begin;

-- ---------------------------------------------------------------------------
-- CBJ-CSF: Central Bank of Jordan — Cyber Security Framework and Cyber Risk Instructions (18 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('CBJ-CSF', 'CBJ Cyber Security', 'Central Bank of Jordan — Cyber Security Framework and Cyber Risk Instructions', 'البنك المركزي الأردني — إطار الأمن السيبراني وتعليمات إدارة المخاطر السيبرانية', 'Central Bank of Jordan (CBJ)', 'البنك المركزي الأردني', 'JO', 'cybersecurity', 'Cyber Security Framework (2020) and Cyber Risk Management Instructions', '2020-01-01', 'https://www.cbj.gov.jo', 'CBJ''s cyber security expectations for banks, payment and electronic money institutions, exchange companies and other licensed entities in Jordan, expressed through its Cyber Security Framework, cyber risk management instructions and related circulars (e.g., on incident reporting, cloud and outsourcing). Rows summarize the recurring obligations by theme; verify the current instruction for each theme before formal use.', 'توقعات البنك المركزي الأردني بشأن الأمن السيبراني للبنوك ومؤسسات الدفع والنقود الإلكترونية وشركات الصرافة وسائر الجهات المرخصة في الأردن، المعبر عنها في إطار الأمن السيبراني وتعليمات إدارة المخاطر السيبرانية والتعاميم ذات الصلة (مثل الإبلاغ عن الحوادث والحوسبة السحابية والإسناد). تلخص الصفوف الالتزامات المتكررة حسب الموضوع؛ يجب التحقق من التعليمات السارية لكل موضوع قبل الاستخدام الرسمي.', true, 60)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('CBJ-1.1', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Board responsibility for cyber security', 'مسؤولية مجلس الإدارة عن الأمن السيبراني', 'The board is responsible for approving the cyber security strategy, policy and risk appetite, ensuring adequate resources, and overseeing the cyber security program through periodic reporting.', 'يتحمل مجلس الإدارة مسؤولية اعتماد استراتيجية وسياسة الأمن السيبراني وشهية المخاطر، وضمان الموارد الكافية، والإشراف على برنامج الأمن السيبراني من خلال التقارير الدورية.', null, 'governance', 'high', 'summarized', false, 10),
  ('CBJ-1.2', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Cyber security function and committee', 'وظيفة الأمن السيبراني ولجنة الأمن السيبراني', 'Establish an independent cyber security function headed by a qualified senior officer reporting outside IT operations, and a cyber security committee with a documented charter.', 'إنشاء وظيفة مستقلة للأمن السيبراني يرأسها مسؤول رفيع مؤهل يرتبط خارج عمليات تقنية المعلومات، ولجنة للأمن السيبراني بميثاق موثق.', null, 'governance', 'high', 'summarized', false, 20),
  ('CBJ-1.3', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Cyber security strategy, policy and standards', 'استراتيجية وسياسة ومعايير الأمن السيبراني', 'Maintain an approved cyber security strategy aligned to business objectives, supported by policies and technical standards that are communicated and reviewed at least annually.', 'الاحتفاظ باستراتيجية معتمدة للأمن السيبراني متوافقة مع أهداف الأعمال، مدعومة بسياسات ومعايير تقنية يتم إبلاغها ومراجعتها سنوياً على الأقل.', null, 'governance', 'high', 'summarized', false, 30),
  ('CBJ-1.4', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Cyber risk management', 'إدارة المخاطر السيبرانية', 'Integrate cyber risk into enterprise risk management with a documented methodology, periodic risk assessments (including before new products, channels and material changes), a risk register and treatment plans reported to the board.', 'دمج المخاطر السيبرانية في إدارة المخاطر المؤسسية بمنهجية موثقة وتقييمات دورية (بما في ذلك قبل المنتجات والقنوات الجديدة والتغييرات الجوهرية) وسجل مخاطر وخطط معالجة تُرفع إلى مجلس الإدارة.', null, 'governance', 'high', 'summarized', false, 40),
  ('CBJ-1.5', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Awareness and training', 'التوعية والتدريب', 'Run cyber security awareness for staff, customers and third parties, with specialized training for cyber security and IT staff and board-level briefings.', 'تنفيذ التوعية بالأمن السيبراني للموظفين والعملاء والأطراف الخارجية، مع تدريب متخصص لموظفي الأمن السيبراني وتقنية المعلومات وإحاطات على مستوى مجلس الإدارة.', null, 'preventive', 'medium', 'summarized', false, 50),
  ('CBJ-1.6', 'Governance and Strategy', 'الحوكمة والاستراتيجية', null, null, 'Compliance and independent audit', 'الامتثال والتدقيق المستقل', 'Assess compliance with CBJ cyber security requirements at least annually, subject the cyber security program to independent audit, and report results and remediation to the audit committee and CBJ as required.', 'تقييم الامتثال لمتطلبات البنك المركزي للأمن السيبراني سنوياً على الأقل، وإخضاع برنامج الأمن السيبراني للتدقيق المستقل، ورفع النتائج والمعالجة إلى لجنة التدقيق والبنك المركزي حسب المطلوب.', null, 'detective', 'medium', 'summarized', false, 60),
  ('CBJ-2.1', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Asset management and classification', 'إدارة الأصول والتصنيف', 'Maintain an inventory of information and technology assets with owners, classify information, and protect customer data as confidential.', 'الاحتفاظ بجرد للأصول المعلوماتية والتقنية مع تحديد المالكين، وتصنيف المعلومات، وحماية بيانات العملاء كمعلومات سرية.', null, 'preventive', 'high', 'summarized', false, 70),
  ('CBJ-2.2', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Identity and access management', 'إدارة الهوية والصلاحيات', 'Enforce least privilege, formal access provisioning and periodic review, multi-factor authentication for remote and privileged access, and monitoring of privileged accounts.', 'فرض الحد الأدنى من الصلاحيات، والمنح الرسمي للصلاحيات والمراجعة الدورية، والمصادقة متعددة العناصر للوصول عن بُعد والمميز، ومراقبة الحسابات المميزة.', null, 'preventive', 'high', 'summarized', false, 80),
  ('CBJ-2.3', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Infrastructure and network security', 'أمن البنية التحتية والشبكات', 'Segment networks, protect perimeters, harden systems, deploy malware protection and apply patches within defined timelines based on criticality.', 'عزل الشبكات، وحماية المحيط، وتحصين الأنظمة، ونشر الحماية من البرمجيات الضارة، وتطبيق التحديثات ضمن مدد محددة حسب الأهمية.', null, 'preventive', 'high', 'summarized', false, 90),
  ('CBJ-2.4', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Application and digital channel security', 'أمن التطبيقات والقنوات الرقمية', 'Apply secure development practices and security testing to applications, and protect electronic and mobile banking channels with multi-factor authentication, transaction verification, fraud monitoring and customer awareness.', 'تطبيق ممارسات التطوير الآمن واختبار الأمن على التطبيقات، وحماية القنوات المصرفية الإلكترونية والهاتف المحمول بالمصادقة متعددة العناصر والتحقق من المعاملات ومراقبة الاحتيال وتوعية العملاء.', null, 'preventive', 'high', 'summarized', false, 100),
  ('CBJ-2.5', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Cryptography and data protection', 'التشفير وحماية البيانات', 'Encrypt sensitive data at rest and in transit using approved algorithms, manage keys securely, and apply data leakage prevention.', 'تشفير البيانات الحساسة أثناء التخزين والنقل بخوارزميات معتمدة، وإدارة المفاتيح بشكل آمن، وتطبيق منع تسرب البيانات.', null, 'preventive', 'high', 'summarized', false, 110),
  ('CBJ-2.6', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Vulnerability management and penetration testing', 'إدارة الثغرات واختبار الاختراق', 'Perform regular vulnerability assessments and at least annual penetration tests on critical and internet-facing systems, and remediate findings by risk.', 'إجراء تقييمات دورية للثغرات واختبارات اختراق سنوية على الأقل للأنظمة الحرجة والمتصلة بالإنترنت، ومعالجة الملاحظات وفق المخاطر.', null, 'detective', 'high', 'summarized', false, 120),
  ('CBJ-2.7', 'Protection and Detection', 'الحماية والاكتشاف', null, null, 'Security monitoring and SOC', 'المراقبة الأمنية ومركز العمليات الأمنية', 'Monitor security events from critical systems continuously through a security operations capability, retain logs per CBJ requirements, and use threat intelligence including CBJ and national CERT (JoCERT) advisories.', 'مراقبة الأحداث الأمنية من الأنظمة الحرجة بشكل مستمر من خلال قدرة عمليات أمنية، والاحتفاظ بالسجلات وفق متطلبات البنك المركزي، واستخدام معلومات التهديدات بما فيها تنبيهات البنك المركزي والفريق الوطني (JoCERT).', null, 'detective', 'high', 'summarized', false, 130),
  ('CBJ-3.1', 'Response, Resilience and Third Parties', 'الاستجابة والصمود والأطراف الخارجية', null, null, 'Cyber incident management and CBJ reporting', 'إدارة الحوادث السيبرانية والإبلاغ للبنك المركزي', 'Maintain and test a cyber incident response plan, classify incidents by severity, and report significant cyber incidents to CBJ within the timelines it prescribes, followed by root-cause and remediation reports.', 'الاحتفاظ بخطة للاستجابة للحوادث السيبرانية واختبارها، وتصنيف الحوادث حسب الخطورة، والإبلاغ عن الحوادث السيبرانية الجسيمة للبنك المركزي ضمن المدد التي يحددها، يليها تقارير السبب الجذري والمعالجة.', null, 'corrective', 'high', 'summarized', false, 140),
  ('CBJ-3.2', 'Response, Resilience and Third Parties', 'الاستجابة والصمود والأطراف الخارجية', null, null, 'Business continuity and disaster recovery', 'استمرارية الأعمال والتعافي من الكوارث', 'Maintain business continuity and disaster recovery plans covering cyber scenarios, with an alternate site, defined recovery objectives and at least annual testing reported to the board.', 'الاحتفاظ بخطط لاستمرارية الأعمال والتعافي من الكوارث تغطي السيناريوهات السيبرانية، مع موقع بديل وأهداف استعادة محددة واختبار سنوي على الأقل يُرفع إلى مجلس الإدارة.', null, 'corrective', 'high', 'summarized', false, 150),
  ('CBJ-3.3', 'Response, Resilience and Third Parties', 'الاستجابة والصمود والأطراف الخارجية', null, null, 'Third-party and outsourcing risk', 'مخاطر الأطراف الخارجية والإسناد', 'Assess third parties before engagement, include cyber security, confidentiality, audit and incident notification clauses in contracts, obtain CBJ approval for material outsourcing, and monitor providers continuously.', 'تقييم الأطراف الخارجية قبل التعاقد، وتضمين بنود الأمن السيبراني والسرية والتدقيق والإبلاغ عن الحوادث في العقود، والحصول على موافقة البنك المركزي للإسناد الجوهري، ومراقبة مقدمي الخدمات بشكل مستمر.', null, 'governance', 'high', 'summarized', false, 160),
  ('CBJ-3.4', 'Response, Resilience and Third Parties', 'الاستجابة والصمود والأطراف الخارجية', null, null, 'Cloud computing', 'الحوسبة السحابية', 'Cloud adoption for material systems or customer data requires risk assessment, CBJ approval where applicable, data residency and confidentiality safeguards, encryption, provider assurance and an exit strategy.', 'يتطلب اعتماد الحوسبة السحابية للأنظمة الجوهرية أو بيانات العملاء تقييم المخاطر، وموافقة البنك المركزي عند الاقتضاء، وضمانات بقاء البيانات وسريتها، والتشفير، وتأكيد مقدم الخدمة، واستراتيجية خروج.', null, 'governance', 'high', 'summarized', false, 170),
  ('CBJ-3.5', 'Response, Resilience and Third Parties', 'الاستجابة والصمود والأطراف الخارجية', null, null, 'Customer data protection and privacy', 'حماية بيانات العملاء والخصوصية', 'Protect customer data in line with CBJ confidentiality requirements and Jordan''s Personal Data Protection Law (2023), including consent, purpose limitation, breach notification and data subject rights.', 'حماية بيانات العملاء وفق متطلبات السرية لدى البنك المركزي وقانون حماية البيانات الشخصية الأردني (2023)، بما في ذلك الموافقة وتحديد الغرض والإبلاغ عن الاختراقات وحقوق أصحاب البيانات.', null, 'preventive', 'high', 'summarized', false, 180)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'CBJ-CSF'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- EU-AI-ACT: EU Artificial Intelligence Act — Regulation (EU) 2024/1689 (34 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('EU-AI-ACT', 'EU AI Act', 'EU Artificial Intelligence Act — Regulation (EU) 2024/1689', 'قانون الذكاء الاصطناعي للاتحاد الأوروبي — اللائحة (EU) 2024/1689', 'European Commission — AI Office; national market surveillance authorities', 'المفوضية الأوروبية — مكتب الذكاء الاصطناعي؛ سلطات مراقبة السوق الوطنية', 'EU', 'ai-governance', '2024/1689', '2024-08-01', 'https://eur-lex.europa.eu/eli/reg/2024/1689/oj', 'The world''s first horizontal AI regulation. Risk-based: prohibited practices (applicable from 2 Feb 2025), obligations for general-purpose AI models (from 2 Aug 2025), and a comprehensive regime for high-risk AI systems (largely from 2 Aug 2026, with Annex I product-embedded systems from 2 Aug 2027). Extraterritorial reach: applies to GCC providers placing systems on the EU market and to deployers whose AI output is used in the EU. Rows summarize the operative obligations by article.', 'أول تنظيم أفقي للذكاء الاصطناعي في العالم. قائم على المخاطر: ممارسات محظورة (سارية من 2 فبراير 2025)، والتزامات لنماذج الذكاء الاصطناعي ذات الأغراض العامة (من 2 أغسطس 2025)، ونظام شامل لأنظمة الذكاء الاصطناعي عالية المخاطر (معظمه من 2 أغسطس 2026). ذو نطاق خارج الإقليم: ينطبق على مزودي دول الخليج الذين يطرحون أنظمة في السوق الأوروبية وعلى المستخدمين الذين تُستخدم مخرجات أنظمتهم في الاتحاد الأوروبي.', true, 90)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('Art. 2', 'Scope and Prohibited Practices', 'النطاق والممارسات المحظورة', null, null, 'Scope and extraterritorial application', 'النطاق والتطبيق خارج الإقليم', 'Applies to providers placing AI systems or GPAI models on the EU market regardless of where they are established, to deployers located in the EU, and to providers and deployers in third countries where the output produced by the AI system is used in the EU. Excludes military, national security, pure research and personal non-professional use.', 'ينطبق على المزودين الذين يطرحون أنظمة أو نماذج ذكاء اصطناعي ذات أغراض عامة في السوق الأوروبية بغض النظر عن مكان تأسيسهم، وعلى المستخدمين الموجودين في الاتحاد، وعلى المزودين والمستخدمين في دول ثالثة حين تُستخدم مخرجات النظام في الاتحاد. ويستثني الاستخدامات العسكرية والأمن الوطني والبحث البحت والاستخدام الشخصي غير المهني.', null, 'governance', 'high', 'summarized', false, 10),
  ('Art. 3', 'Scope and Prohibited Practices', 'النطاق والممارسات المحظورة', null, null, 'Key definitions — AI system, provider, deployer', 'التعريفات الرئيسية — نظام الذكاء الاصطناعي والمزود والمستخدم', 'An AI system is a machine-based system that operates with varying autonomy, may exhibit adaptiveness, and infers from input how to generate outputs such as predictions, content, recommendations or decisions. Providers develop or have developed and place on the market; deployers use AI systems under their authority in a professional context.', 'نظام الذكاء الاصطناعي هو نظام قائم على الآلة يعمل بدرجات متفاوتة من الاستقلالية، وقد يُظهر قدرة على التكيف، ويستنتج من المدخلات كيفية توليد مخرجات مثل التنبؤات أو المحتوى أو التوصيات أو القرارات. المزود يطور النظام أو يُطوّره لصالحه ويطرحه في السوق؛ والمستخدم يستعمل النظام تحت سلطته في سياق مهني.', null, 'governance', 'medium', 'summarized', false, 20),
  ('Art. 4', 'Scope and Prohibited Practices', 'النطاق والممارسات المحظورة', null, null, 'AI literacy', 'الإلمام بالذكاء الاصطناعي', 'Providers and deployers must take measures to ensure a sufficient level of AI literacy among their staff and other persons operating and using AI systems on their behalf, taking into account their technical knowledge, context and the persons affected.', 'يجب على المزودين والمستخدمين اتخاذ تدابير لضمان مستوى كافٍ من الإلمام بالذكاء الاصطناعي لدى موظفيهم والأشخاص الآخرين الذين يشغلون ويستخدمون أنظمة الذكاء الاصطناعي نيابة عنهم، مع مراعاة معرفتهم التقنية والسياق والأشخاص المتأثرين.', 'AI literacy training plan and completion records.', 'preventive', 'medium', 'summarized', false, 30),
  ('Art. 5', 'Scope and Prohibited Practices', 'النطاق والممارسات المحظورة', null, null, 'Prohibited AI practices', 'ممارسات الذكاء الاصطناعي المحظورة', 'Prohibits placing on the market or using AI that deploys subliminal or manipulative techniques causing significant harm, exploits vulnerabilities of age, disability or social/economic situation, performs social scoring leading to detrimental treatment, predicts criminal offences solely from profiling, untargeted scraping of facial images, emotion recognition in workplaces and education (except medical/safety), biometric categorization inferring sensitive attributes, and real-time remote biometric identification in public spaces for law enforcement except narrowly defined cases.', 'يُحظر طرح أو استخدام ذكاء اصطناعي يستخدم تقنيات لا شعورية أو تلاعبية تسبب ضرراً جسيماً، أو يستغل نقاط ضعف مرتبطة بالعمر أو الإعاقة أو الوضع الاجتماعي/الاقتصادي، أو يقوم بالتقييم الاجتماعي المؤدي إلى معاملة ضارة، أو يتنبأ بالجرائم اعتماداً على التنميط فقط، أو يجمع صور الوجوه بشكل عشوائي، أو يتعرف على المشاعر في أماكن العمل والتعليم (باستثناء الأغراض الطبية/السلامة)، أو يصنف الأشخاص بيومترياً لاستنتاج سمات حساسة، أو يستخدم التعرف البيومتري عن بُعد في الوقت الفعلي في الأماكن العامة لأغراض إنفاذ القانون إلا في حالات محددة بدقة.', 'AI use-case inventory screened against Article 5.', 'preventive', 'high', 'summarized', false, 40),
  ('Art. 6', 'High-Risk AI Systems — Classification', 'أنظمة الذكاء الاصطناعي عالية المخاطر — التصنيف', null, null, 'Classification rules for high-risk AI systems', 'قواعد تصنيف الأنظمة عالية المخاطر', 'An AI system is high-risk if it is a safety component of, or is itself, a product covered by Annex I EU harmonization legislation requiring third-party conformity assessment, or if it falls within an Annex III use case — unless it does not pose a significant risk of harm (narrow procedural task, improving a prior human activity, detecting decision patterns, or preparatory tasks), which the provider must document.', 'يُعد النظام عالي المخاطر إذا كان مكوناً للسلامة في منتج مشمول بتشريعات التوافق الأوروبية في الملحق الأول أو كان هو المنتج نفسه، أو إذا كان ضمن حالات الاستخدام في الملحق الثالث — ما لم يكن لا يشكل خطراً كبيراً بالضرر (مهمة إجرائية ضيقة، أو تحسين نشاط بشري سابق، أو اكتشاف أنماط القرارات، أو مهام تحضيرية)، وهو ما يجب على المزود توثيقه.', 'Documented classification assessment per system.', 'governance', 'high', 'summarized', false, 50),
  ('Annex III', 'High-Risk AI Systems — Classification', 'أنظمة الذكاء الاصطناعي عالية المخاطر — التصنيف', null, null, 'High-risk use cases', 'حالات الاستخدام عالية المخاطر', 'High-risk areas include: biometrics (remote identification, categorization, emotion recognition); critical infrastructure safety components; education and vocational training (admission, evaluation, proctoring); employment and workers management (recruitment, promotion, termination, task allocation, monitoring); access to essential private and public services (creditworthiness, life/health insurance pricing, benefits, emergency dispatch); law enforcement; migration, asylum and border control; and administration of justice and democratic processes.', 'تشمل المجالات عالية المخاطر: القياسات الحيوية (التعرف عن بُعد، التصنيف، التعرف على المشاعر)؛ ومكونات السلامة في البنية التحتية الحرجة؛ والتعليم والتدريب المهني (القبول، التقييم، المراقبة)؛ والتوظيف وإدارة العاملين (التوظيف، الترقية، الإنهاء، توزيع المهام، المراقبة)؛ والوصول إلى الخدمات الأساسية الخاصة والعامة (الجدارة الائتمانية، تسعير تأمين الحياة/الصحة، المزايا، توجيه الطوارئ)؛ وإنفاذ القانون؛ والهجرة واللجوء ومراقبة الحدود؛ وإدارة العدالة والعمليات الديمقراطية.', null, 'governance', 'high', 'summarized', false, 60),
  ('Art. 9', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Risk management system', 'نظام إدارة المخاطر', 'Establish, implement, document and maintain a continuous, iterative risk management system across the entire lifecycle: identify known and reasonably foreseeable risks to health, safety and fundamental rights, estimate and evaluate risks including from reasonably foreseeable misuse, evaluate post-market data, and adopt targeted risk management measures so residual risk is acceptable. Testing must be performed against defined metrics, including in real-world conditions where appropriate, and consider impacts on minors and vulnerable groups.', 'إنشاء وتنفيذ وتوثيق وصيانة نظام مستمر ومتكرر لإدارة المخاطر عبر دورة الحياة بأكملها: تحديد المخاطر المعروفة والمتوقعة بشكل معقول على الصحة والسلامة والحقوق الأساسية، وتقدير وتقييم المخاطر بما فيها الناتجة عن سوء الاستخدام المتوقع، وتقييم بيانات ما بعد التسويق، واعتماد تدابير مستهدفة بحيث يكون الخطر المتبقي مقبولاً. ويجب إجراء الاختبارات وفق مقاييس محددة، بما في ذلك في ظروف واقعية عند الاقتضاء، ومراعاة الآثار على القاصرين والفئات الضعيفة.', 'Risk management file, residual risk acceptance, test protocols.', 'governance', 'high', 'summarized', false, 70),
  ('Art. 10', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Data and data governance', 'البيانات وحوكمة البيانات', 'Training, validation and testing datasets must be subject to data governance practices covering design choices, data origin and collection, preparation (labelling, cleaning, enrichment), assumptions, availability and suitability assessment, bias examination and mitigation, and identification of data gaps. Datasets must be relevant, sufficiently representative, and to the best extent possible free of errors and complete, with appropriate statistical properties for the intended persons and context. Special-category data may be processed for bias detection only under strict safeguards.', 'يجب أن تخضع مجموعات بيانات التدريب والتحقق والاختبار لممارسات حوكمة تغطي خيارات التصميم، ومصدر البيانات وجمعها، وإعدادها (الوسم، التنظيف، الإثراء)، والافتراضات، وتقييم التوافر والملاءمة، وفحص التحيز والتخفيف منه، وتحديد فجوات البيانات. ويجب أن تكون البيانات ذات صلة وممثلة بشكل كافٍ وخالية من الأخطاء ومكتملة قدر الإمكان، وذات خصائص إحصائية مناسبة للأشخاص والسياق المستهدف. ولا يجوز معالجة البيانات ذات الفئة الخاصة لاكتشاف التحيز إلا وفق ضمانات صارمة.', 'Dataset documentation (datasheets), bias assessment reports.', 'preventive', 'high', 'summarized', false, 80),
  ('Art. 11', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Technical documentation', 'الوثائق التقنية', 'Draw up technical documentation before placing on the market and keep it up to date, demonstrating compliance with Section 2 and containing at minimum the elements in Annex IV (general description, development process, monitoring and control, risk management, changes, standards applied, EU declaration of conformity, post-market plan). SMEs may use a simplified form.', 'إعداد الوثائق التقنية قبل الطرح في السوق وتحديثها باستمرار، بحيث تثبت الامتثال للقسم الثاني وتتضمن كحد أدنى عناصر الملحق الرابع (الوصف العام، عملية التطوير، المراقبة والتحكم، إدارة المخاطر، التغييرات، المعايير المطبقة، إعلان المطابقة الأوروبي، خطة ما بعد التسويق). ويجوز للمنشآت الصغيرة والمتوسطة استخدام نموذج مبسط.', 'Annex IV technical file.', 'governance', 'high', 'summarized', false, 90),
  ('Art. 12', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Record-keeping (logging)', 'حفظ السجلات (التسجيل)', 'High-risk AI systems must technically allow automatic recording of events (logs) over their lifetime, enabling traceability of functioning, identification of situations that may present risk or lead to substantial modification, post-market monitoring and deployer monitoring of operation.', 'يجب أن تتيح الأنظمة عالية المخاطر تقنياً التسجيل التلقائي للأحداث طوال عمرها، بما يمكّن من تتبع الأداء، وتحديد الحالات التي قد تشكل خطراً أو تؤدي إلى تعديل جوهري، والمراقبة بعد التسويق، ومراقبة المستخدم للتشغيل.', 'Logging specification, log retention configuration.', 'detective', 'high', 'summarized', false, 100),
  ('Art. 13', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Transparency and provision of information to deployers', 'الشفافية وتوفير المعلومات للمستخدمين', 'Design systems so deployers can interpret outputs and use them appropriately, and provide instructions for use including the provider''s identity, the intended purpose, level of accuracy, robustness and cybersecurity, known or foreseeable risks, human oversight measures, computational and hardware resources, expected lifetime and maintenance, and the log collection mechanisms.', 'تصميم الأنظمة بحيث يتمكن المستخدمون من تفسير المخرجات واستخدامها بشكل مناسب، وتوفير تعليمات الاستخدام التي تشمل هوية المزود، والغرض المقصود، ومستوى الدقة والمتانة والأمن السيبراني، والمخاطر المعروفة أو المتوقعة، وتدابير الإشراف البشري، والموارد الحاسوبية والعتادية، والعمر المتوقع والصيانة، وآليات جمع السجلات.', 'Instructions for use, model card.', 'preventive', 'high', 'summarized', false, 110),
  ('Art. 14', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Human oversight', 'الإشراف البشري', 'Design systems with appropriate human-machine interface tools so they can be effectively overseen by natural persons during use. Oversight measures must enable the overseer to understand capacities and limitations, remain aware of automation bias, correctly interpret output, decide not to use or override the output, and intervene or halt the system. For remote biometric identification, no action may be taken on the basis of identification unless verified by at least two competent persons.', 'تصميم الأنظمة بأدوات واجهة مناسبة بين الإنسان والآلة بحيث يمكن الإشراف عليها فعلياً من قبل أشخاص طبيعيين أثناء الاستخدام. ويجب أن تمكّن تدابير الإشراف المشرف من فهم القدرات والقيود، والانتباه لتحيز الأتمتة، وتفسير المخرجات بشكل صحيح، وتقرير عدم استخدام المخرجات أو تجاوزها، والتدخل أو إيقاف النظام. وفي التعرف البيومتري عن بُعد، لا يجوز اتخاذ إجراء بناءً على التعرف ما لم يتحقق منه شخصان مختصان على الأقل.', 'Human oversight design documentation, operator training.', 'preventive', 'high', 'summarized', false, 120),
  ('Art. 15', 'High-Risk AI Systems — Requirements (Chapter III, Section 2)', 'أنظمة الذكاء الاصطناعي عالية المخاطر — المتطلبات', null, null, 'Accuracy, robustness and cybersecurity', 'الدقة والمتانة والأمن السيبراني', 'Achieve appropriate levels of accuracy, robustness and cybersecurity consistently throughout the lifecycle; declare accuracy levels and metrics in the instructions; build resilience to errors, faults and inconsistencies (including technical redundancy and fail-safe plans); address feedback loops in continually learning systems; and protect against AI-specific attacks such as data poisoning, model poisoning, adversarial examples and confidentiality attacks.', 'تحقيق مستويات مناسبة من الدقة والمتانة والأمن السيبراني باستمرار طوال دورة الحياة؛ والإعلان عن مستويات الدقة ومقاييسها في التعليمات؛ وبناء المرونة تجاه الأخطاء والأعطال والتناقضات (بما في ذلك التكرار التقني وخطط الأمان عند الفشل)؛ ومعالجة حلقات التغذية الراجعة في الأنظمة دائمة التعلم؛ والحماية من الهجمات الخاصة بالذكاء الاصطناعي مثل تسميم البيانات والنماذج والأمثلة العدائية وهجمات السرية.', 'Accuracy metrics, adversarial testing reports, security assessment.', 'preventive', 'high', 'summarized', false, 130),
  ('Art. 16', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Obligations of providers of high-risk AI systems', 'التزامات مزودي الأنظمة عالية المخاطر', 'Providers must ensure compliance with Section 2 requirements, indicate their name and contact details on the system, have a quality management system, keep documentation and logs, undergo conformity assessment, draw up the EU declaration of conformity, affix the CE marking, register in the EU database, take corrective actions, demonstrate compliance to authorities on request, and ensure accessibility requirements.', 'يجب على المزودين ضمان الامتثال لمتطلبات القسم الثاني، وبيان اسمهم وبيانات الاتصال على النظام، وامتلاك نظام لإدارة الجودة، والاحتفاظ بالوثائق والسجلات، والخضوع لتقييم المطابقة، وإعداد إعلان المطابقة الأوروبي، ووضع علامة CE، والتسجيل في قاعدة بيانات الاتحاد، واتخاذ الإجراءات التصحيحية، وإثبات الامتثال للسلطات عند الطلب، وضمان متطلبات إمكانية الوصول.', null, 'governance', 'high', 'summarized', false, 140),
  ('Art. 17', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Quality management system', 'نظام إدارة الجودة', 'Providers must put in place a documented quality management system covering regulatory compliance strategy, design and development controls, testing and validation procedures, technical specifications and standards, data management, the risk management system, post-market monitoring, incident reporting, communication with authorities, record-keeping, resource management and an accountability framework.', 'يجب على المزودين وضع نظام موثق لإدارة الجودة يغطي استراتيجية الامتثال التنظيمي، وضوابط التصميم والتطوير، وإجراءات الاختبار والتحقق، والمواصفات والمعايير التقنية، وإدارة البيانات، ونظام إدارة المخاطر، والمراقبة بعد التسويق، والإبلاغ عن الحوادث، والتواصل مع السلطات، وحفظ السجلات، وإدارة الموارد، وإطار المساءلة.', 'QMS manual (may be integrated with ISO 9001 / ISO 42001).', 'governance', 'high', 'summarized', false, 150),
  ('Art. 18', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Documentation retention', 'الاحتفاظ بالوثائق', 'Providers must keep the technical documentation, QMS documentation, notified-body approvals and the EU declaration of conformity at the disposal of national authorities for 10 years after the system is placed on the market.', 'يجب على المزودين الاحتفاظ بالوثائق التقنية ووثائق نظام إدارة الجودة وموافقات الجهات المُخطَرة وإعلان المطابقة الأوروبي تحت تصرف السلطات الوطنية لمدة 10 سنوات بعد طرح النظام في السوق.', null, 'governance', 'medium', 'summarized', false, 160),
  ('Art. 19', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Automatically generated logs', 'السجلات المولدة تلقائياً', 'Providers must keep automatically generated logs under their control for a period appropriate to the intended purpose, of at least six months, unless otherwise provided by applicable law.', 'يجب على المزودين الاحتفاظ بالسجلات المولدة تلقائياً الخاضعة لسيطرتهم لمدة مناسبة للغرض المقصود لا تقل عن ستة أشهر، ما لم ينص القانون المعمول به على خلاف ذلك.', null, 'detective', 'medium', 'summarized', false, 170),
  ('Art. 20', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Corrective actions and duty of information', 'الإجراءات التصحيحية وواجب الإبلاغ', 'Providers who consider a system non-compliant must immediately take corrective action to bring it into conformity, withdraw, disable or recall it, and inform distributors, deployers, authorized representatives and importers. Where the system presents a risk, they must investigate and inform the market surveillance authorities.', 'يجب على المزودين الذين يرون أن النظام غير ممتثل اتخاذ إجراءات تصحيحية فورية لجعله مطابقاً أو سحبه أو تعطيله أو استدعائه، وإبلاغ الموزعين والمستخدمين والممثلين المعتمدين والمستوردين. وإذا كان النظام يشكل خطراً، يجب التحقيق وإبلاغ سلطات مراقبة السوق.', null, 'corrective', 'high', 'summarized', false, 180),
  ('Art. 22', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Authorized representative for non-EU providers', 'الممثل المعتمد للمزودين من خارج الاتحاد', 'Providers established outside the EU must appoint, by written mandate, an authorized representative established in the EU before making high-risk AI systems available, who verifies the declaration of conformity and technical documentation, keeps them available to authorities and cooperates with them.', 'يجب على المزودين المؤسسين خارج الاتحاد تعيين ممثل معتمد مؤسس في الاتحاد بتفويض كتابي قبل إتاحة الأنظمة عالية المخاطر، يتحقق من إعلان المطابقة والوثائق التقنية ويبقيها متاحة للسلطات ويتعاون معها.', 'Signed mandate with EU representative.', 'governance', 'high', 'summarized', false, 190),
  ('Art. 25', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Responsibilities along the AI value chain', 'المسؤوليات على امتداد سلسلة قيمة الذكاء الاصطناعي', 'A distributor, importer, deployer or other third party becomes the provider of a high-risk system if they put their name or trademark on it, make a substantial modification, or modify the intended purpose so that it becomes high-risk. Providers of high-risk systems and third-party suppliers of components must conclude written agreements specifying information, capabilities and technical access needed for compliance.', 'يصبح الموزع أو المستورد أو المستخدم أو أي طرف ثالث مزوداً للنظام عالي المخاطر إذا وضع اسمه أو علامته التجارية عليه، أو أجرى تعديلاً جوهرياً، أو غيّر الغرض المقصود بحيث يصبح عالي المخاطر. ويجب على مزودي الأنظمة عالية المخاطر وموردي المكونات من الأطراف الثالثة إبرام اتفاقيات كتابية تحدد المعلومات والقدرات والوصول التقني اللازم للامتثال.', null, 'governance', 'medium', 'summarized', false, 200),
  ('Art. 26', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Obligations of deployers of high-risk AI systems', 'التزامات مستخدمي الأنظمة عالية المخاطر', 'Deployers must use systems in accordance with the instructions, assign human oversight to competent persons with the necessary authority and training, ensure input data is relevant and representative where under their control, monitor operation and inform the provider and authorities of risks or serious incidents, keep logs for at least six months, inform workers'' representatives before deploying in the workplace, inform affected natural persons where decisions are made about them, and where applicable perform a data protection impact assessment.', 'يجب على المستخدمين استخدام الأنظمة وفق التعليمات، وإسناد الإشراف البشري إلى أشخاص مختصين يتمتعون بالصلاحية والتدريب اللازمين، وضمان أن تكون بيانات الإدخال ذات صلة وممثلة حين تكون تحت سيطرتهم، ومراقبة التشغيل وإبلاغ المزود والسلطات بالمخاطر أو الحوادث الجسيمة، والاحتفاظ بالسجلات لمدة لا تقل عن ستة أشهر، وإبلاغ ممثلي العاملين قبل النشر في مكان العمل، وإبلاغ الأشخاص الطبيعيين المتأثرين عند اتخاذ قرارات بشأنهم، وإجراء تقييم أثر حماية البيانات عند الاقتضاء.', 'Deployment procedure, oversight assignments, DPIA.', 'governance', 'high', 'summarized', false, 210),
  ('Art. 27', 'Obligations of Providers and Deployers', 'التزامات المزودين والمستخدمين', null, null, 'Fundamental rights impact assessment', 'تقييم الأثر على الحقوق الأساسية', 'Before deploying an Annex III high-risk system, deployers that are public bodies or private entities providing public services, and deployers using systems for creditworthiness or life/health insurance risk assessment, must perform a fundamental rights impact assessment describing the processes, period and frequency of use, categories of persons affected, specific risks of harm, human oversight measures, and measures if risks materialize, and notify the market surveillance authority.', 'قبل نشر نظام عالي المخاطر مشمول بالملحق الثالث، يجب على المستخدمين من الجهات العامة أو الكيانات الخاصة التي تقدم خدمات عامة، والمستخدمين لأغراض الجدارة الائتمانية أو تقييم مخاطر تأمين الحياة/الصحة، إجراء تقييم للأثر على الحقوق الأساسية يصف العمليات ومدة وتكرار الاستخدام وفئات الأشخاص المتأثرين ومخاطر الضرر المحددة وتدابير الإشراف البشري والتدابير في حال تحقق المخاطر، وإخطار سلطة مراقبة السوق.', 'FRIA report and notification record.', 'governance', 'high', 'summarized', false, 220),
  ('Art. 43', 'Conformity, Registration and Transparency', 'المطابقة والتسجيل والشفافية', null, null, 'Conformity assessment', 'تقييم المطابقة', 'Providers of Annex III high-risk systems generally follow the internal-control conformity assessment procedure (Annex VI); biometric systems require third-party assessment by a notified body (Annex VII) unless harmonized standards are fully applied. Annex I product systems follow the sectoral legislation''s procedure. A new assessment is required after substantial modification.', 'يتبع مزودو الأنظمة عالية المخاطر في الملحق الثالث عموماً إجراء تقييم المطابقة بالرقابة الداخلية (الملحق السادس)؛ وتتطلب الأنظمة البيومترية تقييماً من طرف ثالث بواسطة جهة مُخطَرة (الملحق السابع) ما لم تُطبق المعايير المنسقة بالكامل. وتتبع أنظمة منتجات الملحق الأول إجراء التشريع القطاعي. ويلزم تقييم جديد بعد أي تعديل جوهري.', null, 'governance', 'high', 'summarized', false, 230),
  ('Art. 47', 'Conformity, Registration and Transparency', 'المطابقة والتسجيل والشفافية', null, null, 'EU declaration of conformity', 'إعلان المطابقة الأوروبي', 'Providers must draw up a written, machine-readable EU declaration of conformity for each high-risk system, keep it for 10 years, and continuously update it; it must contain the Annex V information and be translated into languages required by the Member States concerned.', 'يجب على المزودين إعداد إعلان مطابقة أوروبي كتابي قابل للقراءة آلياً لكل نظام عالي المخاطر، والاحتفاظ به لمدة 10 سنوات وتحديثه باستمرار؛ ويجب أن يتضمن معلومات الملحق الخامس ويُترجم إلى اللغات التي تطلبها الدول الأعضاء المعنية.', null, 'governance', 'medium', 'summarized', false, 240),
  ('Art. 49', 'Conformity, Registration and Transparency', 'المطابقة والتسجيل والشفافية', null, null, 'Registration in the EU database', 'التسجيل في قاعدة بيانات الاتحاد', 'Before placing an Annex III high-risk system on the market or putting it into service, the provider (or authorized representative) must register themselves and the system in the EU database; deployers that are public authorities must also register their use. Providers concluding a system is not high-risk under Article 6(3) must register that assessment.', 'قبل طرح نظام عالي المخاطر مشمول بالملحق الثالث في السوق أو تشغيله، يجب على المزود (أو الممثل المعتمد) تسجيل نفسه والنظام في قاعدة بيانات الاتحاد؛ ويجب على المستخدمين من السلطات العامة تسجيل استخدامهم أيضاً. ويجب على المزودين الذين يخلصون إلى أن النظام ليس عالي المخاطر بموجب المادة 6(3) تسجيل هذا التقييم.', null, 'governance', 'medium', 'summarized', false, 250),
  ('Art. 50', 'Conformity, Registration and Transparency', 'المطابقة والتسجيل والشفافية', null, null, 'Transparency obligations for certain AI systems', 'التزامات الشفافية لأنظمة معينة', 'Providers must ensure AI systems interacting directly with persons inform them they are interacting with AI unless obvious; synthetic audio, image, video or text output must be marked in a machine-readable, detectable format. Deployers of emotion recognition or biometric categorization must inform exposed persons; deployers of deepfakes must disclose the content is artificially generated; AI-generated text published to inform the public on matters of public interest must be disclosed unless human-reviewed with editorial responsibility.', 'يجب على المزودين ضمان أن تُعلم أنظمة الذكاء الاصطناعي التي تتفاعل مباشرة مع الأشخاص بأنهم يتفاعلون مع ذكاء اصطناعي ما لم يكن ذلك واضحاً؛ ويجب وسم المخرجات الاصطناعية من صوت وصورة وفيديو ونص بصيغة قابلة للقراءة آلياً والاكتشاف. ويجب على مستخدمي أنظمة التعرف على المشاعر أو التصنيف البيومتري إعلام الأشخاص المعرضين؛ وعلى مستخدمي التزييف العميق الإفصاح بأن المحتوى مولد اصطناعياً؛ ويجب الإفصاح عن النصوص المولدة بالذكاء الاصطناعي المنشورة لإعلام الجمهور بشأن مسائل المصلحة العامة ما لم تخضع لمراجعة بشرية بمسؤولية تحريرية.', 'Disclosure UX, watermarking/provenance implementation.', 'preventive', 'high', 'summarized', false, 260),
  ('Art. 53', 'General-Purpose AI Models', 'نماذج الذكاء الاصطناعي ذات الأغراض العامة', null, null, 'Obligations for providers of GPAI models', 'التزامات مزودي النماذج ذات الأغراض العامة', 'Providers of general-purpose AI models must draw up and maintain technical documentation (Annex XI) including training and testing process and evaluation results, provide downstream providers with information enabling them to understand capabilities and limitations and comply with their own obligations (Annex XII), put in place a policy to comply with EU copyright law including reservations of rights, and publish a sufficiently detailed summary of the content used for training. Open-source models are partially exempt unless they present systemic risk.', 'يجب على مزودي نماذج الذكاء الاصطناعي ذات الأغراض العامة إعداد وصيانة الوثائق التقنية (الملحق الحادي عشر) بما في ذلك عملية التدريب والاختبار ونتائج التقييم، وتزويد المزودين اللاحقين بمعلومات تمكنهم من فهم القدرات والقيود والامتثال لالتزاماتهم (الملحق الثاني عشر)، ووضع سياسة للامتثال لقانون حقوق النشر الأوروبي بما في ذلك حجز الحقوق، ونشر ملخص مفصل بما يكفي للمحتوى المستخدم في التدريب. وتُعفى النماذج مفتوحة المصدر جزئياً ما لم تشكل خطراً نظامياً.', null, 'governance', 'high', 'summarized', false, 270),
  ('Art. 54', 'General-Purpose AI Models', 'نماذج الذكاء الاصطناعي ذات الأغراض العامة', null, null, 'Authorized representatives of GPAI providers', 'الممثلون المعتمدون لمزودي النماذج ذات الأغراض العامة', 'Providers of GPAI models established outside the EU must appoint an authorized representative in the EU before placing the model on the market, mandated to verify and keep documentation, provide information to the AI Office and cooperate with authorities.', 'يجب على مزودي النماذج ذات الأغراض العامة المؤسسين خارج الاتحاد تعيين ممثل معتمد في الاتحاد قبل طرح النموذج في السوق، مفوض بالتحقق من الوثائق والاحتفاظ بها وتقديم المعلومات لمكتب الذكاء الاصطناعي والتعاون مع السلطات.', null, 'governance', 'medium', 'summarized', false, 280),
  ('Art. 51–52', 'General-Purpose AI Models', 'نماذج الذكاء الاصطناعي ذات الأغراض العامة', null, null, 'GPAI models with systemic risk — classification', 'النماذج ذات الخطر النظامي — التصنيف', 'A GPAI model is classified as having systemic risk if it has high-impact capabilities evaluated on technical tools and benchmarks, presumed where cumulative training compute exceeds 10^25 FLOPs, or by Commission decision. Providers must notify the Commission within two weeks of meeting the threshold.', 'يُصنف النموذج ذو الأغراض العامة على أنه ذو خطر نظامي إذا كانت له قدرات عالية التأثير تُقيَّم بأدوات ومقاييس تقنية، ويُفترض ذلك عندما تتجاوز قوة الحوسبة التراكمية للتدريب 10^25 عملية فاصلة عائمة، أو بقرار من المفوضية. ويجب على المزودين إخطار المفوضية خلال أسبوعين من استيفاء الحد.', null, 'governance', 'medium', 'summarized', false, 290),
  ('Art. 55', 'General-Purpose AI Models', 'نماذج الذكاء الاصطناعي ذات الأغراض العامة', null, null, 'Obligations for GPAI models with systemic risk', 'التزامات النماذج ذات الخطر النظامي', 'In addition to Article 53, providers must perform model evaluation with standardized protocols including adversarial testing, assess and mitigate possible systemic risks at Union level, track, document and report serious incidents and corrective measures to the AI Office without undue delay, and ensure an adequate level of cybersecurity protection for the model and its physical infrastructure.', 'بالإضافة إلى المادة 53، يجب على المزودين إجراء تقييم للنموذج ببروتوكولات موحدة تشمل الاختبار العدائي، وتقييم المخاطر النظامية المحتملة على مستوى الاتحاد والتخفيف منها، وتتبع وتوثيق وإبلاغ مكتب الذكاء الاصطناعي بالحوادث الجسيمة والتدابير التصحيحية دون تأخير، وضمان مستوى مناسب من الحماية السيبرانية للنموذج وبنيته التحتية المادية.', 'Red-teaming reports, systemic risk assessment, incident log.', 'preventive', 'high', 'summarized', false, 300),
  ('Art. 72', 'Post-Market Monitoring, Incidents and Enforcement', 'المراقبة بعد التسويق والحوادث والإنفاذ', null, null, 'Post-market monitoring by providers', 'المراقبة بعد التسويق من قبل المزودين', 'Providers must establish and document a post-market monitoring system proportionate to the nature of the AI system, actively and systematically collecting and analyzing performance data throughout the lifetime (including from deployers) to evaluate continuous compliance, based on a post-market monitoring plan included in the technical documentation.', 'يجب على المزودين إنشاء وتوثيق نظام للمراقبة بعد التسويق يتناسب مع طبيعة النظام، يجمع ويحلل بيانات الأداء بشكل نشط ومنهجي طوال العمر (بما في ذلك من المستخدمين) لتقييم الامتثال المستمر، بناءً على خطة مراقبة مضمنة في الوثائق التقنية.', null, 'detective', 'high', 'summarized', false, 310),
  ('Art. 73', 'Post-Market Monitoring, Incidents and Enforcement', 'المراقبة بعد التسويق والحوادث والإنفاذ', null, null, 'Reporting of serious incidents', 'الإبلاغ عن الحوادث الجسيمة', 'Providers of high-risk systems must report serious incidents to the market surveillance authority of the Member State where the incident occurred immediately after establishing a causal link, and no later than 15 days after awareness (2 days for widespread infringement or critical infrastructure disruption; 10 days for death), followed by investigation, risk assessment and corrective action.', 'يجب على مزودي الأنظمة عالية المخاطر إبلاغ سلطة مراقبة السوق في الدولة العضو التي وقع فيها الحادث الجسيم فور إثبات العلاقة السببية، وفي موعد لا يتجاوز 15 يوماً من العلم (يومان للانتهاك واسع النطاق أو تعطل البنية التحتية الحرجة؛ و10 أيام في حالة الوفاة)، يليه التحقيق وتقييم المخاطر والإجراء التصحيحي.', 'Serious incident procedure and reports.', 'corrective', 'high', 'summarized', false, 320),
  ('Art. 99', 'Post-Market Monitoring, Incidents and Enforcement', 'المراقبة بعد التسويق والحوادث والإنفاذ', null, null, 'Penalties', 'العقوبات', 'Non-compliance with prohibited practices: fines up to EUR 35 million or 7% of worldwide annual turnover, whichever is higher. Non-compliance with other obligations (providers, deployers, importers, distributors, notified bodies): up to EUR 15 million or 3%. Supplying incorrect or misleading information to authorities: up to EUR 7.5 million or 1%. Lower caps apply to SMEs.', 'عدم الامتثال للممارسات المحظورة: غرامات تصل إلى 35 مليون يورو أو 7% من إجمالي الإيرادات السنوية العالمية، أيهما أعلى. وعدم الامتثال للالتزامات الأخرى (المزودين والمستخدمين والمستوردين والموزعين والجهات المُخطَرة): حتى 15 مليون يورو أو 3%. وتقديم معلومات غير صحيحة أو مضللة للسلطات: حتى 7.5 مليون يورو أو 1%. وتُطبق حدود أدنى على المنشآت الصغيرة والمتوسطة.', null, 'governance', 'high', 'summarized', false, 330),
  ('Art. 113', 'Post-Market Monitoring, Incidents and Enforcement', 'المراقبة بعد التسويق والحوادث والإنفاذ', null, null, 'Entry into force and application timeline', 'الدخول حيز النفاذ والجدول الزمني للتطبيق', 'In force 1 August 2024. Prohibited practices and AI literacy apply from 2 February 2025; GPAI obligations, governance and penalties from 2 August 2025; the majority of provisions including Annex III high-risk obligations from 2 August 2026; Annex I product-embedded high-risk obligations from 2 August 2027.', 'دخل حيز النفاذ في 1 أغسطس 2024. تسري الممارسات المحظورة والإلمام بالذكاء الاصطناعي من 2 فبراير 2025؛ والتزامات النماذج ذات الأغراض العامة والحوكمة والعقوبات من 2 أغسطس 2025؛ ومعظم الأحكام بما فيها التزامات الملحق الثالث عالية المخاطر من 2 أغسطس 2026؛ والتزامات الملحق الأول للمنتجات من 2 أغسطس 2027.', null, 'governance', 'medium', 'summarized', false, 340)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'EU-AI-ACT'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- ISO-27001: ISO/IEC 27001:2022 — Information Security Management Systems (Annex A controls) (93 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('ISO-27001', 'ISO/IEC 27001:2022', 'ISO/IEC 27001:2022 — Information Security Management Systems (Annex A controls)', 'آيزو/آي إي سي 27001:2022 — أنظمة إدارة أمن المعلومات (ضوابط الملحق أ)', 'International Organization for Standardization (ISO) / IEC', 'المنظمة الدولية للتوحيد القياسي / اللجنة الكهروتقنية الدولية', 'INTL', 'information-security', '2022', '2022-10-25', 'https://www.iso.org/standard/27001', 'The international standard for information security management systems (ISMS). Annex A lists 93 reference controls across four themes — Organizational (37), People (8), Physical (14) and Technological (34). Control titles follow the standard; requirement text here is AETHER''s paraphrase of each control''s intent, not the copyrighted ISO wording. Certification requires the licensed standard.', 'المعيار الدولي لأنظمة إدارة أمن المعلومات. يتضمن الملحق أ 93 ضابطاً مرجعياً موزعة على أربعة محاور — تنظيمية (37)، الأفراد (8)، مادية (14)، تقنية (34). عناوين الضوابط وفق المعيار، أما نص المتطلبات فهو صياغة AETHER لمقصد كل ضابط وليس النص الأصلي المحمي بحقوق النشر.', false, 70)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('A.5.1', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Policies for information security', 'سياسات أمن المعلومات', 'Define an information security policy and supporting topic-specific policies, have them approved by management, publish them, communicate them to personnel and relevant external parties, and review them at planned intervals or after significant change.', 'تحديد سياسة أمن المعلومات والسياسات الموضوعية الداعمة لها، واعتمادها من الإدارة، ونشرها، وإبلاغها للعاملين والأطراف الخارجية ذات العلاقة، ومراجعتها على فترات مخططة أو عند حدوث تغيير جوهري.', 'Approved policy set, communication records, review log.', 'governance', 'high', 'paraphrased', false, 10),
  ('A.5.2', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security roles and responsibilities', 'أدوار ومسؤوليات أمن المعلومات', 'Define and allocate information security roles and responsibilities according to the organization''s needs.', 'تحديد أدوار ومسؤوليات أمن المعلومات وتوزيعها وفقاً لاحتياجات المنظمة.', null, 'governance', 'high', 'paraphrased', false, 20),
  ('A.5.3', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Segregation of duties', 'فصل المهام', 'Segregate conflicting duties and areas of responsibility to reduce the risk of unauthorized or unintentional modification or misuse of assets.', 'فصل المهام ومجالات المسؤولية المتعارضة للحد من مخاطر التعديل أو إساءة الاستخدام غير المصرح بهما أو غير المقصودين للأصول.', null, 'preventive', 'high', 'paraphrased', false, 30),
  ('A.5.4', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Management responsibilities', 'مسؤوليات الإدارة', 'Management requires all personnel to apply information security in accordance with the established policies, topic-specific policies and procedures.', 'تُلزم الإدارة جميع العاملين بتطبيق أمن المعلومات وفقاً للسياسات والإجراءات المعتمدة.', null, 'governance', 'medium', 'paraphrased', false, 40),
  ('A.5.5', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Contact with authorities', 'التواصل مع الجهات الرسمية', 'Establish and maintain contact with relevant authorities (regulators, law enforcement, supervisory bodies).', 'إنشاء قنوات تواصل مع الجهات الرسمية ذات العلاقة (الجهات التنظيمية وجهات إنفاذ القانون) والمحافظة عليها.', null, 'governance', 'medium', 'paraphrased', false, 50),
  ('A.5.6', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Contact with special interest groups', 'التواصل مع مجموعات الاهتمام المتخصصة', 'Establish and maintain contact with special interest groups, security forums and professional associations.', 'إنشاء قنوات تواصل مع مجموعات الاهتمام المتخصصة ومنتديات الأمن والجمعيات المهنية والمحافظة عليها.', null, 'governance', 'low', 'paraphrased', false, 60),
  ('A.5.7', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Threat intelligence', 'معلومات التهديدات', 'Collect and analyze information about information security threats to produce threat intelligence that informs mitigation.', 'جمع وتحليل المعلومات المتعلقة بتهديدات أمن المعلومات لإنتاج معلومات استباقية توجه إجراءات التخفيف.', null, 'detective', 'medium', 'paraphrased', false, 70),
  ('A.5.8', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security in project management', 'أمن المعلومات في إدارة المشاريع', 'Integrate information security into project management regardless of project type.', 'دمج أمن المعلومات في إدارة المشاريع بغض النظر عن نوع المشروع.', null, 'preventive', 'medium', 'paraphrased', false, 80),
  ('A.5.9', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Inventory of information and other associated assets', 'جرد المعلومات والأصول المرتبطة بها', 'Develop and maintain an inventory of information and other associated assets, including their owners.', 'إعداد جرد للمعلومات والأصول المرتبطة بها والمحافظة عليه، بما في ذلك تحديد مالكيها.', null, 'preventive', 'high', 'paraphrased', false, 90),
  ('A.5.10', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Acceptable use of information and other associated assets', 'الاستخدام المقبول للمعلومات والأصول المرتبطة بها', 'Identify, document and implement rules for the acceptable use and handling of information and other associated assets.', 'تحديد وتوثيق وتطبيق قواعد الاستخدام المقبول للمعلومات والأصول المرتبطة بها والتعامل معها.', null, 'preventive', 'medium', 'paraphrased', false, 100),
  ('A.5.11', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Return of assets', 'إعادة الأصول', 'Personnel and other interested parties return all organizational assets in their possession upon change or termination of employment, contract or agreement.', 'يعيد العاملون والأطراف المعنية جميع أصول المنظمة التي بحوزتهم عند تغيير أو إنهاء العلاقة الوظيفية أو العقد أو الاتفاقية.', null, 'preventive', 'medium', 'paraphrased', false, 110),
  ('A.5.12', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Classification of information', 'تصنيف المعلومات', 'Classify information according to the organization''s needs based on confidentiality, integrity, availability and relevant interested-party requirements.', 'تصنيف المعلومات وفقاً لاحتياجات المنظمة بناءً على السرية والسلامة والتوافر ومتطلبات الأطراف المعنية.', null, 'preventive', 'high', 'paraphrased', false, 120),
  ('A.5.13', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Labelling of information', 'وسم المعلومات', 'Develop and implement procedures for labelling information in accordance with the classification scheme.', 'وضع وتطبيق إجراءات لوسم المعلومات وفقاً لآلية التصنيف المعتمدة.', null, 'preventive', 'medium', 'paraphrased', false, 130),
  ('A.5.14', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information transfer', 'نقل المعلومات', 'Establish rules, procedures or agreements for all types of information transfer within the organization and with external parties.', 'وضع قواعد أو إجراءات أو اتفاقيات لجميع أنواع نقل المعلومات داخل المنظمة ومع الأطراف الخارجية.', null, 'preventive', 'medium', 'paraphrased', false, 140),
  ('A.5.15', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Access control', 'التحكم في الوصول', 'Establish and implement rules to control physical and logical access to information and associated assets based on business and security requirements.', 'وضع وتطبيق قواعد للتحكم في الوصول المادي والمنطقي إلى المعلومات والأصول المرتبطة بها بناءً على متطلبات الأعمال والأمن.', null, 'preventive', 'high', 'paraphrased', false, 150),
  ('A.5.16', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Identity management', 'إدارة الهوية', 'Manage the full life cycle of identities.', 'إدارة دورة الحياة الكاملة للهويات.', null, 'preventive', 'high', 'paraphrased', false, 160),
  ('A.5.17', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Authentication information', 'معلومات المصادقة', 'Control the allocation and management of authentication information through a management process, including advising personnel on appropriate handling.', 'التحكم في تخصيص وإدارة معلومات المصادقة من خلال عملية إدارية، بما في ذلك توجيه العاملين بشأن التعامل السليم معها.', null, 'preventive', 'high', 'paraphrased', false, 170),
  ('A.5.18', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Access rights', 'صلاحيات الوصول', 'Provision, review, modify and remove access rights to information and associated assets in accordance with the access control policy.', 'منح صلاحيات الوصول إلى المعلومات والأصول المرتبطة بها ومراجعتها وتعديلها وإلغاؤها وفقاً لسياسة التحكم في الوصول.', null, 'preventive', 'high', 'paraphrased', false, 180),
  ('A.5.19', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security in supplier relationships', 'أمن المعلومات في العلاقات مع الموردين', 'Define and implement processes and procedures to manage information security risks associated with the use of suppliers'' products or services.', 'تحديد وتطبيق عمليات وإجراءات لإدارة مخاطر أمن المعلومات المرتبطة باستخدام منتجات أو خدمات الموردين.', null, 'governance', 'high', 'paraphrased', false, 190),
  ('A.5.20', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Addressing information security within supplier agreements', 'معالجة أمن المعلومات في اتفاقيات الموردين', 'Establish and agree relevant information security requirements with each supplier based on the type of relationship.', 'تحديد متطلبات أمن المعلومات ذات العلاقة والاتفاق عليها مع كل مورد بناءً على نوع العلاقة.', null, 'preventive', 'high', 'paraphrased', false, 200),
  ('A.5.21', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Managing information security in the ICT supply chain', 'إدارة أمن المعلومات في سلسلة إمداد تقنية المعلومات والاتصالات', 'Define and implement processes to manage information security risks associated with the ICT products and services supply chain.', 'تحديد وتطبيق عمليات لإدارة مخاطر أمن المعلومات المرتبطة بسلسلة إمداد منتجات وخدمات تقنية المعلومات والاتصالات.', null, 'governance', 'medium', 'paraphrased', false, 210),
  ('A.5.22', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Monitoring, review and change management of supplier services', 'مراقبة ومراجعة وإدارة التغيير في خدمات الموردين', 'Regularly monitor, review, evaluate and manage change in supplier information security practices and service delivery.', 'مراقبة ممارسات أمن المعلومات وتقديم الخدمات لدى الموردين ومراجعتها وتقييمها وإدارة التغييرات فيها بانتظام.', null, 'detective', 'medium', 'paraphrased', false, 220),
  ('A.5.23', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security for use of cloud services', 'أمن المعلومات لاستخدام الخدمات السحابية', 'Establish processes for acquisition, use, management and exit from cloud services in accordance with the organization''s information security requirements.', 'وضع عمليات لاقتناء الخدمات السحابية واستخدامها وإدارتها والخروج منها وفقاً لمتطلبات أمن المعلومات في المنظمة.', null, 'governance', 'high', 'paraphrased', false, 230),
  ('A.5.24', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security incident management planning and preparation', 'التخطيط والاستعداد لإدارة حوادث أمن المعلومات', 'Plan and prepare for managing information security incidents by defining, establishing and communicating processes, roles and responsibilities.', 'التخطيط والاستعداد لإدارة حوادث أمن المعلومات من خلال تحديد وإنشاء وإبلاغ العمليات والأدوار والمسؤوليات.', null, 'corrective', 'high', 'paraphrased', false, 240),
  ('A.5.25', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Assessment and decision on information security events', 'تقييم أحداث أمن المعلومات واتخاذ القرار بشأنها', 'Assess information security events and decide whether they are to be categorized as information security incidents.', 'تقييم أحداث أمن المعلومات وتحديد ما إذا كانت تُصنف كحوادث أمن معلومات.', null, 'detective', 'high', 'paraphrased', false, 250),
  ('A.5.26', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Response to information security incidents', 'الاستجابة لحوادث أمن المعلومات', 'Respond to information security incidents in accordance with documented procedures.', 'الاستجابة لحوادث أمن المعلومات وفقاً للإجراءات الموثقة.', null, 'corrective', 'high', 'paraphrased', false, 260),
  ('A.5.27', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Learning from information security incidents', 'التعلم من حوادث أمن المعلومات', 'Use knowledge gained from information security incidents to strengthen and improve controls.', 'استخدام المعرفة المكتسبة من حوادث أمن المعلومات لتعزيز الضوابط وتحسينها.', null, 'corrective', 'medium', 'paraphrased', false, 270),
  ('A.5.28', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Collection of evidence', 'جمع الأدلة', 'Establish and implement procedures for the identification, collection, acquisition and preservation of evidence related to information security events.', 'وضع وتطبيق إجراءات لتحديد الأدلة المتعلقة بأحداث أمن المعلومات وجمعها والحصول عليها والحفاظ عليها.', null, 'detective', 'medium', 'paraphrased', false, 280),
  ('A.5.29', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Information security during disruption', 'أمن المعلومات أثناء الانقطاع', 'Plan how to maintain information security at an appropriate level during disruption.', 'التخطيط لكيفية الحفاظ على مستوى مناسب من أمن المعلومات أثناء الانقطاع.', null, 'corrective', 'high', 'paraphrased', false, 290),
  ('A.5.30', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'ICT readiness for business continuity', 'جاهزية تقنية المعلومات والاتصالات لاستمرارية الأعمال', 'Plan, implement, maintain and test ICT readiness based on business continuity objectives and ICT continuity requirements.', 'التخطيط لجاهزية تقنية المعلومات والاتصالات وتنفيذها وصيانتها واختبارها بناءً على أهداف استمرارية الأعمال ومتطلبات استمرارية التقنية.', null, 'corrective', 'high', 'paraphrased', false, 300),
  ('A.5.31', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Legal, statutory, regulatory and contractual requirements', 'المتطلبات القانونية والتشريعية والتنظيمية والتعاقدية', 'Identify, document and keep up to date the legal, statutory, regulatory and contractual requirements relevant to information security and the organization''s approach to meeting them.', 'تحديد وتوثيق وتحديث المتطلبات القانونية والتشريعية والتنظيمية والتعاقدية المتعلقة بأمن المعلومات ونهج المنظمة في الوفاء بها.', null, 'governance', 'high', 'paraphrased', false, 310),
  ('A.5.32', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Intellectual property rights', 'حقوق الملكية الفكرية', 'Implement appropriate procedures to protect intellectual property rights.', 'تطبيق إجراءات مناسبة لحماية حقوق الملكية الفكرية.', null, 'preventive', 'low', 'paraphrased', false, 320),
  ('A.5.33', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Protection of records', 'حماية السجلات', 'Protect records from loss, destruction, falsification, unauthorized access and unauthorized release.', 'حماية السجلات من الفقدان والإتلاف والتزوير والوصول غير المصرح به والإفصاح غير المصرح به.', null, 'preventive', 'medium', 'paraphrased', false, 330),
  ('A.5.34', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Privacy and protection of PII', 'الخصوصية وحماية المعلومات الشخصية', 'Identify and meet the requirements regarding the preservation of privacy and protection of personally identifiable information according to applicable laws, regulations and contracts.', 'تحديد متطلبات الحفاظ على الخصوصية وحماية المعلومات الشخصية والوفاء بها وفقاً للقوانين والأنظمة والعقود المعمول بها.', null, 'governance', 'high', 'paraphrased', false, 340),
  ('A.5.35', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Independent review of information security', 'المراجعة المستقلة لأمن المعلومات', 'Independently review the organization''s approach to managing information security and its implementation at planned intervals or when significant changes occur.', 'مراجعة نهج المنظمة في إدارة أمن المعلومات وتطبيقه بشكل مستقل على فترات مخططة أو عند حدوث تغييرات جوهرية.', null, 'detective', 'medium', 'paraphrased', false, 350),
  ('A.5.36', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Compliance with policies, rules and standards for information security', 'الامتثال لسياسات وقواعد ومعايير أمن المعلومات', 'Regularly review compliance with the organization''s information security policy, topic-specific policies, rules and standards.', 'المراجعة المنتظمة للامتثال لسياسة أمن المعلومات والسياسات الموضوعية والقواعد والمعايير في المنظمة.', null, 'detective', 'medium', 'paraphrased', false, 360),
  ('A.5.37', 'Organizational controls', 'الضوابط التنظيمية', null, null, 'Documented operating procedures', 'إجراءات التشغيل الموثقة', 'Document operating procedures for information processing facilities and make them available to personnel who need them.', 'توثيق إجراءات تشغيل مرافق معالجة المعلومات وإتاحتها للعاملين الذين يحتاجون إليها.', null, 'preventive', 'low', 'paraphrased', false, 370),
  ('A.6.1', 'People controls', 'ضوابط الأفراد', null, null, 'Screening', 'التحقق من الخلفية', 'Carry out background verification checks on candidates prior to joining and on an ongoing basis, proportionate to business requirements, information classification and perceived risks.', 'إجراء التحقق من خلفية المرشحين قبل الانضمام وبشكل مستمر، بما يتناسب مع متطلبات الأعمال وتصنيف المعلومات والمخاطر المتوقعة.', null, 'preventive', 'medium', 'paraphrased', false, 380),
  ('A.6.2', 'People controls', 'ضوابط الأفراد', null, null, 'Terms and conditions of employment', 'شروط وأحكام التوظيف', 'Employment contracts state the personnel''s and the organization''s responsibilities for information security.', 'تنص عقود العمل على مسؤوليات العاملين والمنظمة تجاه أمن المعلومات.', null, 'preventive', 'medium', 'paraphrased', false, 390),
  ('A.6.3', 'People controls', 'ضوابط الأفراد', null, null, 'Information security awareness, education and training', 'التوعية والتثقيف والتدريب في أمن المعلومات', 'Provide personnel and relevant interested parties with appropriate awareness, education, training and regular updates on the information security policy and procedures relevant to their role.', 'تزويد العاملين والأطراف المعنية بالتوعية والتثقيف والتدريب المناسب والتحديثات المنتظمة بشأن سياسة وإجراءات أمن المعلومات ذات الصلة بأدوارهم.', null, 'preventive', 'medium', 'paraphrased', false, 400),
  ('A.6.4', 'People controls', 'ضوابط الأفراد', null, null, 'Disciplinary process', 'الإجراءات التأديبية', 'Formalize and communicate a disciplinary process to take action against personnel who have committed an information security policy violation.', 'إضفاء الطابع الرسمي على إجراءات تأديبية وإبلاغها لاتخاذ الإجراء بحق العاملين الذين ينتهكون سياسة أمن المعلومات.', null, 'corrective', 'low', 'paraphrased', false, 410),
  ('A.6.5', 'People controls', 'ضوابط الأفراد', null, null, 'Responsibilities after termination or change of employment', 'المسؤوليات بعد إنهاء أو تغيير العلاقة الوظيفية', 'Define, enforce and communicate the information security responsibilities and duties that remain valid after termination or change of employment.', 'تحديد وإنفاذ وإبلاغ مسؤوليات وواجبات أمن المعلومات التي تظل سارية بعد إنهاء أو تغيير العلاقة الوظيفية.', null, 'preventive', 'medium', 'paraphrased', false, 420),
  ('A.6.6', 'People controls', 'ضوابط الأفراد', null, null, 'Confidentiality or non-disclosure agreements', 'اتفاقيات السرية أو عدم الإفصاح', 'Identify, document, regularly review and sign confidentiality or non-disclosure agreements reflecting the organization''s needs for protecting information.', 'تحديد وتوثيق ومراجعة وتوقيع اتفاقيات السرية أو عدم الإفصاح بما يعكس احتياجات المنظمة لحماية المعلومات.', null, 'preventive', 'medium', 'paraphrased', false, 430),
  ('A.6.7', 'People controls', 'ضوابط الأفراد', null, null, 'Remote working', 'العمل عن بُعد', 'Implement security measures when personnel work remotely to protect information accessed, processed or stored outside the organization''s premises.', 'تطبيق تدابير أمنية عند عمل العاملين عن بُعد لحماية المعلومات التي يتم الوصول إليها أو معالجتها أو تخزينها خارج مقر المنظمة.', null, 'preventive', 'medium', 'paraphrased', false, 440),
  ('A.6.8', 'People controls', 'ضوابط الأفراد', null, null, 'Information security event reporting', 'الإبلاغ عن أحداث أمن المعلومات', 'Provide a mechanism for personnel to report observed or suspected information security events through appropriate channels in a timely manner.', 'توفير آلية للعاملين للإبلاغ عن أحداث أمن المعلومات الملاحظة أو المشتبه بها عبر القنوات المناسبة وفي الوقت المناسب.', null, 'detective', 'medium', 'paraphrased', false, 450),
  ('A.7.1', 'Physical controls', 'الضوابط المادية', null, null, 'Physical security perimeters', 'المحيط الأمني المادي', 'Define and use security perimeters to protect areas that contain information and other associated assets.', 'تحديد واستخدام محيطات أمنية لحماية المناطق التي تحتوي على المعلومات والأصول المرتبطة بها.', null, 'preventive', 'medium', 'paraphrased', false, 460),
  ('A.7.2', 'Physical controls', 'الضوابط المادية', null, null, 'Physical entry', 'الدخول المادي', 'Protect secure areas by appropriate entry controls and access points.', 'حماية المناطق الآمنة بضوابط دخول ونقاط وصول مناسبة.', null, 'preventive', 'high', 'paraphrased', false, 470),
  ('A.7.3', 'Physical controls', 'الضوابط المادية', null, null, 'Securing offices, rooms and facilities', 'تأمين المكاتب والغرف والمرافق', 'Design and implement physical security for offices, rooms and facilities.', 'تصميم وتطبيق الأمن المادي للمكاتب والغرف والمرافق.', null, 'preventive', 'medium', 'paraphrased', false, 480),
  ('A.7.4', 'Physical controls', 'الضوابط المادية', null, null, 'Physical security monitoring', 'مراقبة الأمن المادي', 'Continuously monitor premises for unauthorized physical access.', 'المراقبة المستمرة للمباني لاكتشاف الوصول المادي غير المصرح به.', null, 'detective', 'medium', 'paraphrased', false, 490),
  ('A.7.5', 'Physical controls', 'الضوابط المادية', null, null, 'Protecting against physical and environmental threats', 'الحماية من التهديدات المادية والبيئية', 'Design and implement protection against physical and environmental threats such as natural disasters and other intentional or unintentional threats to infrastructure.', 'تصميم وتطبيق الحماية من التهديدات المادية والبيئية مثل الكوارث الطبيعية والتهديدات المقصودة أو غير المقصودة للبنية التحتية.', null, 'preventive', 'medium', 'paraphrased', false, 500),
  ('A.7.6', 'Physical controls', 'الضوابط المادية', null, null, 'Working in secure areas', 'العمل في المناطق الآمنة', 'Design and implement security measures for working in secure areas.', 'تصميم وتطبيق تدابير أمنية للعمل في المناطق الآمنة.', null, 'preventive', 'low', 'paraphrased', false, 510),
  ('A.7.7', 'Physical controls', 'الضوابط المادية', null, null, 'Clear desk and clear screen', 'المكتب النظيف والشاشة النظيفة', 'Define and enforce clear desk rules for papers and removable storage media and clear screen rules for information processing facilities.', 'تحديد وإنفاذ قواعد المكتب النظيف للأوراق ووسائط التخزين القابلة للإزالة وقواعد الشاشة النظيفة لمرافق معالجة المعلومات.', null, 'preventive', 'low', 'paraphrased', false, 520),
  ('A.7.8', 'Physical controls', 'الضوابط المادية', null, null, 'Equipment siting and protection', 'موقع المعدات وحمايتها', 'Site equipment securely and protect it.', 'وضع المعدات في مواقع آمنة وحمايتها.', null, 'preventive', 'medium', 'paraphrased', false, 530),
  ('A.7.9', 'Physical controls', 'الضوابط المادية', null, null, 'Security of assets off-premises', 'أمن الأصول خارج المقر', 'Protect off-site assets.', 'حماية الأصول الموجودة خارج مقر المنظمة.', null, 'preventive', 'medium', 'paraphrased', false, 540),
  ('A.7.10', 'Physical controls', 'الضوابط المادية', null, null, 'Storage media', 'وسائط التخزين', 'Manage storage media through their life cycle of acquisition, use, transportation and disposal in accordance with the classification scheme and handling requirements.', 'إدارة وسائط التخزين طوال دورة حياتها من الاقتناء والاستخدام والنقل والتخلص وفقاً لآلية التصنيف ومتطلبات التعامل.', null, 'preventive', 'medium', 'paraphrased', false, 550),
  ('A.7.11', 'Physical controls', 'الضوابط المادية', null, null, 'Supporting utilities', 'المرافق الداعمة', 'Protect information processing facilities from power failures and other disruptions caused by failures in supporting utilities.', 'حماية مرافق معالجة المعلومات من انقطاع الطاقة والاضطرابات الأخرى الناجمة عن أعطال المرافق الداعمة.', null, 'preventive', 'medium', 'paraphrased', false, 560),
  ('A.7.12', 'Physical controls', 'الضوابط المادية', null, null, 'Cabling security', 'أمن الكابلات', 'Protect cables carrying power, data or supporting information services from interception, interference or damage.', 'حماية الكابلات الناقلة للطاقة أو البيانات أو خدمات المعلومات الداعمة من الاعتراض أو التداخل أو التلف.', null, 'preventive', 'low', 'paraphrased', false, 570),
  ('A.7.13', 'Physical controls', 'الضوابط المادية', null, null, 'Equipment maintenance', 'صيانة المعدات', 'Maintain equipment correctly to ensure availability, integrity and confidentiality of information.', 'صيانة المعدات بشكل صحيح لضمان توافر المعلومات وسلامتها وسريتها.', null, 'preventive', 'low', 'paraphrased', false, 580),
  ('A.7.14', 'Physical controls', 'الضوابط المادية', null, null, 'Secure disposal or re-use of equipment', 'التخلص الآمن من المعدات أو إعادة استخدامها', 'Verify that items of equipment containing storage media are checked so that sensitive data and licensed software have been removed or securely overwritten prior to disposal or re-use.', 'التحقق من فحص المعدات التي تحتوي على وسائط تخزين للتأكد من إزالة البيانات الحساسة والبرمجيات المرخصة أو الكتابة فوقها بشكل آمن قبل التخلص منها أو إعادة استخدامها.', null, 'preventive', 'medium', 'paraphrased', false, 590),
  ('A.8.1', 'Technological controls', 'الضوابط التقنية', null, null, 'User endpoint devices', 'أجهزة المستخدمين الطرفية', 'Protect information stored on, processed by or accessible via user endpoint devices.', 'حماية المعلومات المخزنة أو المعالجة أو التي يمكن الوصول إليها عبر أجهزة المستخدمين الطرفية.', null, 'preventive', 'high', 'paraphrased', false, 600),
  ('A.8.2', 'Technological controls', 'الضوابط التقنية', null, null, 'Privileged access rights', 'صلاحيات الوصول المميزة', 'Restrict and manage the allocation and use of privileged access rights.', 'تقييد وإدارة تخصيص واستخدام صلاحيات الوصول المميزة.', null, 'preventive', 'high', 'paraphrased', false, 610),
  ('A.8.3', 'Technological controls', 'الضوابط التقنية', null, null, 'Information access restriction', 'تقييد الوصول إلى المعلومات', 'Restrict access to information and other associated assets in accordance with the established topic-specific access control policy.', 'تقييد الوصول إلى المعلومات والأصول المرتبطة بها وفقاً لسياسة التحكم في الوصول المعتمدة.', null, 'preventive', 'high', 'paraphrased', false, 620),
  ('A.8.4', 'Technological controls', 'الضوابط التقنية', null, null, 'Access to source code', 'الوصول إلى الشفرة المصدرية', 'Appropriately manage read and write access to source code, development tools and software libraries.', 'إدارة صلاحيات القراءة والكتابة للشفرة المصدرية وأدوات التطوير ومكتبات البرمجيات بشكل مناسب.', null, 'preventive', 'medium', 'paraphrased', false, 630),
  ('A.8.5', 'Technological controls', 'الضوابط التقنية', null, null, 'Secure authentication', 'المصادقة الآمنة', 'Implement secure authentication technologies and procedures based on information access restrictions and the access control policy.', 'تطبيق تقنيات وإجراءات مصادقة آمنة بناءً على قيود الوصول إلى المعلومات وسياسة التحكم في الوصول.', null, 'preventive', 'high', 'paraphrased', false, 640),
  ('A.8.6', 'Technological controls', 'الضوابط التقنية', null, null, 'Capacity management', 'إدارة السعة', 'Monitor and adjust the use of resources in line with current and expected capacity requirements.', 'مراقبة استخدام الموارد وتعديله بما يتماشى مع متطلبات السعة الحالية والمتوقعة.', null, 'preventive', 'low', 'paraphrased', false, 650),
  ('A.8.7', 'Technological controls', 'الضوابط التقنية', null, null, 'Protection against malware', 'الحماية من البرمجيات الضارة', 'Implement protection against malware, supported by appropriate user awareness.', 'تطبيق الحماية من البرمجيات الضارة مدعومة بتوعية مناسبة للمستخدمين.', null, 'preventive', 'high', 'paraphrased', false, 660),
  ('A.8.8', 'Technological controls', 'الضوابط التقنية', null, null, 'Management of technical vulnerabilities', 'إدارة الثغرات التقنية', 'Obtain information about technical vulnerabilities of information systems in use, evaluate exposure and take appropriate measures.', 'الحصول على معلومات عن الثغرات التقنية في أنظمة المعلومات المستخدمة، وتقييم مدى التعرض لها، واتخاذ التدابير المناسبة.', null, 'detective', 'high', 'paraphrased', false, 670),
  ('A.8.9', 'Technological controls', 'الضوابط التقنية', null, null, 'Configuration management', 'إدارة الإعدادات', 'Establish, document, implement, monitor and review configurations, including security configurations, of hardware, software, services and networks.', 'وضع وتوثيق وتطبيق ومراقبة ومراجعة إعدادات الأجهزة والبرمجيات والخدمات والشبكات، بما في ذلك الإعدادات الأمنية.', null, 'preventive', 'high', 'paraphrased', false, 680),
  ('A.8.10', 'Technological controls', 'الضوابط التقنية', null, null, 'Information deletion', 'حذف المعلومات', 'Delete information stored in information systems, devices or any other storage media when no longer required.', 'حذف المعلومات المخزنة في أنظمة المعلومات أو الأجهزة أو أي وسائط تخزين أخرى عند انتفاء الحاجة إليها.', null, 'preventive', 'medium', 'paraphrased', false, 690),
  ('A.8.11', 'Technological controls', 'الضوابط التقنية', null, null, 'Data masking', 'إخفاء البيانات', 'Use data masking in accordance with the access control policy and business requirements, taking applicable legislation into consideration.', 'استخدام إخفاء البيانات وفقاً لسياسة التحكم في الوصول ومتطلبات الأعمال مع مراعاة التشريعات المعمول بها.', null, 'preventive', 'medium', 'paraphrased', false, 700),
  ('A.8.12', 'Technological controls', 'الضوابط التقنية', null, null, 'Data leakage prevention', 'منع تسرب البيانات', 'Apply data leakage prevention measures to systems, networks and any other devices that process, store or transmit sensitive information.', 'تطبيق تدابير منع تسرب البيانات على الأنظمة والشبكات وأي أجهزة أخرى تعالج أو تخزن أو تنقل معلومات حساسة.', null, 'preventive', 'high', 'paraphrased', false, 710),
  ('A.8.13', 'Technological controls', 'الضوابط التقنية', null, null, 'Information backup', 'النسخ الاحتياطي للمعلومات', 'Maintain and regularly test backup copies of information, software and systems in accordance with the agreed topic-specific policy on backup.', 'الاحتفاظ بنسخ احتياطية من المعلومات والبرمجيات والأنظمة واختبارها بانتظام وفقاً لسياسة النسخ الاحتياطي المعتمدة.', null, 'corrective', 'high', 'paraphrased', false, 720),
  ('A.8.14', 'Technological controls', 'الضوابط التقنية', null, null, 'Redundancy of information processing facilities', 'تكرار مرافق معالجة المعلومات', 'Implement information processing facilities with sufficient redundancy to meet availability requirements.', 'تنفيذ مرافق معالجة المعلومات بتكرار كافٍ لتلبية متطلبات التوافر.', null, 'preventive', 'medium', 'paraphrased', false, 730),
  ('A.8.15', 'Technological controls', 'الضوابط التقنية', null, null, 'Logging', 'تسجيل الأحداث', 'Produce, store, protect and analyze logs that record activities, exceptions, faults and other relevant events.', 'إنتاج وتخزين وحماية وتحليل السجلات التي توثق الأنشطة والاستثناءات والأعطال والأحداث الأخرى ذات الصلة.', null, 'detective', 'high', 'paraphrased', false, 740),
  ('A.8.16', 'Technological controls', 'الضوابط التقنية', null, null, 'Monitoring activities', 'أنشطة المراقبة', 'Monitor networks, systems and applications for anomalous behaviour and take appropriate actions to evaluate potential information security incidents.', 'مراقبة الشبكات والأنظمة والتطبيقات لاكتشاف السلوك الشاذ واتخاذ الإجراءات المناسبة لتقييم حوادث أمن المعلومات المحتملة.', null, 'detective', 'high', 'paraphrased', false, 750),
  ('A.8.17', 'Technological controls', 'الضوابط التقنية', null, null, 'Clock synchronization', 'مزامنة الساعات', 'Synchronize the clocks of information processing systems to approved time sources.', 'مزامنة ساعات أنظمة معالجة المعلومات مع مصادر وقت معتمدة.', null, 'preventive', 'low', 'paraphrased', false, 760),
  ('A.8.18', 'Technological controls', 'الضوابط التقنية', null, null, 'Use of privileged utility programs', 'استخدام برامج الأدوات المساعدة المميزة', 'Restrict and tightly control the use of utility programs that can be capable of overriding system and application controls.', 'تقييد استخدام برامج الأدوات المساعدة القادرة على تجاوز ضوابط الأنظمة والتطبيقات والتحكم فيه بإحكام.', null, 'preventive', 'medium', 'paraphrased', false, 770),
  ('A.8.19', 'Technological controls', 'الضوابط التقنية', null, null, 'Installation of software on operational systems', 'تثبيت البرمجيات على الأنظمة التشغيلية', 'Implement procedures and measures to securely manage software installation on operational systems.', 'تطبيق إجراءات وتدابير لإدارة تثبيت البرمجيات على الأنظمة التشغيلية بشكل آمن.', null, 'preventive', 'medium', 'paraphrased', false, 780),
  ('A.8.20', 'Technological controls', 'الضوابط التقنية', null, null, 'Networks security', 'أمن الشبكات', 'Secure, manage and control networks and network devices to protect information in systems and applications.', 'تأمين الشبكات وأجهزتها وإدارتها والتحكم فيها لحماية المعلومات في الأنظمة والتطبيقات.', null, 'preventive', 'high', 'paraphrased', false, 790),
  ('A.8.21', 'Technological controls', 'الضوابط التقنية', null, null, 'Security of network services', 'أمن خدمات الشبكة', 'Identify, implement and monitor security mechanisms, service levels and service requirements of network services.', 'تحديد وتنفيذ ومراقبة الآليات الأمنية ومستويات الخدمة ومتطلبات خدمات الشبكة.', null, 'preventive', 'medium', 'paraphrased', false, 800),
  ('A.8.22', 'Technological controls', 'الضوابط التقنية', null, null, 'Segregation of networks', 'فصل الشبكات', 'Segregate groups of information services, users and information systems in the organization''s networks.', 'فصل مجموعات خدمات المعلومات والمستخدمين وأنظمة المعلومات في شبكات المنظمة.', null, 'preventive', 'high', 'paraphrased', false, 810),
  ('A.8.23', 'Technological controls', 'الضوابط التقنية', null, null, 'Web filtering', 'تصفية الويب', 'Manage access to external websites to reduce exposure to malicious content.', 'إدارة الوصول إلى المواقع الخارجية للحد من التعرض للمحتوى الضار.', null, 'preventive', 'medium', 'paraphrased', false, 820),
  ('A.8.24', 'Technological controls', 'الضوابط التقنية', null, null, 'Use of cryptography', 'استخدام التشفير', 'Define and implement rules for the effective use of cryptography, including cryptographic key management.', 'تحديد وتطبيق قواعد للاستخدام الفعال للتشفير، بما في ذلك إدارة مفاتيح التشفير.', null, 'preventive', 'high', 'paraphrased', false, 830),
  ('A.8.25', 'Technological controls', 'الضوابط التقنية', null, null, 'Secure development life cycle', 'دورة حياة التطوير الآمن', 'Establish and apply rules for the secure development of software and systems.', 'وضع وتطبيق قواعد للتطوير الآمن للبرمجيات والأنظمة.', null, 'preventive', 'high', 'paraphrased', false, 840),
  ('A.8.26', 'Technological controls', 'الضوابط التقنية', null, null, 'Application security requirements', 'متطلبات أمن التطبيقات', 'Identify, specify and approve information security requirements when developing or acquiring applications.', 'تحديد وتوصيف واعتماد متطلبات أمن المعلومات عند تطوير التطبيقات أو اقتنائها.', null, 'preventive', 'medium', 'paraphrased', false, 850),
  ('A.8.27', 'Technological controls', 'الضوابط التقنية', null, null, 'Secure system architecture and engineering principles', 'مبادئ الهندسة والبنية الآمنة للأنظمة', 'Establish, document, maintain and apply principles for engineering secure systems to any information system development activities.', 'وضع وتوثيق وصيانة وتطبيق مبادئ هندسة الأنظمة الآمنة على أنشطة تطوير أنظمة المعلومات.', null, 'preventive', 'medium', 'paraphrased', false, 860),
  ('A.8.28', 'Technological controls', 'الضوابط التقنية', null, null, 'Secure coding', 'البرمجة الآمنة', 'Apply secure coding principles to software development.', 'تطبيق مبادئ البرمجة الآمنة في تطوير البرمجيات.', null, 'preventive', 'high', 'paraphrased', false, 870),
  ('A.8.29', 'Technological controls', 'الضوابط التقنية', null, null, 'Security testing in development and acceptance', 'اختبار الأمن في التطوير والقبول', 'Define and implement security testing processes in the development life cycle.', 'تحديد وتنفيذ عمليات اختبار الأمن ضمن دورة حياة التطوير.', null, 'detective', 'medium', 'paraphrased', false, 880),
  ('A.8.30', 'Technological controls', 'الضوابط التقنية', null, null, 'Outsourced development', 'التطوير المُسند لجهات خارجية', 'Direct, monitor and review the activities related to outsourced system development.', 'توجيه ومراقبة ومراجعة الأنشطة المتعلقة بتطوير الأنظمة المُسند لجهات خارجية.', null, 'detective', 'medium', 'paraphrased', false, 890),
  ('A.8.31', 'Technological controls', 'الضوابط التقنية', null, null, 'Separation of development, test and production environments', 'فصل بيئات التطوير والاختبار والإنتاج', 'Separate and secure development, testing and production environments.', 'فصل بيئات التطوير والاختبار والإنتاج وتأمينها.', null, 'preventive', 'high', 'paraphrased', false, 900),
  ('A.8.32', 'Technological controls', 'الضوابط التقنية', null, null, 'Change management', 'إدارة التغيير', 'Subject changes to information processing facilities and information systems to change management procedures.', 'إخضاع التغييرات على مرافق معالجة المعلومات وأنظمة المعلومات لإجراءات إدارة التغيير.', null, 'preventive', 'high', 'paraphrased', false, 910),
  ('A.8.33', 'Technological controls', 'الضوابط التقنية', null, null, 'Test information', 'معلومات الاختبار', 'Appropriately select, protect and manage test information.', 'اختيار معلومات الاختبار وحمايتها وإدارتها بشكل مناسب.', null, 'preventive', 'low', 'paraphrased', false, 920),
  ('A.8.34', 'Technological controls', 'الضوابط التقنية', null, null, 'Protection of information systems during audit testing', 'حماية أنظمة المعلومات أثناء اختبارات التدقيق', 'Plan and agree audit tests and other assurance activities involving assessment of operational systems between the tester and appropriate management.', 'التخطيط لاختبارات التدقيق وأنشطة التأكيد الأخرى التي تتضمن تقييم الأنظمة التشغيلية والاتفاق عليها بين المختبر والإدارة المعنية.', null, 'preventive', 'low', 'paraphrased', false, 930)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'ISO-27001'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- KSA-PDPL: Personal Data Protection Law (PDPL) — Kingdom of Saudi Arabia (32 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('KSA-PDPL', 'Saudi PDPL', 'Personal Data Protection Law (PDPL) — Kingdom of Saudi Arabia', 'نظام حماية البيانات الشخصية — المملكة العربية السعودية', 'Saudi Data & AI Authority (SDAIA) — National Data Management Office', 'الهيئة السعودية للبيانات والذكاء الاصطناعي (سدايا) — مكتب إدارة البيانات الوطنية', 'SA', 'data-protection', 'Royal Decree M/19 (2021), amended M/148 (2023)', '2023-09-14', 'https://sdaia.gov.sa/en/SDAIA/about/Documents/Personal%20Data%20English%20V2-23April2023-%20Reviewed-.pdf', 'The Kingdom''s first comprehensive personal data protection law, in force since 14 September 2023 with a one-year compliance grace period. It applies to any processing of personal data of individuals in the Kingdom, including by controllers outside the Kingdom. Rows are organized by article and summarize each obligation; the Implementing Regulations and the Personal Data Transfer Regulations add detailed requirements that should be consulted alongside.', 'أول نظام شامل لحماية البيانات الشخصية في المملكة، ساري المفعول منذ 14 سبتمبر 2023 مع مهلة امتثال لمدة عام. ينطبق على أي معالجة للبيانات الشخصية للأفراد في المملكة، بما في ذلك المعالجة من قبل جهات تحكم خارج المملكة. الصفوف منظمة حسب المواد وتلخص كل التزام؛ وتضيف اللائحة التنفيذية ولائحة نقل البيانات الشخصية متطلبات تفصيلية يجب الرجوع إليها.', true, 30)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('Art. 2', 'Scope and Data Subject Rights', 'النطاق وحقوق صاحب البيانات', null, null, 'Scope of application', 'نطاق التطبيق', 'The law applies to any processing of personal data relating to individuals that takes place in the Kingdom by any means, including processing by entities outside the Kingdom of personal data of individuals residing in the Kingdom. Processing for purely personal or family use is excluded.', 'يسري النظام على أي معالجة للبيانات الشخصية المتعلقة بالأفراد تتم في المملكة بأي وسيلة، بما في ذلك معالجة جهات خارج المملكة لبيانات أفراد مقيمين فيها. وتُستثنى المعالجة للأغراض الشخصية أو العائلية البحتة.', null, 'governance', 'high', 'summarized', false, 10),
  ('Art. 4', 'Scope and Data Subject Rights', 'النطاق وحقوق صاحب البيانات', null, null, 'Rights of the data subject', 'حقوق صاحب البيانات الشخصية', 'Data subjects have the right to be informed of the legal basis and purpose of collection, the right to access their personal data, the right to obtain a copy in a clear readable format, the right to request correction, completion or updating, and the right to request destruction of data no longer needed.', 'لصاحب البيانات الحق في العلم بالأساس النظامي والغرض من جمع بياناته، والحق في الوصول إليها، والحصول على نسخة منها بصيغة واضحة ومقروءة، وطلب تصحيحها أو إكمالها أو تحديثها، وطلب إتلافها عند انتفاء الحاجة إليها.', 'DSAR procedure, request log, response templates.', 'governance', 'high', 'summarized', false, 20),
  ('Art. 21', 'Scope and Data Subject Rights', 'النطاق وحقوق صاحب البيانات', null, null, 'Responding to data subject requests', 'الاستجابة لطلبات أصحاب البيانات', 'Controllers must respond to data subject requests to exercise their rights within the period set by the Implementing Regulations (30 days, extendable once), free of charge except where requests are repetitive or excessive.', 'يجب على جهة التحكم الاستجابة لطلبات أصحاب البيانات لممارسة حقوقهم خلال المدة التي تحددها اللائحة (30 يوماً قابلة للتمديد مرة واحدة)، دون مقابل إلا في حال تكرار الطلبات أو مبالغتها.', 'SLA tracking for requests.', 'corrective', 'medium', 'summarized', false, 30),
  ('Art. 3', 'Scope and Data Subject Rights', 'النطاق وحقوق صاحب البيانات', null, null, 'Personal data of deceased persons', 'البيانات الشخصية للمتوفين', 'Provisions apply to personal data of deceased persons where the data would lead to identifying them or a family member.', 'تسري الأحكام على البيانات الشخصية للمتوفين إذا كانت تؤدي إلى التعرف عليهم أو على أحد أفراد أسرهم.', null, 'governance', 'low', 'summarized', false, 40),
  ('Art. 5', 'Lawful Basis and Consent', 'الأساس النظامي والموافقة', null, null, 'Consent as the general basis for processing', 'الموافقة كأساس عام للمعالجة', 'Personal data may not be processed without the consent of the data subject except in the cases provided by the law. The Regulations set the conditions and forms of consent, including for sensitive data and minors.', 'لا يجوز معالجة البيانات الشخصية دون موافقة صاحبها إلا في الحالات المنصوص عليها في النظام. وتحدد اللائحة شروط الموافقة وأشكالها، بما في ذلك للبيانات الحساسة والقاصرين.', 'Consent records, consent capture UX.', 'preventive', 'high', 'summarized', false, 50),
  ('Art. 6', 'Lawful Basis and Consent', 'الأساس النظامي والموافقة', null, null, 'Processing without consent', 'المعالجة دون موافقة', 'Consent is not required where processing serves the data subject''s actual interest and contact is impossible, where required by another law or a prior agreement to which the data subject is party, where the controller is a public entity acting for security or judicial purposes, or where necessary for the controller''s legitimate interests (excluding sensitive data) without prejudice to the data subject''s rights.', 'لا تُشترط الموافقة إذا كانت المعالجة تحقق مصلحة فعلية لصاحب البيانات وتعذر الاتصال به، أو كانت مطلوبة بموجب نظام آخر أو اتفاق سابق يكون صاحب البيانات طرفاً فيه، أو كانت جهة التحكم جهة عامة لأغراض أمنية أو قضائية، أو كانت ضرورية لتحقيق المصالح المشروعة لجهة التحكم (باستثناء البيانات الحساسة) دون المساس بحقوق صاحب البيانات.', 'Lawful basis register, legitimate interest assessments.', 'governance', 'high', 'summarized', false, 60),
  ('Art. 7', 'Lawful Basis and Consent', 'الأساس النظامي والموافقة', null, null, 'Conditions of consent', 'شروط الموافقة', 'Consent may not be a condition for providing a service or benefit unless the service is directly related to the processing. Data subjects may withdraw consent at any time.', 'لا يجوز أن تكون الموافقة شرطاً لتقديم خدمة أو ميزة ما لم تكن الخدمة مرتبطة مباشرة بالمعالجة. ولصاحب البيانات سحب موافقته في أي وقت.', null, 'preventive', 'medium', 'summarized', false, 70),
  ('Art. 10', 'Lawful Basis and Consent', 'الأساس النظامي والموافقة', null, null, 'Direct collection from the data subject', 'الجمع المباشر من صاحب البيانات', 'Personal data must be collected directly from the data subject and processed only for the purpose of collection, except where the data subject consents, the data is publicly available, the controller is a public entity for security/judicial purposes, or collection is necessary to protect vital interests or comply with another law.', 'يجب جمع البيانات الشخصية من صاحبها مباشرة ومعالجتها للغرض الذي جُمعت من أجله، إلا بموافقة صاحبها، أو إذا كانت البيانات متاحة للعموم، أو كانت جهة التحكم جهة عامة لأغراض أمنية أو قضائية، أو كان الجمع ضرورياً لحماية مصلحة حيوية أو للالتزام بنظام آخر.', null, 'preventive', 'medium', 'summarized', false, 80),
  ('Art. 11', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Purpose limitation and proportionality', 'تحديد الغرض والتناسب', 'The purpose of collection must be directly related to the controller''s purposes and not contrary to law; the method must be appropriate and not deceptive; content must be limited to the minimum necessary; and data must not be processed beyond the purpose except as permitted.', 'يجب أن يكون الغرض من الجمع مرتبطاً مباشرة بأغراض جهة التحكم وغير مخالف للأنظمة، وأن تكون الطريقة مناسبة وغير مضللة، وأن يقتصر المحتوى على الحد الأدنى اللازم، وألا تُعالج البيانات خارج نطاق الغرض إلا بما هو مسموح.', null, 'preventive', 'high', 'summarized', false, 90),
  ('Art. 12', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Privacy policy', 'سياسة الخصوصية', 'Controllers must adopt and make available to data subjects, before collecting their data, a privacy policy describing the purpose, content, method of collection, means of storage, processing, destruction and the data subject''s rights.', 'يجب على جهة التحكم وضع سياسة خصوصية وإتاحتها لأصحاب البيانات قبل جمع بياناتهم، تبين الغرض والمحتوى وطريقة الجمع ووسائل الحفظ والمعالجة والإتلاف وحقوق صاحب البيانات.', 'Published privacy policy (EN/AR).', 'preventive', 'high', 'summarized', false, 100),
  ('Art. 13', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Notice at the time of collection', 'الإشعار عند الجمع', 'When collecting personal data directly, the controller must inform the data subject of the legal basis, the purpose and whether collection is mandatory or optional, the identity and address of the collector, the entities to which data may be disclosed and whether it will be transferred abroad, the consequences of not collecting, and the data subject''s rights.', 'عند جمع البيانات مباشرة من صاحبها، يجب إعلامه بالأساس النظامي، والغرض وما إذا كان الجمع إلزامياً أو اختيارياً، وهوية وعنوان الجهة الجامعة، والجهات التي ستُفصح لها البيانات وما إذا كانت ستُنقل خارج المملكة، وأثر عدم الجمع، وحقوقه.', 'Collection notices, consent forms.', 'preventive', 'high', 'summarized', false, 110),
  ('Art. 14', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Accuracy and data minimization', 'الدقة وتقليل البيانات', 'Controllers must not process data unless it is accurate, complete and up to date, and must not process more than necessary for the purpose.', 'لا يجوز لجهة التحكم معالجة البيانات ما لم تكن دقيقة ومكتملة ومحدثة، ولا معالجة أكثر مما هو ضروري للغرض.', null, 'preventive', 'medium', 'summarized', false, 120),
  ('Art. 17', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Correction and updating', 'التصحيح والتحديث', 'Controllers must correct, complete or update personal data when they become aware of inaccuracy or on request, and notify any entity to which the data was disclosed.', 'يجب على جهة التحكم تصحيح البيانات أو إكمالها أو تحديثها عند علمها بعدم دقتها أو بناءً على طلب، وإشعار أي جهة أُفصح لها عن البيانات.', null, 'corrective', 'medium', 'summarized', false, 130),
  ('Art. 18', 'Collection, Purpose and Transparency', 'الجمع والغرض والشفافية', null, null, 'Destruction when no longer needed', 'الإتلاف عند انتفاء الحاجة', 'Controllers must destroy personal data without undue delay once the purpose of collection ends, unless retention is required by law or the data is anonymized. Data required for legal claims may be retained for the necessary period.', 'يجب على جهة التحكم إتلاف البيانات الشخصية دون تأخير بمجرد انتهاء الغرض من جمعها، ما لم يكن الاحتفاظ مطلوباً بموجب نظام أو كانت البيانات مجهّلة. ويجوز الاحتفاظ بالبيانات اللازمة للمطالبات القانونية للمدة الضرورية.', 'Retention schedule, destruction logs.', 'preventive', 'high', 'summarized', false, 140),
  ('Art. 15', 'Disclosure and Transfers', 'الإفصاح والنقل', null, null, 'Conditions for disclosure', 'شروط الإفصاح', 'Personal data may be disclosed only with the data subject''s consent, where the data is from a public source, where a public entity requires it for security or judicial purposes, where necessary to protect public health or safety or a specific individual''s life, where anonymized, or where necessary for the controller''s legitimate interest without harming the data subject (excluding sensitive data).', 'لا يجوز الإفصاح عن البيانات الشخصية إلا بموافقة صاحبها، أو إذا كانت من مصدر متاح للعموم، أو طلبتها جهة عامة لأغراض أمنية أو قضائية، أو كان الإفصاح ضرورياً لحماية الصحة أو السلامة العامة أو حياة فرد بعينه، أو كانت البيانات مجهّلة، أو كان الإفصاح ضرورياً لتحقيق مصلحة مشروعة لجهة التحكم دون الإضرار بصاحب البيانات (باستثناء البيانات الحساسة).', null, 'preventive', 'high', 'summarized', false, 150),
  ('Art. 16', 'Disclosure and Transfers', 'الإفصاح والنقل', null, null, 'Restrictions on disclosure', 'قيود الإفصاح', 'Disclosure is prohibited even in permitted cases where it threatens security, harms the Kingdom''s reputation or interests, conflicts with another law, affects an ongoing investigation, or would harm the data subject or a third party.', 'يُحظر الإفصاح حتى في الحالات المسموح بها إذا كان يهدد الأمن، أو يضر بسمعة المملكة أو مصالحها، أو يتعارض مع نظام آخر، أو يؤثر على تحقيق قائم، أو يلحق ضرراً بصاحب البيانات أو بطرف ثالث.', null, 'preventive', 'medium', 'summarized', false, 160),
  ('Art. 29', 'Disclosure and Transfers', 'الإفصاح والنقل', null, null, 'Cross-border transfer of personal data', 'نقل البيانات الشخصية خارج المملكة', 'Personal data may be transferred or disclosed outside the Kingdom only for a purpose permitted by law (international agreements, the Kingdom''s interests, contract performance, or other cases in the Regulations), provided the destination affords an adequate level of protection or appropriate safeguards are in place, the transfer is limited to the minimum necessary, and it does not prejudice national security or the data subject''s privacy.', 'لا يجوز نقل البيانات الشخصية أو الإفصاح عنها خارج المملكة إلا لغرض يجيزه النظام (الاتفاقيات الدولية، أو مصالح المملكة، أو تنفيذ عقد، أو الحالات الأخرى في اللائحة)، بشرط توفر مستوى مناسب من الحماية في جهة الوجهة أو ضمانات مناسبة، وأن يقتصر النقل على الحد الأدنى الضروري، وألا يمس الأمن الوطني أو خصوصية صاحب البيانات.', 'Transfer impact assessments, standard contractual clauses, adequacy determinations.', 'preventive', 'high', 'summarized', false, 170),
  ('Art. 19', 'Security, Breach and Accountability', 'الأمن والاختراق والمساءلة', null, null, 'Security of personal data', 'أمن البيانات الشخصية', 'Controllers must take the necessary organizational, administrative and technical measures to protect personal data, including during transfer, in accordance with the controls issued by the National Cybersecurity Authority and the Regulations.', 'يجب على جهة التحكم اتخاذ التدابير التنظيمية والإدارية والتقنية اللازمة لحماية البيانات الشخصية، بما في ذلك أثناء النقل، وفقاً للضوابط الصادرة عن الهيئة الوطنية للأمن السيبراني واللائحة.', 'Security controls mapped to NCA ECC/PDPL, encryption evidence.', 'preventive', 'high', 'summarized', false, 180),
  ('Art. 20', 'Security, Breach and Accountability', 'الأمن والاختراق والمساءلة', null, null, 'Personal data breach notification', 'الإشعار باختراق البيانات الشخصية', 'Controllers must notify the competent authority of any breach, damage or unauthorized access to personal data within 72 hours of becoming aware of it, and notify affected data subjects without undue delay where the breach may cause harm to them.', 'يجب على جهة التحكم إشعار الجهة المختصة بأي اختراق أو تسرب أو وصول غير مشروع للبيانات الشخصية خلال 72 ساعة من العلم به، وإشعار أصحاب البيانات المتأثرين دون تأخير إذا كان الاختراق قد يلحق بهم ضرراً.', 'Breach response procedure, notification templates, breach register.', 'corrective', 'high', 'summarized', false, 190),
  ('Art. 22', 'Security, Breach and Accountability', 'الأمن والاختراق والمساءلة', null, null, 'Records of processing activities', 'سجلات أنشطة المعالجة', 'Controllers must maintain records of processing activities for the period specified in the Regulations, including at minimum the controller''s contact details, the purpose, categories of data subjects, recipients, cross-border transfers and the retention period.', 'يجب على جهة التحكم الاحتفاظ بسجلات لأنشطة المعالجة للمدة المحددة في اللائحة، تتضمن كحد أدنى بيانات الاتصال بجهة التحكم، والغرض، وفئات أصحاب البيانات، والجهات المتلقية، وعمليات النقل خارج المملكة، ومدة الاحتفاظ.', 'ROPA maintained and reviewed.', 'governance', 'high', 'summarized', false, 200),
  ('Art. 30', 'Security, Breach and Accountability', 'الأمن والاختراق والمساءلة', null, null, 'Data protection officer', 'مسؤول حماية البيانات الشخصية', 'Controllers must appoint one or more persons responsible for personal data protection in the cases specified by the Regulations (e.g., public entities, large-scale monitoring, or sensitive data as a core activity).', 'يجب على جهة التحكم تعيين شخص أو أكثر مسؤولاً عن حماية البيانات الشخصية في الحالات التي تحددها اللائحة (مثل الجهات العامة أو المراقبة واسعة النطاق أو معالجة البيانات الحساسة كنشاط رئيسي).', 'DPO appointment and registration with the authority.', 'governance', 'medium', 'summarized', false, 210),
  ('Art. 8', 'Security, Breach and Accountability', 'الأمن والاختراق والمساءلة', null, null, 'Controllers and processors — accountability', 'جهة التحكم وجهة المعالجة — المساءلة', 'Controllers remain responsible for processing carried out on their behalf by processors, must select processors that provide sufficient guarantees, and must verify processor compliance with the law and the controller''s instructions.', 'تبقى جهة التحكم مسؤولة عن المعالجة التي تتم نيابة عنها من قبل جهات المعالجة، ويجب عليها اختيار جهات معالجة توفر ضمانات كافية والتحقق من التزامها بالنظام وبتعليمات جهة التحكم.', 'Data processing agreements, processor due diligence.', 'governance', 'high', 'summarized', false, 220),
  ('Art. 23', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Health data', 'البيانات الصحية', 'Processing of health data must comply with additional controls set by the Regulations, including limiting access to the minimum number of employees and the minimum data necessary for the health service.', 'يجب أن تلتزم معالجة البيانات الصحية بالضوابط الإضافية التي تحددها اللائحة، بما في ذلك قصر الوصول على أقل عدد ممكن من الموظفين وعلى الحد الأدنى من البيانات اللازمة للخدمة الصحية.', null, 'preventive', 'high', 'summarized', false, 230),
  ('Art. 24', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Credit data', 'البيانات الائتمانية', 'Processing of credit data must comply with the Credit Information Law and additional controls, including obtaining consent for collection and disclosure and notifying the data subject of requests for their credit data.', 'يجب أن تلتزم معالجة البيانات الائتمانية بنظام المعلومات الائتمانية والضوابط الإضافية، بما في ذلك الحصول على الموافقة للجمع والإفصاح وإشعار صاحب البيانات بطلبات الحصول على بياناته الائتمانية.', null, 'preventive', 'high', 'summarized', false, 240),
  ('Art. 25', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Direct marketing', 'التسويق المباشر', 'Personal data may not be used for direct marketing communications without the data subject''s prior consent, and each communication must identify the sender and provide a clear mechanism to opt out.', 'لا يجوز استخدام البيانات الشخصية لإرسال مواد تسويقية مباشرة دون موافقة مسبقة من صاحبها، ويجب أن تبين كل رسالة هوية المرسل وتوفر آلية واضحة لإلغاء الاشتراك.', 'Marketing consent records, opt-out handling.', 'preventive', 'medium', 'summarized', false, 250),
  ('Art. 26', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Advertising and awareness materials', 'المواد الإعلانية والتوعوية', 'Sending advertising or awareness materials using personal data requires prior consent unless the material is from a public entity for awareness purposes; the Regulations set the controls.', 'يتطلب إرسال المواد الإعلانية أو التوعوية باستخدام البيانات الشخصية موافقة مسبقة ما لم تكن من جهة عامة لأغراض التوعية؛ وتحدد اللائحة الضوابط.', null, 'preventive', 'low', 'summarized', false, 260),
  ('Art. 27', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Scientific, research and statistical purposes', 'الأغراض العلمية والبحثية والإحصائية', 'Personal data may be processed for scientific, research or statistical purposes without consent only if it does not identify the data subject, identifying elements are destroyed before disclosure to others, or it is collected from a public source.', 'يجوز معالجة البيانات الشخصية للأغراض العلمية أو البحثية أو الإحصائية دون موافقة فقط إذا كانت لا تحدد هوية صاحبها، أو تم إتلاف عناصر التعريف قبل الإفصاح للغير، أو كانت من مصدر متاح للعموم.', null, 'preventive', 'low', 'summarized', false, 270),
  ('Art. 28', 'Special Categories and Specific Processing', 'الفئات الخاصة والمعالجة المحددة', null, null, 'Copies of official identity documents', 'نسخ وثائق الهوية الرسمية', 'Copying official identity documents is prohibited except where required by law or by a public entity, or in cases specified by the Regulations.', 'يُحظر نسخ وثائق الهوية الرسمية إلا بمقتضى نظام أو بطلب من جهة عامة أو في الحالات التي تحددها اللائحة.', null, 'preventive', 'medium', 'summarized', false, 280),
  ('Art. 31–32', 'Supervision, Remedies and Penalties', 'الإشراف والتظلم والعقوبات', null, null, 'Competent authority and national register', 'الجهة المختصة والسجل الوطني', 'SDAIA supervises implementation, issues the Regulations, and operates the national register of controllers; controllers must register where required and cooperate with the authority''s inspections and requests.', 'تتولى سدايا الإشراف على التطبيق وإصدار اللائحة وتشغيل السجل الوطني لجهات التحكم؛ ويجب على جهات التحكم التسجيل عند الاقتضاء والتعاون مع الجهة المختصة في عمليات التفتيش والطلبات.', null, 'governance', 'medium', 'summarized', false, 290),
  ('Art. 33–34', 'Supervision, Remedies and Penalties', 'الإشراف والتظلم والعقوبات', null, null, 'Complaints and compensation', 'الشكاوى والتعويض', 'Data subjects may file complaints with the competent authority regarding the application of the law, and anyone who suffers material or moral damage from a violation may claim compensation before the competent court.', 'لأصحاب البيانات تقديم الشكاوى إلى الجهة المختصة بشأن تطبيق النظام، ولكل من لحقه ضرر مادي أو معنوي نتيجة مخالفة المطالبة بالتعويض أمام المحكمة المختصة.', null, 'governance', 'low', 'summarized', false, 300),
  ('Art. 35', 'Supervision, Remedies and Penalties', 'الإشراف والتظلم والعقوبات', null, null, 'Criminal penalties for sensitive data disclosure', 'العقوبات الجزائية للإفصاح عن البيانات الحساسة', 'Disclosing or publishing sensitive personal data in violation of the law with intent to harm or gain personal benefit is punishable by imprisonment of up to two years and/or a fine of up to SAR 3 million.', 'يُعاقب بالسجن مدة لا تزيد على سنتين و/أو بغرامة لا تزيد على 3 ملايين ريال كل من أفصح عن بيانات شخصية حساسة أو نشرها بالمخالفة للنظام بقصد الإضرار أو تحقيق منفعة شخصية.', null, 'governance', 'high', 'summarized', false, 310),
  ('Art. 36', 'Supervision, Remedies and Penalties', 'الإشراف والتظلم والعقوبات', null, null, 'Administrative fines', 'الغرامات الإدارية', 'Other violations are subject to a warning or a fine of up to SAR 5 million, which may be doubled for repeat violations, imposed by a committee formed by the competent authority.', 'تخضع المخالفات الأخرى لعقوبة الإنذار أو غرامة لا تزيد على 5 ملايين ريال، ويجوز مضاعفتها في حال التكرار، تفرضها لجنة تشكلها الجهة المختصة.', null, 'governance', 'high', 'summarized', false, 320)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'KSA-PDPL'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- NCA-ECC: Essential Cybersecurity Controls (ECC-2:2024) (108 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('NCA-ECC', 'NCA ECC', 'Essential Cybersecurity Controls (ECC-2:2024)', 'الضوابط الأساسية للأمن السيبراني (ECC-2:2024)', 'National Cybersecurity Authority (NCA)', 'الهيئة الوطنية للأمن السيبراني', 'SA', 'cybersecurity', '2:2024', '2024-09-01', 'https://nca.gov.sa/en/regulatory-documents/controls-list/', 'The minimum cybersecurity requirements that all Saudi government entities and critical national infrastructure organizations must implement. Organized into four domains (Governance, Defense, Resilience, Third-Party & Cloud), 28 subdomains and 108 controls. ECC-2:2024 supersedes ECC-1:2018.', 'الحد الأدنى من متطلبات الأمن السيبراني الواجب تطبيقها من قبل الجهات الحكومية والبنى التحتية الوطنية الحساسة في المملكة العربية السعودية. تنقسم إلى أربعة مكونات رئيسية (الحوكمة، تعزيز الأمن، الصمود، الأطراف الخارجية والحوسبة السحابية) و28 مكوناً فرعياً و108 ضوابط.', true, 10)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('1-1-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Strategy', 'استراتيجية الأمن السيبراني', 'Define and approve a cybersecurity strategy', 'تحديد واعتماد استراتيجية الأمن السيبراني', 'A cybersecurity strategy must be defined, documented and approved by the Authorizing Official, and must support the organization''s strategic objectives and comply with related laws and regulations.', 'يجب تحديد وتوثيق واعتماد استراتيجية الأمن السيبراني من قبل صاحب الصلاحية، على أن تدعم الأهداف الاستراتيجية للجهة وتلتزم بالمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'Approved strategy document with sign-off, alignment matrix to organizational objectives.', 'governance', 'high', 'paraphrased', false, 10),
  ('1-1-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Strategy', 'استراتيجية الأمن السيبراني', 'Implement the cybersecurity strategy through a roadmap', 'تنفيذ استراتيجية الأمن السيبراني عبر خطة عمل', 'A roadmap must be developed and executed to implement the cybersecurity strategy, with defined initiatives, owners and timelines.', 'يجب وضع خطة عمل لتنفيذ استراتيجية الأمن السيبراني وتنفيذها، مع تحديد المبادرات والمسؤولين والجداول الزمنية.', 'Roadmap, initiative tracker, progress reports.', 'governance', 'medium', 'paraphrased', false, 20),
  ('1-1-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Strategy', 'استراتيجية الأمن السيبراني', 'Review the cybersecurity strategy periodically', 'مراجعة استراتيجية الأمن السيبراني دورياً', 'The cybersecurity strategy must be reviewed at planned intervals and updated when significant changes occur in the organization or regulatory landscape.', 'يجب مراجعة استراتيجية الأمن السيبراني على فترات مخططة وتحديثها عند حدوث تغييرات جوهرية في الجهة أو البيئة التنظيمية.', 'Review records, change log, updated approvals.', 'governance', 'medium', 'paraphrased', false, 30),
  ('1-2-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Management', 'إدارة الأمن السيبراني', 'Establish an independent cybersecurity function', 'إنشاء إدارة مستقلة للأمن السيبراني', 'A dedicated cybersecurity function must be established, independent from IT, and must be staffed with full-time, qualified Saudi nationals in line with NCA requirements.', 'يجب إنشاء إدارة للأمن السيبراني تكون مستقلة عن إدارة تقنية المعلومات، ويعمل بها موظفون سعوديون مؤهلون بدوام كامل وفقاً لمتطلبات الهيئة.', 'Organization chart, function charter, staffing records.', 'governance', 'high', 'paraphrased', false, 40),
  ('1-2-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Management', 'إدارة الأمن السيبراني', 'Appoint a cybersecurity head reporting to the Authorizing Official', 'تعيين رئيس للأمن السيبراني يرتبط بصاحب الصلاحية', 'The head of the cybersecurity function must be appointed at a senior level and report to the head of the organization or their delegate.', 'يجب تعيين رئيس إدارة الأمن السيبراني بمستوى إداري رفيع بحيث يرتبط برئيس الجهة أو من ينيبه.', 'Appointment letter, reporting line in organization chart.', 'governance', 'high', 'paraphrased', false, 50),
  ('1-2-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Management', 'إدارة الأمن السيبراني', 'Establish a cybersecurity steering committee', 'إنشاء لجنة إشرافية للأمن السيبراني', 'A cybersecurity steering committee must be established with the head of cybersecurity as a member, to oversee implementation of the cybersecurity program and ensure objectives are met.', 'يجب إنشاء لجنة إشرافية للأمن السيبراني يكون رئيس الأمن السيبراني عضواً فيها، للإشراف على تنفيذ برنامج الأمن السيبراني وضمان تحقيق أهدافه.', 'Committee charter, membership list, meeting minutes.', 'governance', 'medium', 'paraphrased', false, 60),
  ('1-3-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Policies and Procedures', 'سياسات وإجراءات الأمن السيبراني', 'Define and approve cybersecurity policies and procedures', 'تحديد واعتماد سياسات وإجراءات الأمن السيبراني', 'Cybersecurity policies and procedures must be defined, documented and approved by the Authorizing Official, and communicated to relevant personnel and third parties.', 'يجب تحديد وتوثيق واعتماد سياسات وإجراءات الأمن السيبراني من قبل صاحب الصلاحية، وإبلاغها للعاملين والأطراف الخارجية ذات العلاقة.', 'Policy set with approvals, distribution and acknowledgement records.', 'governance', 'high', 'paraphrased', false, 70),
  ('1-3-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Policies and Procedures', 'سياسات وإجراءات الأمن السيبراني', 'Implement cybersecurity policies and procedures', 'تطبيق سياسات وإجراءات الأمن السيبراني', 'Approved cybersecurity policies and procedures must be implemented across the organization.', 'يجب تطبيق سياسات وإجراءات الأمن السيبراني المعتمدة في الجهة.', 'Implementation evidence, compliance checks.', 'governance', 'high', 'paraphrased', false, 80),
  ('1-3-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Policies and Procedures', 'سياسات وإجراءات الأمن السيبراني', 'Support policies with technical standards', 'دعم السياسات بمعايير تقنية', 'Cybersecurity policies must be supported by technical security standards (e.g., for firewalls, databases, operating systems) that define secure configuration baselines.', 'يجب دعم سياسات الأمن السيبراني بمعايير تقنية للأمن السيبراني (مثل جدران الحماية وقواعد البيانات وأنظمة التشغيل) تحدد خطوط الأساس للإعدادات الآمنة.', 'Technical standards library, baseline configuration documents.', 'preventive', 'medium', 'paraphrased', false, 90),
  ('1-3-4', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Policies and Procedures', 'سياسات وإجراءات الأمن السيبراني', 'Review policies and procedures periodically', 'مراجعة السياسات والإجراءات دورياً', 'Cybersecurity policies and procedures must be reviewed at planned intervals, updated as needed, and changes must be approved and documented.', 'يجب مراجعة سياسات وإجراءات الأمن السيبراني على فترات مخططة وتحديثها عند الحاجة، مع اعتماد التغييرات وتوثيقها.', 'Version history, review schedule, approval records.', 'governance', 'medium', 'paraphrased', false, 100),
  ('1-4-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Roles and Responsibilities', 'أدوار ومسؤوليات الأمن السيبراني', 'Define cybersecurity roles and responsibilities', 'تحديد أدوار ومسؤوليات الأمن السيبراني', 'Cybersecurity roles and responsibilities (including RACI) must be defined, documented and approved by the Authorizing Official for all relevant stakeholders.', 'يجب تحديد وتوثيق واعتماد أدوار ومسؤوليات الأمن السيبراني (بما في ذلك مصفوفة RACI) لجميع الأطراف ذات العلاقة من قبل صاحب الصلاحية.', 'RACI matrix, role descriptions, approvals.', 'governance', 'high', 'paraphrased', false, 110),
  ('1-4-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Roles and Responsibilities', 'أدوار ومسؤوليات الأمن السيبراني', 'Review roles and responsibilities periodically', 'مراجعة الأدوار والمسؤوليات دورياً', 'Cybersecurity roles and responsibilities must be reviewed and updated periodically.', 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني وتحديثها دورياً.', 'Review records.', 'governance', 'low', 'paraphrased', false, 120),
  ('1-5-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Risk Management', 'إدارة مخاطر الأمن السيبراني', 'Define a cybersecurity risk management methodology', 'تحديد منهجية إدارة مخاطر الأمن السيبراني', 'A cybersecurity risk management methodology and procedures must be defined, documented and approved in line with regulatory requirements.', 'يجب تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني بما يتوافق مع المتطلبات التنظيمية.', 'Risk methodology document, risk appetite statement.', 'governance', 'high', 'paraphrased', false, 130),
  ('1-5-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Risk Management', 'إدارة مخاطر الأمن السيبراني', 'Implement cybersecurity risk management procedures', 'تطبيق إجراءات إدارة مخاطر الأمن السيبراني', 'Cybersecurity risk management procedures must be implemented, including risk identification, assessment, treatment and monitoring.', 'يجب تطبيق إجراءات إدارة مخاطر الأمن السيبراني بما يشمل تحديد المخاطر وتقييمها ومعالجتها ومراقبتها.', 'Risk register, treatment plans, risk reports.', 'governance', 'high', 'paraphrased', false, 140),
  ('1-5-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Risk Management', 'إدارة مخاطر الأمن السيبراني', 'Conduct risk assessments at key trigger points', 'إجراء تقييم المخاطر عند نقاط محددة', 'Cybersecurity risk assessments must be conducted at minimum: early in technology projects, before major changes to technology infrastructure, when planning new technology services, and when planning to engage third parties.', 'يجب إجراء تقييم مخاطر الأمن السيبراني كحد أدنى: في المراحل المبكرة للمشاريع التقنية، وقبل إجراء تغييرات جوهرية على البنية التحتية التقنية، وعند التخطيط لخدمات تقنية جديدة، وعند التخطيط للتعاقد مع أطراف خارجية.', 'Risk assessment reports tied to project/change/vendor records.', 'preventive', 'high', 'paraphrased', false, 150),
  ('1-5-4', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity Risk Management', 'إدارة مخاطر الأمن السيبراني', 'Review the risk methodology periodically', 'مراجعة منهجية إدارة المخاطر دورياً', 'The cybersecurity risk management methodology and procedures must be reviewed and updated periodically.', 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها دورياً.', 'Review records.', 'governance', 'low', 'paraphrased', false, 160),
  ('1-6-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity in Information and Technology Project Management', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'Embed cybersecurity in project and change management', 'تضمين الأمن السيبراني في إدارة المشاريع والتغيير', 'Cybersecurity requirements must be included in project management and change management methodologies to protect confidentiality, integrity and availability of information and technology assets.', 'يجب تضمين متطلبات الأمن السيبراني ضمن منهجيات إدارة المشاريع وإدارة التغيير لحماية سرية وسلامة وتوافر الأصول المعلوماتية والتقنية.', 'Project methodology with security gates, change templates.', 'preventive', 'high', 'paraphrased', false, 170),
  ('1-6-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity in Information and Technology Project Management', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'Minimum cybersecurity requirements for projects', 'الحد الأدنى من متطلبات الأمن السيبراني للمشاريع', 'Cybersecurity requirements for projects and changes must cover at minimum: vulnerability assessment and remediation, and review of secure configuration and hardening before go-live.', 'يجب أن تغطي متطلبات الأمن السيبراني للمشاريع والتغييرات كحد أدنى: تقييم الثغرات ومعالجتها، ومراجعة الإعدادات الآمنة والتحصين قبل الإطلاق.', 'Pre-go-live security sign-off, vulnerability reports.', 'preventive', 'high', 'paraphrased', false, 180),
  ('1-6-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Cybersecurity in Information and Technology Project Management', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'Secure software development requirements', 'متطلبات التطوير الآمن للبرمجيات', 'Cybersecurity requirements for software and application development projects must cover at minimum: secure coding standards, trusted sources for development tools and libraries, security testing, secure integration between applications, and secure configuration review before go-live.', 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير البرمجيات والتطبيقات كحد أدنى: معايير البرمجة الآمنة، والمصادر الموثوقة لأدوات ومكتبات التطوير، واختبارات الأمن، والتكامل الآمن بين التطبيقات، ومراجعة الإعدادات الآمنة قبل الإطلاق.', 'Secure SDLC standard, SAST/DAST reports, dependency policy.', 'preventive', 'high', 'paraphrased', false, 190),
  ('1-7-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Compliance with Cybersecurity Standards, Laws and Regulations', 'الالتزام بالمعايير والتشريعات والتنظيمات ذات العلاقة بالأمن السيبراني', 'Comply with national cybersecurity legislation', 'الالتزام بالتشريعات الوطنية للأمن السيبراني', 'The organization must comply with applicable national cybersecurity laws, regulations and NCA requirements.', 'يجب على الجهة الالتزام بالتشريعات والتنظيمات الوطنية ومتطلبات الهيئة ذات العلاقة بالأمن السيبراني.', 'Compliance register, NCA assessment submissions.', 'governance', 'high', 'paraphrased', false, 200),
  ('1-7-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Compliance with Cybersecurity Standards, Laws and Regulations', 'الالتزام بالمعايير والتشريعات والتنظيمات ذات العلاقة بالأمن السيبراني', 'Comply with international agreements and standards', 'الالتزام بالاتفاقيات والمعايير الدولية', 'The organization must comply with cybersecurity requirements arising from international agreements or commitments it has entered into.', 'يجب على الجهة الالتزام بمتطلبات الأمن السيبراني الناشئة عن الاتفاقيات أو الالتزامات الدولية التي انضمت إليها.', 'Inventory of applicable international obligations.', 'governance', 'medium', 'paraphrased', false, 210),
  ('1-8-1', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Periodical Cybersecurity Review and Audit', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'Periodic self-review by the cybersecurity function', 'المراجعة الدورية من قبل إدارة الأمن السيبراني', 'The cybersecurity function must periodically review the implementation of cybersecurity controls across the organization.', 'يجب على إدارة الأمن السيبراني مراجعة تطبيق ضوابط الأمن السيبراني في الجهة بشكل دوري.', 'Self-assessment reports, remediation tracking.', 'detective', 'medium', 'paraphrased', false, 220),
  ('1-8-2', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Periodical Cybersecurity Review and Audit', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'Independent cybersecurity audit', 'التدقيق المستقل للأمن السيبراني', 'Cybersecurity implementation must be reviewed and audited by independent parties (e.g., internal audit) outside the cybersecurity function, in line with accepted audit standards and regulatory requirements.', 'يجب مراجعة وتدقيق تطبيق الأمن السيبراني من قبل أطراف مستقلة (مثل المراجعة الداخلية) من خارج إدارة الأمن السيبراني، وفقاً لمعايير التدقيق المتعارف عليها والمتطلبات التنظيمية.', 'Audit plan, audit reports, management responses.', 'detective', 'high', 'paraphrased', false, 230),
  ('1-8-3', 'Cybersecurity Governance', 'حوكمة الأمن السيبراني', 'Periodical Cybersecurity Review and Audit', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'Report review and audit results to the steering committee', 'رفع نتائج المراجعة والتدقيق للجنة الإشرافية', 'Results of cybersecurity reviews and audits must be documented and presented to the cybersecurity steering committee and the Authorizing Official, including findings, recommendations and remediation plans.', 'يجب توثيق نتائج مراجعات وتدقيق الأمن السيبراني وعرضها على اللجنة الإشرافية وصاحب الصلاحية، بما يشمل الملاحظات والتوصيات وخطط المعالجة.', 'Committee minutes with audit findings.', 'governance', 'medium', 'paraphrased', false, 240),
