-- NIST-CSF: NIST Cybersecurity Framework 2.0 (106 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('NIST-CSF', 'NIST CSF 2.0', 'NIST Cybersecurity Framework 2.0', 'إطار الأمن السيبراني للمعهد الوطني الأمريكي للمعايير والتقنية (NIST CSF 2.0)', 'U.S. National Institute of Standards and Technology (NIST)', 'المعهد الوطني للمعايير والتقنية (الولايات المتحدة)', 'INTL', 'cybersecurity', '2.0', '2024-02-26', 'https://www.nist.gov/cyberframework', 'A voluntary, outcome-based framework for managing cybersecurity risk, organized into six Functions — Govern, Identify, Protect, Detect, Respond, Recover — 22 Categories and 106 Subcategories. Widely used in the GCC as a reference architecture for cybersecurity programs and as a crosswalk target for SAMA CSF and NCA ECC.', 'إطار طوعي قائم على النتائج لإدارة مخاطر الأمن السيبراني، منظم في ست وظائف — الحوكمة، التحديد، الحماية، الاكتشاف، الاستجابة، التعافي — و22 فئة و106 فئات فرعية. يُستخدم على نطاق واسع في دول الخليج كمرجع لبرامج الأمن السيبراني وكهدف للمواءمة مع SAMA CSF وNCA ECC.', false, 80)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

