-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('QA-NIA', 'Qatar NIA Policy', 'Qatar National Information Assurance (NIA) Policy', 'سياسة ضمان المعلومات الوطنية لدولة قطر', 'National Cyber Security Agency (NCSA), Qatar', 'الوكالة الوطنية للأمن السيبراني، قطر', 'QA', 'information-security', '2.1', '2023-01-01', 'https://www.ncsa.gov.qa/en', 'Qatar''s national information assurance baseline, originally issued by MOTC/Q-CERT and now maintained by the National Cyber Security Agency. Mandatory for government entities and critical sector organizations; used as the basis for NIA certification. Organized into governance domains and technical security domains. Rows summarize each domain''s core obligations; verify against the current NCSA publication before formal use.', 'خط الأساس الوطني لضمان المعلومات في قطر، صدر أصلاً عن وزارة المواصلات والاتصالات/كيوسيرت وتتولاه الآن الوكالة الوطنية للأمن السيبراني. إلزامي للجهات الحكومية ومؤسسات القطاعات الحرجة؛ ويُستخدم كأساس لشهادة ضمان المعلومات الوطنية. منظم في مجالات حوكمة ومجالات أمن تقنية. تلخص الصفوف الالتزامات الأساسية لكل مجال؛ يجب التحقق منها مقابل منشور الوكالة الحالي قبل الاستخدام الرسمي.', true, 50)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('GS', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Governance Structure', 'هيكل الحوكمة', 'Establish an information security governance structure with senior management accountability, an appointed information security manager, an information security policy approved by management, and defined roles for asset owners and custodians.', 'إنشاء هيكل لحوكمة أمن المعلومات بمساءلة الإدارة العليا، وتعيين مدير لأمن المعلومات، وسياسة لأمن المعلومات معتمدة من الإدارة، وأدوار محددة لمالكي الأصول والمشرفين عليها.', null, 'governance', 'high', 'summarized', false, 10),
  ('RM', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Risk Management', 'إدارة المخاطر', 'Implement an information security risk management process aligned to the national risk assessment methodology, covering asset identification, threat and vulnerability analysis, risk evaluation, treatment and periodic review.', 'تنفيذ عملية لإدارة مخاطر أمن المعلومات متوافقة مع المنهجية الوطنية لتقييم المخاطر، تغطي تحديد الأصول وتحليل التهديدات والثغرات وتقييم المخاطر ومعالجتها والمراجعة الدورية.', null, 'governance', 'high', 'summarized', false, 20),
  ('TM', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Third Party Security Management', 'إدارة أمن الأطراف الخارجية', 'Assess third parties before engagement, include security requirements and right-to-audit in contracts, and monitor third-party compliance throughout the relationship; sensitive data hosted by third parties must remain within Qatar unless approved.', 'تقييم الأطراف الخارجية قبل التعاقد، وتضمين المتطلبات الأمنية وحق التدقيق في العقود، ومراقبة امتثال الأطراف الخارجية طوال العلاقة؛ ويجب أن تبقى البيانات الحساسة المستضافة لدى أطراف خارجية داخل قطر ما لم تتم الموافقة على خلاف ذلك.', null, 'governance', 'high', 'summarized', false, 30),
  ('DL', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Data Labelling', 'وسم البيانات', 'Classify and label information according to the national classification scheme (e.g., Public, Internal, Restricted, Confidential, Secret) and apply handling controls proportionate to the label.', 'تصنيف المعلومات ووسمها وفق آلية التصنيف الوطنية (مثل عام، داخلي، مقيد، سري، سري للغاية) وتطبيق ضوابط تعامل تتناسب مع التصنيف.', null, 'preventive', 'high', 'summarized', false, 40),
  ('CM', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Change Management', 'إدارة التغيير', 'Control changes to information systems through formal request, security impact assessment, approval, testing and documented rollback.', 'التحكم في التغييرات على أنظمة المعلومات من خلال طلب رسمي وتقييم الأثر الأمني والاعتماد والاختبار والتراجع الموثق.', null, 'preventive', 'high', 'summarized', false, 50),
  ('PS', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Personnel Security', 'أمن الأفراد', 'Screen personnel before employment according to role sensitivity, define security responsibilities in employment terms, and manage access on role change and termination.', 'التحقق من الأفراد قبل التوظيف وفق حساسية الدور، وتحديد المسؤوليات الأمنية في شروط العمل، وإدارة الصلاحيات عند تغيير الدور والإنهاء.', null, 'preventive', 'medium', 'summarized', false, 60),
  ('AT', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Security Awareness', 'التوعية الأمنية', 'Provide security awareness to all personnel at induction and periodically thereafter, with specialized training for security and IT staff.', 'توفير التوعية الأمنية لجميع العاملين عند الالتحاق وبشكل دوري، مع تدريب متخصص لموظفي الأمن وتقنية المعلومات.', null, 'preventive', 'medium', 'summarized', false, 70),
  ('IM', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Incident Management', 'إدارة الحوادث', 'Establish incident detection, reporting, classification, response and post-incident review processes, and report incidents to the national CERT (Q-CERT / NCSA) within required timelines.', 'إنشاء عمليات لاكتشاف الحوادث والإبلاغ عنها وتصنيفها والاستجابة لها والمراجعة بعد الحادث، والإبلاغ عن الحوادث إلى فريق الاستجابة الوطني (كيوسيرت / الوكالة) ضمن المدد المطلوبة.', null, 'corrective', 'high', 'summarized', false, 80),
  ('BC', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Business Continuity Management', 'إدارة استمرارية الأعمال', 'Perform business impact analysis, develop and test business continuity and disaster recovery plans for critical systems, and review them at least annually.', 'إجراء تحليل الأثر على الأعمال، ووضع واختبار خطط استمرارية الأعمال والتعافي من الكوارث للأنظمة الحرجة، ومراجعتها سنوياً على الأقل.', null, 'corrective', 'high', 'summarized', false, 90),
  ('SM', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Logging and Security Monitoring', 'التسجيل والمراقبة الأمنية', 'Enable logging on critical systems, protect and retain logs per the national retention requirement, synchronize time, and monitor logs for security events.', 'تفعيل التسجيل على الأنظمة الحرجة، وحماية السجلات والاحتفاظ بها وفق متطلبات الاحتفاظ الوطنية، ومزامنة الوقت، ومراقبة السجلات لاكتشاف الأحداث الأمنية.', null, 'detective', 'high', 'summarized', false, 100),
  ('DR', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Data Retention and Archival', 'الاحتفاظ بالبيانات وأرشفتها', 'Define retention periods for information in line with legal requirements, archive securely, and dispose of information securely at end of retention.', 'تحديد فترات الاحتفاظ بالمعلومات وفق المتطلبات القانونية، والأرشفة الآمنة، والتخلص الآمن من المعلومات عند انتهاء فترة الاحتفاظ.', null, 'preventive', 'medium', 'summarized', false, 110),
  ('DC', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Documentation', 'التوثيق', 'Maintain current, approved and controlled documentation of policies, procedures, architectures and configurations supporting the information security program.', 'الاحتفاظ بوثائق محدثة ومعتمدة ومضبوطة للسياسات والإجراءات والبنى والإعدادات الداعمة لبرنامج أمن المعلومات.', null, 'governance', 'low', 'summarized', false, 120),
  ('AC', 'Governance Domains', 'مجالات الحوكمة', null, null, 'Audit and Certification', 'التدقيق والاعتماد', 'Conduct periodic internal audits against the NIA Policy, remediate findings, and undergo NIA certification assessment where mandated.', 'إجراء تدقيق داخلي دوري مقابل سياسة ضمان المعلومات الوطنية، ومعالجة الملاحظات، والخضوع لتقييم شهادة ضمان المعلومات الوطنية حيثما يكون إلزامياً.', null, 'detective', 'medium', 'summarized', false, 130),
  ('CS', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Communications Security', 'أمن الاتصالات', 'Protect voice, video and data communications, including secure configuration of PBX/VoIP, fax and messaging, and encryption for sensitive communications.', 'حماية اتصالات الصوت والفيديو والبيانات، بما في ذلك الإعداد الآمن لأنظمة الهاتف والاتصال عبر الإنترنت والفاكس والمراسلة، والتشفير للاتصالات الحساسة.', null, 'preventive', 'medium', 'summarized', false, 140),
  ('NS', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Network Security', 'أمن الشبكات', 'Design networks with security zones and segmentation, deploy firewalls and intrusion detection/prevention, harden network devices, secure wireless networks and control remote access.', 'تصميم الشبكات بمناطق أمنية وعزل، ونشر جدران الحماية وأنظمة كشف ومنع الاختراق، وتحصين أجهزة الشبكة، وتأمين الشبكات اللاسلكية، والتحكم في الوصول عن بُعد.', null, 'preventive', 'high', 'summarized', false, 150),
  ('IE', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Information Exchange', 'تبادل المعلومات', 'Govern exchange of information with external parties through agreements, approved channels and protection proportionate to classification.', 'تنظيم تبادل المعلومات مع الأطراف الخارجية من خلال اتفاقيات وقنوات معتمدة وحماية تتناسب مع التصنيف.', null, 'preventive', 'medium', 'summarized', false, 160),
  ('GW', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Gateway Security', 'أمن البوابات', 'Secure internet and inter-network gateways with content filtering, malware inspection, proxying, email security and data leakage controls.', 'تأمين بوابات الإنترنت والبوابات بين الشبكات بتصفية المحتوى وفحص البرمجيات الضارة والوكلاء وأمن البريد الإلكتروني وضوابط منع تسرب البيانات.', null, 'preventive', 'high', 'summarized', false, 170),
  ('PR', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Product Security', 'أمن المنتجات', 'Select security products and ICT equipment that meet national evaluation requirements and maintain them in supported, patched configurations.', 'اختيار المنتجات الأمنية ومعدات تقنية المعلومات التي تستوفي متطلبات التقييم الوطنية وصيانتها بإعدادات مدعومة ومحدثة.', null, 'preventive', 'medium', 'summarized', false, 180),
  ('SS', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Software Security', 'أمن البرمجيات', 'Apply secure development lifecycle practices, secure coding, application security testing and secure configuration of operating systems, databases and applications.', 'تطبيق ممارسات دورة حياة التطوير الآمن والبرمجة الآمنة واختبار أمن التطبيقات والإعداد الآمن لأنظمة التشغيل وقواعد البيانات والتطبيقات.', null, 'preventive', 'high', 'summarized', false, 190),
  ('AM', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Access Control Security', 'أمن التحكم في الوصول', 'Manage user identities and access through formal provisioning, least privilege, strong authentication (multi-factor for privileged and remote access), privileged account controls and periodic access reviews.', 'إدارة هويات المستخدمين والوصول من خلال المنح الرسمي والحد الأدنى من الصلاحيات والمصادقة القوية (متعددة العناصر للوصول المميز وعن بُعد) وضوابط الحسابات المميزة والمراجعات الدورية للصلاحيات.', null, 'preventive', 'high', 'summarized', false, 200),
  ('CY', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Cryptographic Security', 'أمن التشفير', 'Use approved cryptographic algorithms and key lengths, protect data at rest and in transit according to classification, and manage keys across their lifecycle.', 'استخدام خوارزميات التشفير وأطوال المفاتيح المعتمدة، وحماية البيانات أثناء التخزين والنقل وفق التصنيف، وإدارة المفاتيح طوال دورة حياتها.', null, 'preventive', 'high', 'summarized', false, 210),
  ('PD', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Portable Devices and Working Off-site', 'الأجهزة المحمولة والعمل خارج الموقع', 'Protect portable devices and removable media with encryption, device management and remote wipe, and define rules for teleworking and off-site handling of information.', 'حماية الأجهزة المحمولة والوسائط القابلة للإزالة بالتشفير وإدارة الأجهزة والمسح عن بُعد، وتحديد قواعد العمل عن بُعد والتعامل مع المعلومات خارج الموقع.', null, 'preventive', 'medium', 'summarized', false, 220),
  ('PH', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Physical Security', 'الأمن المادي', 'Protect facilities housing information assets with physical access control, monitoring, environmental protection and secure equipment disposal.', 'حماية المرافق التي تضم الأصول المعلوماتية بالتحكم في الدخول المادي والمراقبة والحماية البيئية والتخلص الآمن من المعدات.', null, 'preventive', 'medium', 'summarized', false, 230),
  ('VL', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Virtualization', 'المحاكاة الافتراضية', 'Secure virtualized environments through hypervisor hardening, isolation of virtual machines by classification, controlled administrative access and monitoring.', 'تأمين البيئات الافتراضية من خلال تحصين برامج المحاكاة وعزل الأجهزة الافتراضية حسب التصنيف والتحكم في الوصول الإداري والمراقبة.', null, 'preventive', 'medium', 'summarized', false, 240),
  ('CL', 'Technical Security Domains', 'مجالات الأمن التقني', null, null, 'Cloud Security', 'أمن الحوسبة السحابية', 'Assess cloud services against national cloud security requirements before adoption, ensure data classification-based restrictions and data residency, contractual security obligations, tenant isolation and exit provisions.', 'تقييم الخدمات السحابية مقابل متطلبات أمن الحوسبة السحابية الوطنية قبل اعتمادها، وضمان القيود المبنية على تصنيف البيانات وبقاء البيانات محلياً والالتزامات الأمنية التعاقدية وعزل المستأجرين وأحكام الخروج.', null, 'governance', 'high', 'summarized', false, 250)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'QA-NIA'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- QCB-TRM: Qatar Central Bank — Technology Risk and Information Security Requirements (20 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('QCB-TRM', 'QCB Technology Risk', 'Qatar Central Bank — Technology Risk and Information Security Requirements', 'مصرف قطر المركزي — متطلبات مخاطر التقنية وأمن المعلومات', 'Qatar Central Bank (QCB)', 'مصرف قطر المركزي', 'QA', 'technology-risk', 'Technology Risk Circular (2018) and subsequent cybersecurity instructions', '2018-01-01', 'https://www.qcb.gov.qa/en/legislation', 'Consolidated view of QCB''s technology risk, information security and cybersecurity expectations for banks, insurers, exchange houses, payment service providers and other QCB-licensed entities, drawing on the Technology Risk Circular and later cybersecurity, cloud and outsourcing instructions. Rows summarize the recurring obligations by theme; QCB issues requirements through numbered circulars, so verify the current applicable circular for each theme before formal use.', 'نظرة موحدة على توقعات مصرف قطر المركزي بشأن مخاطر التقنية وأمن المعلومات والأمن السيبراني للبنوك وشركات التأمين ومحلات الصرافة ومقدمي خدمات الدفع وسائر الجهات المرخصة، استناداً إلى تعميم مخاطر التقنية وتعليمات الأمن السيبراني والحوسبة السحابية والإسناد اللاحقة. تلخص الصفوف الالتزامات المتكررة حسب الموضوع؛ ويصدر المصرف متطلباته عبر تعاميم مرقمة، لذا يجب التحقق من التعميم الساري لكل موضوع قبل الاستخدام الرسمي.', true, 55)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('QCB-GOV-1', 'Governance and Risk Management', 'الحوكمة وإدارة المخاطر', null, null, 'Board and senior management oversight of technology risk', 'إشراف مجلس الإدارة والإدارة العليا على مخاطر التقنية', 'The board must approve the technology risk and information security strategy and policies, ensure adequate resources, and receive regular reporting on technology risk posture, incidents and compliance.', 'يجب على مجلس الإدارة اعتماد استراتيجية وسياسات مخاطر التقنية وأمن المعلومات، وضمان الموارد الكافية، وتلقي تقارير منتظمة عن وضع مخاطر التقنية والحوادث والامتثال.', null, 'governance', 'high', 'summarized', false, 10),
  ('QCB-GOV-2', 'Governance and Risk Management', 'الحوكمة وإدارة المخاطر', null, null, 'Information security function and CISO', 'وظيفة أمن المعلومات ورئيس أمن المعلومات', 'Establish an information security function headed by a qualified senior officer with independence from IT operations, and a technology/IT risk committee with defined charter.', 'إنشاء وظيفة لأمن المعلومات يرأسها مسؤول رفيع مؤهل ومستقل عن عمليات تقنية المعلومات، ولجنة لمخاطر التقنية بميثاق محدد.', null, 'governance', 'high', 'summarized', false, 20),
  ('QCB-GOV-3', 'Governance and Risk Management', 'الحوكمة وإدارة المخاطر', null, null, 'Technology risk management framework', 'إطار إدارة مخاطر التقنية', 'Implement a technology risk management framework integrated with enterprise risk management, including risk identification, assessment, treatment, monitoring and a maintained risk register.', 'تنفيذ إطار لإدارة مخاطر التقنية متكامل مع إدارة المخاطر المؤسسية، يشمل تحديد المخاطر وتقييمها ومعالجتها ومراقبتها وسجل مخاطر محدث.', null, 'governance', 'high', 'summarized', false, 30),
  ('QCB-GOV-4', 'Governance and Risk Management', 'الحوكمة وإدارة المخاطر', null, null, 'Policies, standards and compliance monitoring', 'السياسات والمعايير ومراقبة الامتثال', 'Maintain approved information security policies and technical standards, review them annually, and monitor compliance with QCB requirements and international standards adopted by the institution.', 'الاحتفاظ بسياسات أمن معلومات ومعايير تقنية معتمدة، ومراجعتها سنوياً، ومراقبة الامتثال لمتطلبات المصرف والمعايير الدولية التي تتبناها المؤسسة.', null, 'governance', 'medium', 'summarized', false, 40),
  ('QCB-GOV-5', 'Governance and Risk Management', 'الحوكمة وإدارة المخاطر', null, null, 'Independent assurance', 'التأكيد المستقل', 'Subject technology and information security controls to periodic independent audit (internal audit and, where required, external assessment) with findings reported to the audit committee and tracked to closure.', 'إخضاع ضوابط التقنية وأمن المعلومات لتدقيق مستقل دوري (المراجعة الداخلية وعند الاقتضاء التقييم الخارجي) مع رفع الملاحظات إلى لجنة المراجعة ومتابعتها حتى الإغلاق.', null, 'detective', 'medium', 'summarized', false, 50),
  ('QCB-SEC-1', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Asset management and data classification', 'إدارة الأصول وتصنيف البيانات', 'Maintain an inventory of information and technology assets with owners and classify information, with customer and financial data treated as confidential and protected accordingly.', 'الاحتفاظ بجرد للأصول المعلوماتية والتقنية مع تحديد المالكين وتصنيف المعلومات، مع معاملة بيانات العملاء والبيانات المالية كمعلومات سرية وحمايتها وفقاً لذلك.', null, 'preventive', 'high', 'summarized', false, 60),
  ('QCB-SEC-2', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Identity, access and privileged access management', 'إدارة الهوية والوصول والوصول المميز', 'Enforce least privilege, formal access provisioning and periodic recertification, multi-factor authentication for remote and privileged access, and monitoring of privileged activity.', 'فرض الحد الأدنى من الصلاحيات، والمنح الرسمي للوصول وإعادة الاعتماد الدوري، والمصادقة متعددة العناصر للوصول عن بُعد والمميز، ومراقبة نشاط الحسابات المميزة.', null, 'preventive', 'high', 'summarized', false, 70),
  ('QCB-SEC-3', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Network, endpoint and infrastructure security', 'أمن الشبكات والأجهزة الطرفية والبنية التحتية', 'Segment networks, protect perimeters with firewalls and intrusion prevention, harden systems against baselines, deploy centrally managed malware protection and apply security patches within defined timelines.', 'عزل الشبكات، وحماية المحيط بجدران الحماية وأنظمة منع الاختراق، وتحصين الأنظمة وفق خطوط الأساس، ونشر حماية مدارة مركزياً من البرمجيات الضارة، وتطبيق التحديثات الأمنية ضمن مدد محددة.', null, 'preventive', 'high', 'summarized', false, 80),
  ('QCB-SEC-4', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Cryptography and data protection', 'التشفير وحماية البيانات', 'Encrypt confidential data at rest and in transit using approved algorithms, manage keys securely (HSM for payment and card systems), and apply data leakage prevention controls.', 'تشفير البيانات السرية أثناء التخزين والنقل بخوارزميات معتمدة، وإدارة المفاتيح بشكل آمن (وحدات الأمن المادية لأنظمة الدفع والبطاقات)، وتطبيق ضوابط منع تسرب البيانات.', null, 'preventive', 'high', 'summarized', false, 90),
  ('QCB-SEC-5', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Secure development and change management', 'التطوير الآمن وإدارة التغيير', 'Apply secure development lifecycle practices, security testing before release, and formal change management with segregation of development, test and production.', 'تطبيق ممارسات دورة حياة التطوير الآمن، واختبار الأمن قبل الإطلاق، وإدارة التغيير الرسمية مع فصل بيئات التطوير والاختبار والإنتاج.', null, 'preventive', 'high', 'summarized', false, 100),
  ('QCB-SEC-6', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Vulnerability management and penetration testing', 'إدارة الثغرات واختبار الاختراق', 'Perform regular vulnerability scanning and at least annual penetration testing of internet-facing and critical systems by qualified independent testers, and remediate findings by risk within defined timelines.', 'إجراء فحص دوري للثغرات واختبار اختراق سنوي على الأقل للأنظمة المتصلة بالإنترنت والأنظمة الحرجة من قبل مختبرين مستقلين مؤهلين، ومعالجة الملاحظات وفق المخاطر ضمن مدد محددة.', null, 'detective', 'high', 'summarized', false, 110),
  ('QCB-SEC-7', 'Information Security Operations', 'عمليات أمن المعلومات', null, null, 'Security monitoring and logging', 'المراقبة الأمنية والتسجيل', 'Centrally collect and monitor security logs from critical systems on a 24/7 basis, retain logs for the period required by QCB, and protect log integrity.', 'تجميع ومراقبة السجلات الأمنية من الأنظمة الحرجة مركزياً على مدار الساعة، والاحتفاظ بالسجلات للمدة التي يحددها المصرف، وحماية سلامتها.', null, 'detective', 'high', 'summarized', false, 120),
  ('QCB-DIG-1', 'Digital Channels and Payments', 'القنوات الرقمية والمدفوعات', null, null, 'Electronic banking and mobile channel security', 'أمن القنوات المصرفية الإلكترونية والهاتف المحمول', 'Implement multi-factor customer authentication, transaction signing or verification for high-risk transactions, session security, anti-fraud monitoring and customer awareness for internet and mobile banking.', 'تطبيق مصادقة العملاء متعددة العناصر، والتوقيع أو التحقق من المعاملات عالية المخاطر، وأمن الجلسات، ومراقبة مكافحة الاحتيال، وتوعية العملاء للخدمات المصرفية عبر الإنترنت والهاتف المحمول.', null, 'preventive', 'high', 'summarized', false, 130),
  ('QCB-DIG-2', 'Digital Channels and Payments', 'القنوات الرقمية والمدفوعات', null, null, 'Payment systems and card security', 'أمن أنظمة الدفع والبطاقات', 'Comply with applicable payment scheme standards (PCI DSS, SWIFT CSP), segregate payment infrastructure, and monitor payment transactions for fraud and anomalies.', 'الالتزام بمعايير شبكات الدفع المعمول بها (PCI DSS وبرنامج أمن العملاء لسويفت)، وعزل البنية التحتية للدفع، ومراقبة معاملات الدفع لاكتشاف الاحتيال والشذوذ.', null, 'preventive', 'high', 'summarized', false, 140),
  ('QCB-DIG-3', 'Digital Channels and Payments', 'القنوات الرقمية والمدفوعات', null, null, 'Open APIs and fintech integrations', 'واجهات البرمجة المفتوحة وتكاملات التقنية المالية', 'Secure APIs exposed to third parties with strong authentication, authorization, rate limiting, input validation and monitoring, and assess fintech partners before integration.', 'تأمين واجهات البرمجة المتاحة للأطراف الخارجية بمصادقة وتفويض قويين وتحديد المعدل والتحقق من المدخلات والمراقبة، وتقييم شركاء التقنية المالية قبل التكامل.', null, 'preventive', 'medium', 'summarized', false, 150),
  ('QCB-RES-1', 'Resilience, Incidents and Third Parties', 'الصمود والحوادث والأطراف الخارجية', null, null, 'Business continuity and disaster recovery', 'استمرارية الأعمال والتعافي من الكوارث', 'Maintain business continuity and IT disaster recovery plans for critical services with defined RTO/RPO, an alternate site, and at least annual testing with results reported to the board.', 'الاحتفاظ بخطط لاستمرارية الأعمال والتعافي من الكوارث للخدمات الحرجة مع تحديد أهداف وقت ونقطة الاستعادة وموقع بديل واختبار سنوي على الأقل مع رفع النتائج إلى مجلس الإدارة.', null, 'corrective', 'high', 'summarized', false, 160),
  ('QCB-RES-2', 'Resilience, Incidents and Third Parties', 'الصمود والحوادث والأطراف الخارجية', null, null, 'Cyber incident management and QCB notification', 'إدارة الحوادث السيبرانية وإخطار المصرف', 'Maintain an incident response plan with defined severity levels, and notify QCB of significant cyber incidents and service disruptions within the timelines set by QCB, followed by root-cause and remediation reports.', 'الاحتفاظ بخطة للاستجابة للحوادث بمستويات خطورة محددة، وإخطار المصرف بالحوادث السيبرانية الجسيمة وانقطاع الخدمات ضمن المدد التي يحددها، يليها تقارير السبب الجذري والمعالجة.', null, 'corrective', 'high', 'summarized', false, 170),
  ('QCB-RES-3', 'Resilience, Incidents and Third Parties', 'الصمود والحوادث والأطراف الخارجية', null, null, 'Outsourcing and third-party risk', 'الإسناد الخارجي ومخاطر الأطراف الخارجية', 'Obtain QCB approval for material outsourcing, perform due diligence and risk assessment, include security, audit, data protection and exit clauses in contracts, and monitor providers on an ongoing basis.', 'الحصول على موافقة المصرف للإسناد الجوهري، وإجراء العناية الواجبة وتقييم المخاطر، وتضمين بنود الأمن والتدقيق وحماية البيانات والخروج في العقود، ومراقبة مقدمي الخدمات بشكل مستمر.', null, 'governance', 'high', 'summarized', false, 180),
  ('QCB-RES-4', 'Resilience, Incidents and Third Parties', 'الصمود والحوادث والأطراف الخارجية', null, null, 'Cloud computing', 'الحوسبة السحابية', 'Use of cloud services for material systems or customer data requires risk assessment, QCB non-objection where applicable, data residency and sovereignty considerations, encryption, provider assurance and a documented exit strategy.', 'يتطلب استخدام الخدمات السحابية للأنظمة الجوهرية أو بيانات العملاء تقييم المخاطر، وعدم ممانعة المصرف عند الاقتضاء، ومراعاة بقاء البيانات وسيادتها، والتشفير، وتأكيد مقدم الخدمة، واستراتيجية خروج موثقة.', null, 'governance', 'high', 'summarized', false, 190),
  ('QCB-RES-5', 'Resilience, Incidents and Third Parties', 'الصمود والحوادث والأطراف الخارجية', null, null, 'Data residency and customer data confidentiality', 'بقاء البيانات محلياً وسرية بيانات العملاء', 'Customer and transaction data must be protected in accordance with QCB confidentiality requirements and Qatar''s data privacy law, with cross-border transfer or hosting subject to QCB requirements.', 'يجب حماية بيانات العملاء والمعاملات وفق متطلبات السرية لدى المصرف وقانون حماية خصوصية البيانات القطري، مع خضوع النقل أو الاستضافة خارج الدولة لمتطلبات المصرف.', null, 'preventive', 'high', 'summarized', false, 200)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'QCB-TRM'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- SAMA-CSF: SAMA Cyber Security Framework (48 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('SAMA-CSF', 'SAMA CSF', 'SAMA Cyber Security Framework', 'إطار الأمن السيبراني للبنك المركزي السعودي (ساما)', 'Saudi Central Bank (SAMA)', 'البنك المركزي السعودي', 'SA', 'cybersecurity', '1.0', '2017-05-01', 'https://www.sama.gov.sa/en-US/RulesInstructions/CyberSecurity/Cyber%20Security%20Framework.pdf', 'Mandatory framework for all SAMA-regulated member organizations (banks, insurers, financing companies, payment providers, credit bureaus). Four domains — Leadership & Governance, Risk Management & Compliance, Operations & Technology, Third Party — each broken into subdomains with a principle, objective and control considerations, assessed on a 0–5 maturity scale. Rows at the subdomain level carry the principle; numbered sub-rows carry key control considerations.', 'إطار إلزامي لجميع المؤسسات الخاضعة لإشراف البنك المركزي السعودي (البنوك وشركات التأمين والتمويل ومقدمي خدمات الدفع وشركات المعلومات الائتمانية). أربعة مجالات — القيادة والحوكمة، إدارة المخاطر والالتزام، العمليات والتقنية، الأطراف الخارجية — تنقسم إلى مجالات فرعية لكل منها مبدأ وهدف واعتبارات ضبط، وتُقيَّم على مقياس نضج من 0 إلى 5.', true, 20)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('3.1.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.1 Cyber Security Governance', '3.1.1 حوكمة الأمن السيبراني', 'Establish cyber security governance', 'إرساء حوكمة الأمن السيبراني', 'The member organization must define, approve, implement, communicate and monitor a cyber security governance structure that provides board-level direction and oversight of the cyber security program.', 'يجب على المؤسسة العضو تحديد واعتماد وتطبيق وإبلاغ ومراقبة هيكل حوكمة للأمن السيبراني يوفر التوجيه والإشراف على مستوى مجلس الإدارة لبرنامج الأمن السيبراني.', 'Board mandate, governance charter, committee minutes.', 'governance', 'high', 'paraphrased', false, 10),
  ('3.1.1.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.1 Cyber Security Governance', '3.1.1 حوكمة الأمن السيبراني', 'Board accountability for cyber security', 'مسؤولية مجلس الإدارة عن الأمن السيبراني', 'The board of directors is ultimately responsible for cyber security, endorses the cyber security strategy and policy, and receives periodic reporting on cyber security status and risks.', 'يتحمل مجلس الإدارة المسؤولية النهائية عن الأمن السيبراني، ويعتمد استراتيجية وسياسة الأمن السيبراني، ويتلقى تقارير دورية عن حالة الأمن السيبراني ومخاطره.', null, 'governance', 'high', 'paraphrased', false, 20),
  ('3.1.1.2', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.1 Cyber Security Governance', '3.1.1 حوكمة الأمن السيبراني', 'Cyber security committee', 'لجنة الأمن السيبراني', 'A cyber security committee, chaired by a senior executive and including the CISO and business/IT representatives, must be established with a documented charter to oversee cyber security initiatives and risk decisions.', 'يجب إنشاء لجنة للأمن السيبراني برئاسة تنفيذي رفيع المستوى وعضوية رئيس أمن المعلومات وممثلي الأعمال وتقنية المعلومات، بميثاق موثق للإشراف على مبادرات الأمن السيبراني وقرارات المخاطر.', null, 'governance', 'high', 'paraphrased', false, 30),
  ('3.1.1.3', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.1 Cyber Security Governance', '3.1.1 حوكمة الأمن السيبراني', 'Independent cyber security function', 'وظيفة مستقلة للأمن السيبراني', 'A cyber security function headed by a full-time senior manager (CISO) must be established, independent of IT, with sufficient authority, budget and Saudi-national staffing.', 'يجب إنشاء وظيفة للأمن السيبراني يرأسها مدير رفيع المستوى بدوام كامل (رئيس أمن المعلومات) تكون مستقلة عن تقنية المعلومات وتتمتع بالصلاحيات والميزانية الكافية وبتوطين الوظائف.', null, 'governance', 'high', 'paraphrased', false, 40),
  ('3.1.2', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.2 Cyber Security Strategy', '3.1.2 استراتيجية الأمن السيبراني', 'Define and maintain a cyber security strategy', 'تحديد استراتيجية الأمن السيبراني والمحافظة عليها', 'A cyber security strategy, aligned with the organization''s strategic objectives and SAMA requirements, must be defined, approved by the board, maintained and executed through a roadmap.', 'يجب تحديد استراتيجية للأمن السيبراني تتوافق مع الأهداف الاستراتيجية للمؤسسة ومتطلبات البنك المركزي، واعتمادها من مجلس الإدارة، والمحافظة عليها وتنفيذها عبر خطة عمل.', null, 'governance', 'high', 'paraphrased', false, 50),
  ('3.1.2.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.2 Cyber Security Strategy', '3.1.2 استراتيجية الأمن السيبراني', 'Strategy content', 'محتوى الاستراتيجية', 'The strategy must set the importance and objectives of cyber security, current and target maturity, the initiatives and roadmap to close gaps, and required resources and budget.', 'يجب أن تحدد الاستراتيجية أهمية وأهداف الأمن السيبراني، ومستوى النضج الحالي والمستهدف، والمبادرات وخطة العمل لسد الفجوات، والموارد والميزانية المطلوبة.', null, 'governance', 'medium', 'paraphrased', false, 60),
  ('3.1.3', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.3 Cyber Security Policy', '3.1.3 سياسة الأمن السيبراني', 'Define and maintain a cyber security policy', 'تحديد سياسة الأمن السيبراني والمحافظة عليها', 'A cyber security policy must be defined, approved by the board, communicated to staff and third parties, and periodically reviewed, supported by detailed standards and procedures.', 'يجب تحديد سياسة للأمن السيبراني واعتمادها من مجلس الإدارة وإبلاغها للموظفين والأطراف الخارجية ومراجعتها دورياً، مدعومة بمعايير وإجراءات تفصيلية.', null, 'governance', 'high', 'paraphrased', false, 70),
  ('3.1.3.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.3 Cyber Security Policy', '3.1.3 سياسة الأمن السيبراني', 'Policy scope and content', 'نطاق ومحتوى السياسة', 'The policy must cover the organization''s cyber security objectives and scope, ownership and roles, compliance obligations, and consequences of non-compliance, and must be consistent with SAMA CSF and relevant laws.', 'يجب أن تغطي السياسة أهداف ونطاق الأمن السيبراني، والملكية والأدوار، والتزامات الامتثال، وعواقب عدم الالتزام، وأن تتوافق مع إطار ساما والأنظمة ذات العلاقة.', null, 'governance', 'medium', 'paraphrased', false, 80),
  ('3.1.4', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.4 Cyber Security Roles and Responsibilities', '3.1.4 أدوار ومسؤوليات الأمن السيبراني', 'Define cyber security roles and responsibilities', 'تحديد أدوار ومسؤوليات الأمن السيبراني', 'Responsibilities for cyber security must be defined and allocated across the board, senior management, the cyber security function, business owners, IT and all staff, and documented in a RACI.', 'يجب تحديد مسؤوليات الأمن السيبراني وتوزيعها على مجلس الإدارة والإدارة العليا ووظيفة الأمن السيبراني ومالكي الأعمال وتقنية المعلومات وجميع الموظفين، وتوثيقها في مصفوفة مسؤوليات.', null, 'governance', 'high', 'paraphrased', false, 90),
  ('3.1.4.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.4 Cyber Security Roles and Responsibilities', '3.1.4 أدوار ومسؤوليات الأمن السيبراني', 'CISO responsibilities', 'مسؤوليات رئيس أمن المعلومات', 'The CISO is responsible for developing and maintaining the cyber security strategy, policy, architecture, risk management, awareness, incident management and reporting to the committee and board.', 'يتولى رئيس أمن المعلومات مسؤولية تطوير وصيانة استراتيجية وسياسة وبنية الأمن السيبراني وإدارة المخاطر والتوعية وإدارة الحوادث ورفع التقارير إلى اللجنة ومجلس الإدارة.', null, 'governance', 'medium', 'paraphrased', false, 100),
  ('3.1.5', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.5 Cyber Security in Project Management', '3.1.5 الأمن السيبراني في إدارة المشاريع', 'Integrate cyber security into project management', 'دمج الأمن السيبراني في إدارة المشاريع', 'Cyber security must be integrated into the project management methodology so that security requirements are defined, risk-assessed, implemented and tested before go-live for all projects involving information assets.', 'يجب دمج الأمن السيبراني في منهجية إدارة المشاريع بحيث تُحدد المتطلبات الأمنية وتُقيَّم مخاطرها وتُنفذ وتُختبر قبل الإطلاق لجميع المشاريع المتعلقة بالأصول المعلوماتية.', null, 'preventive', 'high', 'paraphrased', false, 110),
  ('3.1.5.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.5 Cyber Security in Project Management', '3.1.5 الأمن السيبراني في إدارة المشاريع', 'Security gates in the project lifecycle', 'بوابات أمنية في دورة حياة المشروع', 'Projects must include cyber security involvement at initiation, a risk assessment, definition of security requirements, security review of design, security testing, and formal cyber security sign-off before production.', 'يجب أن تتضمن المشاريع مشاركة الأمن السيبراني عند البدء، وتقييم المخاطر، وتحديد المتطلبات الأمنية، ومراجعة أمنية للتصميم، واختبار الأمن، واعتماداً رسمياً من الأمن السيبراني قبل الإنتاج.', null, 'preventive', 'medium', 'paraphrased', false, 120),
  ('3.1.6', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.6 Cyber Security Awareness', '3.1.6 التوعية بالأمن السيبراني', 'Cyber security awareness program', 'برنامج التوعية بالأمن السيبراني', 'A cyber security awareness program must be defined, approved and conducted for staff, third parties and customers to promote awareness of cyber security responsibilities and threats.', 'يجب تحديد واعتماد وتنفيذ برنامج للتوعية بالأمن السيبراني للموظفين والأطراف الخارجية والعملاء لتعزيز الوعي بمسؤوليات الأمن السيبراني وتهديداته.', null, 'preventive', 'medium', 'paraphrased', false, 130),
  ('3.1.6.1', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.6 Cyber Security Awareness', '3.1.6 التوعية بالأمن السيبراني', 'Awareness targeting and measurement', 'استهداف التوعية وقياسها', 'Awareness content must be tailored to target groups (including new joiners, privileged users and customers), delivered through multiple channels, and its effectiveness measured and reported.', 'يجب تخصيص محتوى التوعية للفئات المستهدفة (بما في ذلك الموظفون الجدد والمستخدمون ذوو الصلاحيات والعملاء)، وتقديمه عبر قنوات متعددة، وقياس فاعليته ورفع التقارير عنها.', null, 'preventive', 'low', 'paraphrased', false, 140),
  ('3.1.7', 'Cyber Security Leadership and Governance', 'قيادة وحوكمة الأمن السيبراني', '3.1.7 Cyber Security Training', '3.1.7 التدريب على الأمن السيبراني', 'Cyber security training for staff', 'تدريب الموظفين على الأمن السيبراني', 'Staff must be provided with cyber security training appropriate to their role, with specialized training and certification for cyber security staff and relevant technical staff.', 'يجب تزويد الموظفين بتدريب على الأمن السيبراني يتناسب مع أدوارهم، مع تدريب متخصص وشهادات لموظفي الأمن السيبراني والموظفين التقنيين ذوي الصلة.', null, 'preventive', 'medium', 'paraphrased', false, 150),
  ('3.2.1', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.1 Cyber Security Risk Management', '3.2.1 إدارة مخاطر الأمن السيبراني', 'Cyber security risk management process', 'عملية إدارة مخاطر الأمن السيبراني', 'A cyber security risk management process, aligned with enterprise risk management, must be defined, approved and implemented to identify, analyze, respond to and monitor cyber security risks.', 'يجب تحديد واعتماد وتطبيق عملية لإدارة مخاطر الأمن السيبراني تتوافق مع إدارة المخاطر المؤسسية، لتحديد مخاطر الأمن السيبراني وتحليلها والاستجابة لها ومراقبتها.', null, 'governance', 'high', 'paraphrased', false, 160),
  ('3.2.1.1', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.1 Cyber Security Risk Management', '3.2.1 إدارة مخاطر الأمن السيبراني', 'Risk assessment triggers and scope', 'محفزات ونطاق تقييم المخاطر', 'Risk assessments must be performed periodically on all information assets and at key triggers (new systems, major changes, new third parties, new products or delivery channels).', 'يجب إجراء تقييمات المخاطر دورياً على جميع الأصول المعلوماتية وعند المحفزات الرئيسية (الأنظمة الجديدة، والتغييرات الجوهرية، والأطراف الخارجية الجديدة، والمنتجات أو قنوات التقديم الجديدة).', null, 'detective', 'high', 'paraphrased', false, 170),
  ('3.2.1.2', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.1 Cyber Security Risk Management', '3.2.1 إدارة مخاطر الأمن السيبراني', 'Risk register and treatment', 'سجل المخاطر ومعالجتها', 'Cyber security risks must be recorded in a risk register with owners, risk ratings, treatment decisions (mitigate, accept, transfer, avoid) and action plans, and reported to the cyber security committee.', 'يجب تسجيل مخاطر الأمن السيبراني في سجل مخاطر يتضمن المالكين وتصنيف المخاطر وقرارات المعالجة (التخفيف أو القبول أو النقل أو التجنب) وخطط العمل، ورفعها إلى لجنة الأمن السيبراني.', null, 'governance', 'high', 'paraphrased', false, 180),
  ('3.2.2', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.2 Regulatory Compliance', '3.2.2 الالتزام التنظيمي', 'Regulatory compliance process', 'عملية الالتزام التنظيمي', 'A process must be established to identify, monitor and ensure compliance with SAMA cyber security requirements and other applicable laws and regulations, with non-compliance tracked and reported.', 'يجب إنشاء عملية لتحديد ومراقبة وضمان الالتزام بمتطلبات الأمن السيبراني للبنك المركزي والأنظمة الأخرى المعمول بها، مع تتبع حالات عدم الالتزام ورفع التقارير عنها.', null, 'governance', 'high', 'paraphrased', false, 190),
  ('3.2.3', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.3 Compliance with (Inter)national Industry Standards', '3.2.3 الالتزام بالمعايير الصناعية الوطنية والدولية', 'Compliance with mandatory industry standards', 'الالتزام بالمعايير الصناعية الإلزامية', 'The organization must comply with mandatory (inter)national industry standards applicable to its services, such as PCI DSS for card payments and SWIFT Customer Security Programme for SWIFT users.', 'يجب على المؤسسة الالتزام بالمعايير الصناعية الوطنية والدولية الإلزامية المنطبقة على خدماتها، مثل PCI DSS لمدفوعات البطاقات وبرنامج أمن العملاء لسويفت لمستخدمي سويفت.', null, 'governance', 'high', 'paraphrased', false, 200),
  ('3.2.4', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.4 Cyber Security Review', '3.2.4 مراجعة الأمن السيبراني', 'Periodic cyber security reviews', 'المراجعات الدورية للأمن السيبراني', 'The cyber security function must periodically review compliance of business units, IT and third parties with the cyber security policy and standards, with findings tracked to closure.', 'يجب على وظيفة الأمن السيبراني مراجعة التزام وحدات الأعمال وتقنية المعلومات والأطراف الخارجية بسياسة ومعايير الأمن السيبراني دورياً، مع متابعة الملاحظات حتى إغلاقها.', null, 'detective', 'medium', 'paraphrased', false, 210),
  ('3.2.5', 'Cyber Security Risk Management and Compliance', 'إدارة مخاطر الأمن السيبراني والالتزام', '3.2.5 Cyber Security Audits', '3.2.5 تدقيق الأمن السيبراني', 'Independent cyber security audits', 'التدقيق المستقل للأمن السيبراني', 'Cyber security audits must be performed by an independent internal audit function or external auditor according to an approved audit plan, with results reported to the audit committee and remediation tracked.', 'يجب إجراء تدقيق الأمن السيبراني من قبل وظيفة مراجعة داخلية مستقلة أو مدقق خارجي وفق خطة تدقيق معتمدة، مع رفع النتائج إلى لجنة المراجعة ومتابعة المعالجة.', null, 'detective', 'high', 'paraphrased', false, 220),
  ('3.3.1', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.1 Human Resources', '3.3.1 الموارد البشرية', 'Cyber security in the HR lifecycle', 'الأمن السيبراني في دورة حياة الموارد البشرية', 'Cyber security requirements must be applied before, during and at termination of employment, including screening, contractual security obligations, confidentiality agreements, and timely revocation of access.', 'يجب تطبيق متطلبات الأمن السيبراني قبل وأثناء وعند انتهاء العلاقة الوظيفية، بما في ذلك التحقق من الخلفية والالتزامات الأمنية التعاقدية واتفاقيات السرية وإلغاء الصلاحيات في الوقت المناسب.', null, 'preventive', 'high', 'paraphrased', false, 230),
  ('3.3.2', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.2 Physical Security', '3.3.2 الأمن المادي', 'Physical protection of information assets', 'الحماية المادية للأصول المعلوماتية', 'Physical security controls must protect information assets and facilities (data centers, branches, ATMs, offices) from unauthorized access, damage and environmental threats, including access control, monitoring and secure disposal.', 'يجب أن تحمي ضوابط الأمن المادي الأصول المعلوماتية والمرافق (مراكز البيانات والفروع وأجهزة الصراف الآلي والمكاتب) من الوصول غير المصرح به والأضرار والتهديدات البيئية، بما في ذلك التحكم في الدخول والمراقبة والتخلص الآمن.', null, 'preventive', 'high', 'paraphrased', false, 240),
  ('3.3.3', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.3 Asset Management', '3.3.3 إدارة الأصول', 'Information asset management', 'إدارة الأصول المعلوماتية', 'An accurate inventory of information assets must be maintained with defined owners, classification according to an approved scheme, and handling requirements throughout the asset lifecycle.', 'يجب الاحتفاظ بجرد دقيق للأصول المعلوماتية مع تحديد المالكين وتصنيفها وفق آلية معتمدة ومتطلبات التعامل معها طوال دورة حياتها.', null, 'preventive', 'high', 'paraphrased', false, 250),
  ('3.3.4', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.4 Cyber Security Architecture', '3.3.4 بنية الأمن السيبراني', 'Cyber security architecture', 'بنية الأمن السيبراني', 'A cyber security architecture must be defined and maintained that describes security principles, standards and reference designs (defense-in-depth, segmentation, secure-by-design) and is applied to all new and changed systems.', 'يجب تحديد بنية للأمن السيبراني والمحافظة عليها تصف المبادئ والمعايير والتصاميم المرجعية الأمنية (الدفاع متعدد المستويات والعزل والأمن بالتصميم) وتُطبق على جميع الأنظمة الجديدة والمعدلة.', null, 'preventive', 'high', 'paraphrased', false, 260),
  ('3.3.5', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.5 Identity and Access Management', '3.3.5 إدارة الهوية والصلاحيات', 'Identity and access management', 'إدارة الهوية والصلاحيات', 'Access to information assets must be restricted to authorized users on a need-to-have basis through an approved identity and access management process covering the full user lifecycle.', 'يجب قصر الوصول إلى الأصول المعلوماتية على المستخدمين المصرح لهم وفق مبدأ الحاجة، من خلال عملية معتمدة لإدارة الهوية والصلاحيات تغطي دورة حياة المستخدم بالكامل.', null, 'preventive', 'high', 'paraphrased', false, 270),
  ('3.3.5.1', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.5 Identity and Access Management', '3.3.5 إدارة الهوية والصلاحيات', 'Authentication and privileged access', 'المصادقة والوصول المميز', 'Strong authentication (multi-factor) must be enforced for remote access, privileged access and sensitive systems; privileged accounts must be restricted, monitored and managed through privileged access management.', 'يجب فرض المصادقة القوية (متعددة العناصر) للوصول عن بُعد والوصول المميز والأنظمة الحساسة؛ ويجب تقييد الحسابات المميزة ومراقبتها وإدارتها من خلال إدارة الوصول المميز.', null, 'preventive', 'high', 'paraphrased', false, 280),
  ('3.3.5.2', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.5 Identity and Access Management', '3.3.5 إدارة الهوية والصلاحيات', 'Access reviews and segregation of duties', 'مراجعة الصلاحيات وفصل المهام', 'User access rights must be reviewed periodically by asset owners, segregation of duties enforced, and access revoked immediately on role change or termination.', 'يجب مراجعة صلاحيات المستخدمين دورياً من قبل مالكي الأصول، وفرض فصل المهام، وإلغاء الصلاحيات فوراً عند تغيير الدور أو انتهاء العلاقة.', null, 'detective', 'high', 'paraphrased', false, 290),
  ('3.3.6', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.6 Application Security', '3.3.6 أمن التطبيقات', 'Application security', 'أمن التطبيقات', 'Applications must be developed, acquired and maintained with security requirements addressed throughout the lifecycle, including secure coding, input validation, authentication, session management, logging and security testing before release.', 'يجب تطوير التطبيقات واقتناؤها وصيانتها مع معالجة المتطلبات الأمنية طوال دورة الحياة، بما في ذلك البرمجة الآمنة والتحقق من المدخلات والمصادقة وإدارة الجلسات والتسجيل واختبار الأمن قبل الإطلاق.', null, 'preventive', 'high', 'paraphrased', false, 300),
  ('3.3.7', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.7 Change Management', '3.3.7 إدارة التغيير', 'Secure change management', 'إدارة التغيير الآمنة', 'Changes to information assets must follow a formal change management process with cyber security risk assessment, approval, testing, segregation of environments, and rollback procedures.', 'يجب أن تتبع التغييرات على الأصول المعلوماتية عملية رسمية لإدارة التغيير تتضمن تقييم مخاطر الأمن السيبراني والاعتماد والاختبار وفصل البيئات وإجراءات التراجع.', null, 'preventive', 'high', 'paraphrased', false, 310),
  ('3.3.8', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.8 Infrastructure Security', '3.3.8 أمن البنية التحتية', 'Infrastructure security', 'أمن البنية التحتية', 'Infrastructure components (networks, servers, endpoints, databases, wireless, remote access) must be protected through hardening baselines, segmentation, malware protection, patching, secure configuration and monitoring.', 'يجب حماية مكونات البنية التحتية (الشبكات والخوادم والأجهزة الطرفية وقواعد البيانات والشبكات اللاسلكية والوصول عن بُعد) من خلال خطوط أساس التحصين والعزل والحماية من البرمجيات الضارة والتحديثات والإعدادات الآمنة والمراقبة.', null, 'preventive', 'high', 'paraphrased', false, 320),
  ('3.3.8.1', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.8 Infrastructure Security', '3.3.8 أمن البنية التحتية', 'Network protection and segmentation', 'حماية الشبكات وعزلها', 'Networks must be segmented by security zones with firewalls, intrusion detection/prevention, DDoS protection and restricted internet connectivity; wireless networks must use strong encryption and authentication.', 'يجب عزل الشبكات إلى مناطق أمنية بجدران حماية وأنظمة كشف ومنع الاختراق والحماية من هجمات حجب الخدمة وتقييد الاتصال بالإنترنت؛ ويجب أن تستخدم الشبكات اللاسلكية تشفيراً ومصادقة قويين.', null, 'preventive', 'high', 'paraphrased', false, 330),
  ('3.3.8.2', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.8 Infrastructure Security', '3.3.8 أمن البنية التحتية', 'Endpoint and server hardening', 'تحصين الأجهزة الطرفية والخوادم', 'Servers and endpoints must be hardened against approved baselines, protected by centrally managed anti-malware, patched within defined timelines, and restricted from unauthorized software and removable media.', 'يجب تحصين الخوادم والأجهزة الطرفية وفق خطوط أساس معتمدة، وحمايتها ببرامج مكافحة البرمجيات الضارة المدارة مركزياً، وتحديثها ضمن مدد محددة، وتقييد البرمجيات غير المصرح بها والوسائط القابلة للإزالة.', null, 'preventive', 'high', 'paraphrased', false, 340),
  ('3.3.9', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.9 Cryptography', '3.3.9 التشفير', 'Cryptography and key management', 'التشفير وإدارة المفاتيح', 'Approved cryptographic algorithms and key lengths must protect sensitive data at rest and in transit, with keys managed securely across generation, distribution, storage, rotation and destruction, using HSMs where appropriate.', 'يجب استخدام خوارزميات تشفير وأطوال مفاتيح معتمدة لحماية البيانات الحساسة أثناء التخزين والنقل، مع إدارة المفاتيح بشكل آمن عبر التوليد والتوزيع والتخزين والتدوير والإتلاف، واستخدام وحدات الأمن المادية عند الاقتضاء.', null, 'preventive', 'high', 'paraphrased', false, 350),
  ('3.3.10', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.10 Bring Your Own Device (BYOD)', '3.3.10 استخدام الأجهزة الشخصية', 'BYOD security', 'أمن الأجهزة الشخصية', 'Where personal devices are permitted, a BYOD policy must require device registration, mobile device management, containerization and encryption of organizational data, remote wipe, and restrictions on jailbroken devices.', 'عند السماح بالأجهزة الشخصية، يجب أن تشترط سياسة الأجهزة الشخصية تسجيل الجهاز وإدارة الأجهزة المحمولة وفصل بيانات المؤسسة وتشفيرها والمسح عن بُعد وحظر الأجهزة المكسورة الحماية.', null, 'preventive', 'medium', 'paraphrased', false, 360),
  ('3.3.11', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.11 Secure Disposal of Information Assets', '3.3.11 التخلص الآمن من الأصول المعلوماتية', 'Secure disposal', 'التخلص الآمن', 'Information assets and media must be securely disposed of or sanitized according to classification when no longer required, with disposal recorded and certified.', 'يجب التخلص من الأصول المعلوماتية والوسائط أو مسحها بشكل آمن وفق تصنيفها عند انتفاء الحاجة إليها، مع تسجيل عملية التخلص وتوثيقها بشهادات.', null, 'preventive', 'medium', 'paraphrased', false, 370),
  ('3.3.12', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.12 Payment Systems', '3.3.12 أنظمة الدفع', 'Payment systems security', 'أمن أنظمة الدفع', 'Payment systems (SWIFT, SARIE, mada, card systems, ATMs, POS) must be protected with dedicated controls including segregation, strong authentication, transaction monitoring, fraud detection and compliance with applicable scheme standards.', 'يجب حماية أنظمة الدفع (سويفت وسريع ومدى وأنظمة البطاقات والصراف الآلي ونقاط البيع) بضوابط مخصصة تشمل العزل والمصادقة القوية ومراقبة المعاملات وكشف الاحتيال والالتزام بمعايير شبكات الدفع المعمول بها.', null, 'preventive', 'high', 'paraphrased', false, 380),
  ('3.3.13', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.13 Electronic Banking Services', '3.3.13 الخدمات المصرفية الإلكترونية', 'Electronic banking services security', 'أمن الخدمات المصرفية الإلكترونية', 'Online, mobile and other electronic channels must implement multi-factor customer authentication, transaction verification and limits, secure session handling, fraud monitoring, customer security awareness and secure application development.', 'يجب أن تطبق القنوات الإلكترونية عبر الإنترنت والهاتف المحمول وغيرها مصادقة العملاء متعددة العناصر والتحقق من المعاملات وحدودها والتعامل الآمن مع الجلسات ومراقبة الاحتيال وتوعية العملاء والتطوير الآمن للتطبيقات.', null, 'preventive', 'high', 'paraphrased', false, 390),
  ('3.3.14', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.14 Cyber Security Event Management', '3.3.14 إدارة أحداث الأمن السيبراني', 'Security event logging and monitoring', 'تسجيل ومراقبة الأحداث الأمنية', 'Security events from critical systems must be logged, centrally collected, correlated and monitored 24/7 through a security operations capability, with logs protected and retained per regulatory requirements.', 'يجب تسجيل الأحداث الأمنية من الأنظمة الحساسة وتجميعها مركزياً وربطها ومراقبتها على مدار الساعة من خلال قدرة عمليات أمنية، مع حماية السجلات والاحتفاظ بها وفق المتطلبات التنظيمية.', null, 'detective', 'high', 'paraphrased', false, 400),
  ('3.3.15', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.15 Cyber Security Incident Management', '3.3.15 إدارة حوادث الأمن السيبراني', 'Cyber security incident management', 'إدارة حوادث الأمن السيبراني', 'An incident management process must be established covering detection, classification, response, containment, eradication, recovery, forensics and lessons learned, with defined roles and a tested incident response plan.', 'يجب إنشاء عملية لإدارة الحوادث تغطي الاكتشاف والتصنيف والاستجابة والاحتواء والاستئصال والتعافي والتحليل الجنائي والدروس المستفادة، مع أدوار محددة وخطة استجابة مختبرة.', null, 'corrective', 'high', 'paraphrased', false, 410),
  ('3.3.15.1', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.15 Cyber Security Incident Management', '3.3.15 إدارة حوادث الأمن السيبراني', 'SAMA incident reporting', 'الإبلاغ عن الحوادث للبنك المركزي', 'Medium and high severity cyber security incidents must be reported to SAMA within the timelines SAMA prescribes, with follow-up reports on root cause and remediation.', 'يجب إبلاغ البنك المركزي بحوادث الأمن السيبراني متوسطة وعالية الخطورة ضمن المدد التي يحددها، مع تقارير متابعة عن السبب الجذري والمعالجة.', null, 'corrective', 'high', 'paraphrased', false, 420),
  ('3.3.16', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.16 Threat Management', '3.3.16 إدارة التهديدات', 'Threat intelligence and management', 'معلومات التهديدات وإدارتها', 'A threat management process must collect, analyze and act on threat intelligence from internal and external sources (including SAMA and sector sharing platforms) to anticipate and mitigate emerging threats.', 'يجب إنشاء عملية لإدارة التهديدات تجمع وتحلل معلومات التهديدات من مصادر داخلية وخارجية (بما في ذلك البنك المركزي ومنصات التبادل القطاعية) وتتخذ إجراءات بشأنها لاستباق التهديدات الناشئة والتخفيف منها.', null, 'detective', 'medium', 'paraphrased', false, 430),
  ('3.3.17', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.17 Vulnerability Management', '3.3.17 إدارة الثغرات', 'Vulnerability management', 'إدارة الثغرات', 'Technical vulnerabilities must be identified through regular scanning and penetration testing, classified by risk, and remediated within defined timelines, with exceptions formally approved and tracked.', 'يجب تحديد الثغرات التقنية من خلال الفحص الدوري واختبارات الاختراق، وتصنيفها حسب المخاطر، ومعالجتها ضمن مدد محددة، مع اعتماد الاستثناءات رسمياً وتتبعها.', null, 'detective', 'high', 'paraphrased', false, 440),
  ('3.3.17.1', 'Cyber Security Operations and Technology', 'عمليات وتقنية الأمن السيبراني', '3.3.17 Vulnerability Management', '3.3.17 إدارة الثغرات', 'Penetration testing of critical and internet-facing systems', 'اختبار اختراق الأنظمة الحساسة والمتصلة بالإنترنت', 'Penetration tests must be performed at least annually and after major changes on internet-facing and critical systems by qualified independent testers.', 'يجب إجراء اختبارات الاختراق سنوياً على الأقل وبعد التغييرات الجوهرية على الأنظمة المتصلة بالإنترنت والأنظمة الحساسة من قبل مختبرين مستقلين مؤهلين.', null, 'detective', 'high', 'paraphrased', false, 450),
  ('3.4.1', 'Third Party Cyber Security', 'الأمن السيبراني للأطراف الخارجية', '3.4.1 Contract and Vendor Management', '3.4.1 إدارة العقود والموردين', 'Contract and vendor management', 'إدارة العقود والموردين', 'Cyber security requirements must be embedded in vendor selection, due diligence, contracts (including right to audit, incident notification, confidentiality and data return/destruction) and ongoing monitoring of third parties.', 'يجب تضمين متطلبات الأمن السيبراني في اختيار الموردين والعناية الواجبة والعقود (بما في ذلك حق التدقيق والإبلاغ عن الحوادث والسرية وإعادة البيانات أو إتلافها) والمراقبة المستمرة للأطراف الخارجية.', null, 'preventive', 'high', 'paraphrased', false, 460),
  ('3.4.2', 'Third Party Cyber Security', 'الأمن السيبراني للأطراف الخارجية', '3.4.2 Outsourcing', '3.4.2 الإسناد الخارجي', 'Outsourcing cyber security', 'الأمن السيبراني في الإسناد الخارجي', 'Outsourcing arrangements must comply with SAMA outsourcing rules, include a cyber security risk assessment before contracting, define security obligations and SLAs, and preserve the organization''s accountability and SAMA''s access rights.', 'يجب أن تلتزم ترتيبات الإسناد الخارجي بقواعد البنك المركزي للإسناد، وأن تتضمن تقييم مخاطر الأمن السيبراني قبل التعاقد، وتحديد الالتزامات الأمنية ومستويات الخدمة، مع الحفاظ على مسؤولية المؤسسة وحقوق وصول البنك المركزي.', null, 'governance', 'high', 'paraphrased', false, 470),
  ('3.4.3', 'Third Party Cyber Security', 'الأمن السيبراني للأطراف الخارجية', '3.4.3 Cloud Computing', '3.4.3 الحوسبة السحابية', 'Cloud computing security', 'أمن الحوسبة السحابية', 'Use of cloud services must be risk-assessed and approved, with data classification, data residency within the Kingdom for sensitive data, tenant isolation, encryption, provider security assurance, exit strategy and SAMA non-objection where required.', 'يجب تقييم مخاطر استخدام الخدمات السحابية واعتمادها، مع تصنيف البيانات وبقاء البيانات الحساسة داخل المملكة وعزل المستأجرين والتشفير وتأكيد أمن مقدم الخدمة واستراتيجية الخروج والحصول على عدم ممانعة البنك المركزي عند الاقتضاء.', null, 'governance', 'high', 'paraphrased', false, 480)
) as c(control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
where f.code = 'SAMA-CSF'
on conflict (framework_id, control_ref) do update set
  domain_en = excluded.domain_en, domain_ar = excluded.domain_ar,
  subdomain_en = excluded.subdomain_en, subdomain_ar = excluded.subdomain_ar,
  title_en = excluded.title_en, title_ar = excluded.title_ar,
  requirement_en = excluded.requirement_en, requirement_ar = excluded.requirement_ar,
  evidence_en = excluded.evidence_en, control_type = excluded.control_type,
  criticality = excluded.criticality, fidelity = excluded.fidelity,
  verified = excluded.verified, sort_order = excluded.sort_order;

-- ---------------------------------------------------------------------------
-- UAE-IAS: UAE Information Assurance Standards (NESA / Cybersecurity Council) (27 controls)
-- ---------------------------------------------------------------------------
insert into public.frameworks (code, short_name, name_en, name_ar, regulator_en, regulator_ar, jurisdiction, category, version, effective_date, source_url, description_en, description_ar, mandatory, sort_order)
values ('UAE-IAS', 'UAE IA Standards', 'UAE Information Assurance Standards (NESA / Cybersecurity Council)', 'معايير ضمان المعلومات لدولة الإمارات (الهيئة الوطنية للأمن الإلكتروني / مجلس الأمن السيبراني)', 'UAE Cybersecurity Council (formerly NESA / SIA); referenced by CBUAE for financial institutions', 'مجلس الأمن السيبراني لدولة الإمارات (سابقاً الهيئة الوطنية للأمن الإلكتروني)؛ يشير إليه مصرف الإمارات المركزي للمؤسسات المالية', 'AE', 'information-security', '1.1', '2014-03-01', 'https://www.tdra.gov.ae/en/about-tdra/information-and-egovernment-sector/national-cybersecurity', 'The UAE''s national baseline for information assurance, mandatory for critical-infrastructure and government entities and referenced by the Central Bank of the UAE for banks and financial institutions. 188 controls across 6 management (M1–M6) and 9 technical (T1–T9) families, each tagged with a priority (P1–P4). Rows below are at control-family level with summarized requirements; verify against the licensed standard before formal use.', 'خط الأساس الوطني لضمان المعلومات في دولة الإمارات، إلزامي للجهات الحكومية والبنية التحتية الحرجة ويشير إليه مصرف الإمارات المركزي للبنوك والمؤسسات المالية. 188 ضابطاً موزعة على 6 عائلات إدارية (M1–M6) و9 عائلات تقنية (T1–T9)، لكل منها أولوية (P1–P4). الصفوف أدناه على مستوى عائلة الضوابط بمتطلبات ملخصة؛ يجب التحقق منها مقابل المعيار المرخص قبل الاستخدام الرسمي.', true, 40)
on conflict (code) do update set
  short_name = excluded.short_name, name_en = excluded.name_en, name_ar = excluded.name_ar,
  regulator_en = excluded.regulator_en, regulator_ar = excluded.regulator_ar, jurisdiction = excluded.jurisdiction,
  category = excluded.category, version = excluded.version, effective_date = excluded.effective_date,
  source_url = excluded.source_url, description_en = excluded.description_en, description_ar = excluded.description_ar,
  mandatory = excluded.mandatory, sort_order = excluded.sort_order;

insert into public.controls (framework_id, control_ref, domain_en, domain_ar, subdomain_en, subdomain_ar, title_en, title_ar, requirement_en, requirement_ar, evidence_en, control_type, criticality, fidelity, verified, sort_order)
select f.id, c.* from public.frameworks f
cross join (values
  ('M1.1', 'Management Controls', 'الضوابط الإدارية', 'M1 Strategy and Planning', 'M1 الاستراتيجية والتخطيط', 'Information security strategy and program', 'استراتيجية وبرنامج أمن المعلومات', 'Establish an information security program with a documented strategy, management commitment, defined scope, resources and a roadmap aligned to the national IA framework and the entity''s risk profile.', 'إنشاء برنامج لأمن المعلومات باستراتيجية موثقة والتزام من الإدارة ونطاق محدد وموارد وخطة عمل متوافقة مع الإطار الوطني لضمان المعلومات وملف مخاطر الجهة.', null, 'governance', 'high', 'summarized', false, 10),
  ('M1.2', 'Management Controls', 'الضوابط الإدارية', 'M1 Strategy and Planning', 'M1 الاستراتيجية والتخطيط', 'Information security policy and organization', 'سياسة وتنظيم أمن المعلومات', 'Approve and publish an information security policy, establish an information security function with a designated senior officer, and define governance committees and reporting lines.', 'اعتماد ونشر سياسة أمن المعلومات، وإنشاء وظيفة لأمن المعلومات بمسؤول رفيع المستوى، وتحديد لجان الحوكمة وخطوط الإبلاغ.', null, 'governance', 'high', 'summarized', false, 20),
  ('M1.3', 'Management Controls', 'الضوابط الإدارية', 'M1 Strategy and Planning', 'M1 الاستراتيجية والتخطيط', 'Roles, responsibilities and segregation', 'الأدوار والمسؤوليات وفصل المهام', 'Define and allocate information security roles and responsibilities across management, asset owners, custodians and users, applying segregation of duties.', 'تحديد وتوزيع أدوار ومسؤوليات أمن المعلومات على الإدارة ومالكي الأصول والمشرفين عليها والمستخدمين مع تطبيق فصل المهام.', null, 'governance', 'medium', 'summarized', false, 30),
  ('M2.1', 'Management Controls', 'الضوابط الإدارية', 'M2 Information Security Risk Management', 'M2 إدارة مخاطر أمن المعلومات', 'Risk management methodology', 'منهجية إدارة المخاطر', 'Adopt a documented risk assessment and treatment methodology consistent with the national IA risk management guidance, including criteria for risk acceptance.', 'اعتماد منهجية موثقة لتقييم المخاطر ومعالجتها تتوافق مع التوجيهات الوطنية لإدارة مخاطر ضمان المعلومات، بما في ذلك معايير قبول المخاطر.', null, 'governance', 'high', 'summarized', false, 40),
  ('M2.2', 'Management Controls', 'الضوابط الإدارية', 'M2 Information Security Risk Management', 'M2 إدارة مخاطر أمن المعلومات', 'Risk assessment and treatment', 'تقييم المخاطر ومعالجتها', 'Perform risk assessments on information assets at planned intervals and upon significant change, select and implement controls to treat risks, and maintain a risk register and statement of applicability.', 'إجراء تقييمات المخاطر على الأصول المعلوماتية على فترات مخططة وعند التغييرات الجوهرية، واختيار وتنفيذ الضوابط لمعالجة المخاطر، والاحتفاظ بسجل المخاطر وبيان قابلية التطبيق.', null, 'governance', 'high', 'summarized', false, 50),
  ('M3.1', 'Management Controls', 'الضوابط الإدارية', 'M3 Awareness and Training', 'M3 التوعية والتدريب', 'Security awareness program', 'برنامج التوعية الأمنية', 'Deliver an ongoing security awareness program to all personnel and contractors, with role-based training for privileged and security staff, and measure effectiveness.', 'تقديم برنامج مستمر للتوعية الأمنية لجميع العاملين والمتعاقدين، مع تدريب حسب الدور للموظفين ذوي الصلاحيات وموظفي الأمن، وقياس الفاعلية.', null, 'preventive', 'medium', 'summarized', false, 60),
  ('M4.1', 'Management Controls', 'الضوابط الإدارية', 'M4 Human Resources Security', 'M4 أمن الموارد البشرية', 'Pre-employment screening and terms', 'التحقق قبل التوظيف وشروط العمل', 'Screen candidates proportionate to the sensitivity of the role, and include information security responsibilities and confidentiality obligations in employment terms.', 'التحقق من المرشحين بما يتناسب مع حساسية الدور، وتضمين مسؤوليات أمن المعلومات والتزامات السرية في شروط العمل.', null, 'preventive', 'medium', 'summarized', false, 70),
  ('M4.2', 'Management Controls', 'الضوابط الإدارية', 'M4 Human Resources Security', 'M4 أمن الموارد البشرية', 'During employment and termination', 'أثناء العمل وعند الإنهاء', 'Enforce security responsibilities during employment through a disciplinary process, and on termination or change of role return assets and revoke access promptly.', 'إنفاذ المسؤوليات الأمنية أثناء العمل من خلال إجراءات تأديبية، وعند الإنهاء أو تغيير الدور إعادة الأصول وإلغاء الصلاحيات فوراً.', null, 'preventive', 'medium', 'summarized', false, 80),
  ('M5.1', 'Management Controls', 'الضوابط الإدارية', 'M5 Compliance', 'M5 الامتثال', 'Legal and regulatory compliance', 'الامتثال القانوني والتنظيمي', 'Identify applicable legal, regulatory and contractual requirements (including UAE federal laws on cybercrime and data protection) and demonstrate compliance through periodic reviews and independent audits.', 'تحديد المتطلبات القانونية والتنظيمية والتعاقدية المعمول بها (بما في ذلك القوانين الاتحادية للجرائم الإلكترونية وحماية البيانات) وإثبات الامتثال من خلال المراجعات الدورية والتدقيق المستقل.', null, 'governance', 'high', 'summarized', false, 90),
  ('M5.2', 'Management Controls', 'الضوابط الإدارية', 'M5 Compliance', 'M5 الامتثال', 'Compliance with the IA Standards', 'الامتثال لمعايير ضمان المعلومات', 'Perform self-assessments against the IA Standards, report compliance status to the national authority as required, and remediate gaps according to priority (P1 first).', 'إجراء تقييمات ذاتية مقابل معايير ضمان المعلومات، ورفع حالة الامتثال إلى الجهة الوطنية حسب المطلوب، ومعالجة الفجوات وفق الأولوية (P1 أولاً).', null, 'detective', 'high', 'summarized', false, 100),
  ('M6.1', 'Management Controls', 'الضوابط الإدارية', 'M6 Performance Evaluation and Improvement', 'M6 تقييم الأداء والتحسين', 'Monitoring, measurement and improvement', 'المراقبة والقياس والتحسين', 'Define security metrics, monitor and measure control effectiveness, conduct management reviews and internal audits, and drive corrective and preventive actions.', 'تحديد مقاييس الأمن، ومراقبة وقياس فاعلية الضوابط، وإجراء مراجعات الإدارة والتدقيق الداخلي، ودفع الإجراءات التصحيحية والوقائية.', null, 'detective', 'medium', 'summarized', false, 110),
  ('T1.1', 'Technical Controls', 'الضوابط التقنية', 'T1 Asset Management', 'T1 إدارة الأصول', 'Asset inventory and ownership', 'جرد الأصول وملكيتها', 'Maintain an inventory of information assets with assigned owners and acceptable use rules.', 'الاحتفاظ بجرد للأصول المعلوماتية مع تحديد المالكين وقواعد الاستخدام المقبول.', null, 'preventive', 'high', 'summarized', false, 120),
  ('T1.2', 'Technical Controls', 'الضوابط التقنية', 'T1 Asset Management', 'T1 إدارة الأصول', 'Information classification and handling', 'تصنيف المعلومات والتعامل معها', 'Classify and label information according to the national classification scheme and define handling, storage, transfer and disposal procedures per classification.', 'تصنيف المعلومات ووسمها وفق آلية التصنيف الوطنية وتحديد إجراءات التعامل والتخزين والنقل والتخلص لكل تصنيف.', null, 'preventive', 'high', 'summarized', false, 130),
  ('T2.1', 'Technical Controls', 'الضوابط التقنية', 'T2 Physical and Environmental Security', 'T2 الأمن المادي والبيئي', 'Secure areas and equipment protection', 'المناطق الآمنة وحماية المعدات', 'Protect facilities and equipment with physical perimeters, entry controls, monitoring, environmental protection and secure disposal of equipment.', 'حماية المرافق والمعدات بمحيطات مادية وضوابط دخول ومراقبة وحماية بيئية وتخلص آمن من المعدات.', null, 'preventive', 'medium', 'summarized', false, 140),
  ('T3.1', 'Technical Controls', 'الضوابط التقنية', 'T3 Operations Management', 'T3 إدارة العمليات', 'Operational procedures and change management', 'إجراءات التشغيل وإدارة التغيير', 'Document operating procedures, control changes to systems, and separate development, test and production environments.', 'توثيق إجراءات التشغيل، والتحكم في التغييرات على الأنظمة، وفصل بيئات التطوير والاختبار والإنتاج.', null, 'preventive', 'high', 'summarized', false, 150),
  ('T3.2', 'Technical Controls', 'الضوابط التقنية', 'T3 Operations Management', 'T3 إدارة العمليات', 'Malware protection and patching', 'الحماية من البرمجيات الضارة والتحديثات', 'Deploy and maintain anti-malware on all systems and apply security patches within defined timeframes based on criticality.', 'نشر وصيانة الحماية من البرمجيات الضارة على جميع الأنظمة وتطبيق التحديثات الأمنية ضمن مدد محددة حسب الأهمية.', null, 'preventive', 'high', 'summarized', false, 160),
  ('T3.3', 'Technical Controls', 'الضوابط التقنية', 'T3 Operations Management', 'T3 إدارة العمليات', 'Backup', 'النسخ الاحتياطي', 'Back up information and software regularly, protect backups and test restoration periodically.', 'النسخ الاحتياطي للمعلومات والبرمجيات بانتظام، وحماية النسخ، واختبار الاستعادة دورياً.', null, 'corrective', 'high', 'summarized', false, 170),
